window.CS50KZ_QUIZ = [{"q":"Екілік жүйедегі <code>101</code> ондық жүйеде қандай сан?","o":["101","3","5","6"],"a":2,"e":"4×1 + 2×0 + 1×1 = 5.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"8 битпен (1 байт) неше түрлі мән беруге болады?","o":["255","256","8","128"],"a":1,"e":"2⁸ = 256 мән: 0-ден 255-ке дейін.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"ASCII-де 72, 73, 33 сандары нені білдіреді?","o":["HI!","hi!","BOW","Күңгірт сары түс"],"a":0,"e":"72 = H, 73 = I, 33 = !. Photoshop-та ашсақ, дәл осы сандар күңгірт сары түс болар еді. Бәрі контекстке байланысты, бірақ ASCII бойынша жауап - HI!.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"Бас әріпті кіші әріпке айналдыру үшін ASCII кодына не істеу керек?","o":["1 қосу","2-ге көбейту","65 алу","32 қосу (32-нің орнындағы битті 1 ету)"],"a":3,"e":"Мысалы, A = 65, a = 97, айырмасы 32.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"1000 беттік телефон кітабы 2000 бетке ұлғайса, «ортасынан бөлу» алгоритміне неше қадам қосылады?","o":["1000","Шамамен 1","500","Екі есе көп"],"a":1,"e":"Бір рет жыртқанда 2000 бет 1000 бетке түседі. Бұл log₂ n алгоритмінің артықшылығы.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"Scratch-тағы «ask ... and wait» блогының <code>answer</code> айнымалысы нені білдіреді?","o":["Жанама әсерді","Циклді","Қайтарылатын мәнді","Логикалық өрнекті"],"a":2,"e":"«ask» функциясы адам енгізген жауапты бағдарламаға қайтарады, ол answer айнымалысында сақталады.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"«if touching mouse pointer» блогы «forever» ішінде болмаса, мысық неге мияуламайды?","o":["Шарт тек бір рет, жасыл ту басылған сәтте ғана тексеріледі","Дыбыс қосылмаған","Мысық спрайты жоқ","«if» блогы Scratch-та жұмыс істемейді"],"a":0,"e":"Бағдарлама өте жылдам орындалып қойды. «forever» шартты үнемі тексеріп отыруды қамтамасыз етеді.","l":"0-апта: Scratch","u":"lectures/week-0.html#quiz"},{"q":"hello.c файлын өзгерттіңіз. Өзгерісті көру үшін не істеу керек?","o":["Бірден <code>./hello</code> іске қосу","Алдымен <code>make hello</code>, сосын <code>./hello</code>","<code>code hello.c</code> қайта жазу","Ештеңе, өзгеріс автоматты түрде көрінеді"],"a":1,"e":"Бастапқы код өзгерсе, жаңа машиналық код алу үшін қайта компиляциялау керек.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"<code>if (x = y)</code> мен <code>if (x == y)</code> айырмашылығы неде?","o":["Айырмашылығы жоқ","Біріншісі салыстырады, екіншісі меншіктейді","Біріншісі меншіктейді, екіншісі салыстырады","Екеуі де қате"],"a":2,"e":"<code>=</code> меншіктеу, <code>==</code> теңдікті салыстыру.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"<code>printf(\"%i\\n\", 7 / 2);</code> не шығарады?","o":["3","3.5","4","Қате береді"],"a":0,"e":"Бүтін санды бүтін санға бөлгенде кесу (truncation) болады: 3,5 → 3.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"<code>7 % 3</code> нәтижесі қандай?","o":["2.33","2","0","1"],"a":3,"e":"7 = 3 × 2 + 1, қалдығы 1.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"Кірісті кем дегенде бір рет сұрап, қате болса қайта сұрау үшін қай цикл ең ыңғайлы?","o":["<code>for</code>","<code>do-while</code>","<code>while</code>","Цикл керек емес"],"a":1,"e":"do-while шартты соңында тексереді, сондықтан денесі кем дегенде бір рет орындалады.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"Функцияны <code>main</code>-нен кейін анықтасаңыз, не қосу керек?","o":["Түсініктеме","<code>#include &lt;cs50.h&gt;</code>","<code>main</code>-нің үстіне функцияның прототипін","Ештеңе"],"a":2,"e":"Компилятор кодты жоғарыдан төменге оқиды, сондықтан прототип оған функцияның кейін болатынын алдын ала айтады.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"32 биттік <code>int</code>-ке тым үлкен мән сақтасақ не болады?","o":["Бүтін сан толып кетеді, нәтиже теріс не 0 болуы мүмкін","Компьютер автоматты түрде 64 битке көшеді","Бағдарлама әрқашан компиляцияланбайды","Мән дөңгелектенеді"],"a":0,"e":"Бұл integer overflow. Boeing 787 және Pac-Man мысалдарын еске түсіріңіз.","l":"1-апта: C тілі","u":"lectures/week-1.html#quiz"},{"q":"<code>string s = \"CS50\";</code> жадта неше байт алады?","o":["3","4","5","8"],"a":2,"e":"4 таңба + соңындағы <code>\\0</code> (NUL) = 5 байт.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"<code>int a[5];</code> массивінің соңғы элементінің индексі қандай?","o":["4","5","6","0"],"a":0,"e":"Индекстер 0-ден басталады: 0, 1, 2, 3, 4.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"<code>./greet David Malan</code> командасында <code>argc</code> неге тең?","o":["1","2","4","3"],"a":3,"e":"<code>argv[0]</code> = \"./greet\", <code>argv[1]</code> = \"David\", <code>argv[2]</code> = \"Malan\", барлығы 3.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"«undefined reference to get_string ... linker command failed» қатесі қай кезеңде пайда болады?","o":["Алдын ала өңдеу","Байланыстыру","Ассемблерлеу","Орындалу уақытында"],"a":1,"e":"Компилятор сіздің кодыңызды CS50 кітапханасымен байланыстыра алмады. Шешімі: <code>-lcs50</code> не <code>make</code>.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"Бағдарлама сәтті аяқталғанда <code>main</code> әдетте не қайтарады?","o":["1","-1","0","404"],"a":2,"e":"Келісім бойынша 0 сәттілікті, ал басқа сандар қатені білдіреді.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"Цезарь шифрымен «ABC», кілт 2, нәтиже қандай?","o":["CDE","BCD","YZA","ABC"],"a":0,"e":"Әр әріп 2 орынға жылжиды.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"<code>for (int i = 0; i &lt; strlen(s); i++)</code> жолының жобалау мәселесі қандай?","o":["Ол компиляцияланбайды","<code>strlen</code> әр айналымда қайта шақырылады","Соңғы таңба өткізіліп кетеді","Мәселесі жоқ"],"a":1,"e":"Ұзындықты бір рет есептеп, айнымалыда сақтаған дұрыс: <code>for (int i = 0, n = strlen(s); i &lt; n; i++)</code>.","l":"2-апта: Массивтер","u":"lectures/week-2.html#quiz"},{"q":"1 000 000 сұрыпталған элементте екілік іздеу ең көп дегенде шамамен неше қадам жасайды?","o":["1 000 000","20","500 000","1000"],"a":1,"e":"log₂ 1 000 000 ≈ 20, себебі 2²⁰ ≈ 1 048 576.","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"O(3<em>n</em>² + 100<em>n</em> + 5) қалай жеңілдетіледі?","o":["O(3<em>n</em>²)","O(100<em>n</em>)","O(<em>n</em>)","O(<em>n</em>²)"],"a":3,"e":"Тек ең басым мүше қалады, тұрақты көбейткіштер елеусіз.","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Сұрыпталмаған массивке екілік іздеу неге жарамайды?","o":["«Сол жаққа ба, оң жаққа ба?» деген шешімнің негізі болмайды","Ол тым баяу жұмыс істейді","C-да оны жазуға болмайды","Жарайды, айырмашылығы жоқ"],"a":0,"e":"Кіші сандар солда, үлкендері оңда деп болжауға болмайды, сондықтан іздегенді өткізіп алуымыз мүмкін.","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Қай алгоритмнің Ω-сы мен O-сы бірдей, демек Θ-мен сипатталады?","o":["Сызықтық іздеу","Bubble sort (ерте тоқтаумен)","Selection sort","Екілік іздеу"],"a":2,"e":"Selection sort әрқашан <em>n</em>² қадам жасайды, тіпті деректер сұрыпталған болса да: Θ(<em>n</em>²).","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Неге <code>if (s == t)</code> екі жолды дұрыс салыстырмайды?","o":["Жолдар тым ұзын","Жолдарды таңба-таңбамен салыстыру керек, ол үшін <code>strcmp</code> бар","<code>==</code> тек <code>float</code> үшін","Компилятор рұқсат бермейді"],"a":1,"e":"Келесі аптада бұның нақты себебін көреміз: <code>==</code> жолдардың мекенжайларын салыстырады.","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Рекурсивті функцияда базалық жағдай болмаса не болады?","o":["Функция бір рет қана орындалады","Нәтиже 0 болады","Ештеңе өзгермейді","Функция өзін шексіз шақыра береді (жад таусылады)"],"a":3,"e":"clang мұндай жағдайды кейде компиляция кезінде-ақ байқайды: «all paths through this function will call itself».","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Merge sort-тың басты кемшілігі қандай?","o":["Қосымша жад керек","Ол O(<em>n</em>²)","Ол тек жұп санды элементтермен жұмыс істейді","Кемшілігі жоқ"],"a":0,"e":"Біріктіру үшін екінші «сөре», яғни қосымша массив керек.","l":"3-апта: Алгоритмдер","u":"lectures/week-3.html#quiz"},{"q":"Он алтылық <code>0x2A</code> ондық жүйеде қандай сан?","o":["210","32","42","26"],"a":2,"e":"2 × 16 + 10 × 1 = 42 (A = 10).","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"<code>int n = 50; int *p = &amp;n;</code> болса, <code>*p</code> неге тең?","o":["<code>n</code>-нің мекенжайы","50","<code>p</code>-ның мекенжайы","Қоқыс мән"],"a":1,"e":"<code>*p</code> - p-дағы мекенжайға барып, ондағы мәнді алу (дереференс).","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"<code>string t = s;</code> жолынан кейін <code>t[0] = 'X';</code> орындасақ, <code>s</code>-ке не болады?","o":["<code>s</code> те өзгереді, себебі екеуі бір жадты көрсетеді","<code>s</code> өзгермейді","Бағдарлама компиляцияланбайды","<code>s</code> NULL болады"],"a":0,"e":"Тек мекенжай көшірілді. Нағыз көшірме үшін <code>malloc</code> және <code>strcpy</code> керек.","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"«HI!» жолын көшіру үшін <code>malloc</code>-қа неше байт беру керек?","o":["3","8","2","4"],"a":3,"e":"<code>strlen(s) + 1</code>: 3 таңба және NUL.","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"NUL мен NULL айырмашылығы неде?","o":["Айырмашылығы жоқ","NUL - мекенжай, NULL - таңба","NUL - жолды аяқтайтын <code>\\0</code> таңбасы, NULL - <code>0x0</code> ерекше мекенжайы","Екеуі де <code>malloc</code>-тың қайтаратын мәні"],"a":2,"e":"NUL - 8 нөлдік бит, NULL - «ештеңені көрсетпейтін» көрсеткіш.","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"<code>malloc</code> жадты қай аймақтан береді?","o":["Стектен","Үймеден (heap)","Машиналық код аймағынан","Қатты дисктен"],"a":1,"e":"Функциялар мен жергілікті айнымалылар стекте, ал malloc берген жад үймеде.","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"Неге бірінші <code>swap(int a, int b)</code> нұсқасы <code>x</code> пен <code>y</code>-ті ауыстырмады?","o":["Функция мәндердің көшірмелерін алды (мән бойынша беру)","<code>tmp</code> айнымалысы жоқ","Прототип қате жазылды","<code>int</code> орнына <code>float</code> керек еді"],"a":0,"e":"Шешімі: мекенжайларды беру, яғни <code>swap(&amp;x, &amp;y)</code> және <code>int *a, int *b</code>.","l":"4-апта: Жад","u":"lectures/week-4.html#quiz"},{"q":"Асханадағы подностар қандай құрылымға мысал?","o":["Стек (LIFO)","Кезек (FIFO)","Хэш-кесте","Trie"],"a":0,"e":"Соңғы қойылған поднос бірінші алынады.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"<code>n-&gt;next</code> қай жазумен бірдей?","o":["<code>n.next</code>","<code>*n.next</code>","<code>(*n).next</code>","<code>&amp;n.next</code>"],"a":2,"e":"Көрсеткі - дереференс пен нүктенің бірігуі. Жақшалар операциялар реті үшін керек.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"Байланысқан тізімге жаңа түйін қосқанда <code>list = n;</code> жолын <code>n-&gt;next = list;</code> жолынан бұрын жазсақ не болады?","o":["Ештеңе, рет маңызды емес","Ескі тізім «жетім» қалады, жад ағып кетеді","Компилятор қате береді","Тізім сұрыпталады"],"a":1,"e":"Тізімнің басына апаратын жалғыз көрсеткішті жоғалтамыз.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"1, 2, 3, 4, 5 ретімен қосылған екілік іздеу ағашында іздеу қандай уақыт алады?","o":["O(1)","O(log <em>n</em>)","O(<em>n</em> log <em>n</em>)","O(<em>n</em>)"],"a":3,"e":"Ағаш теңгерімсіз, ол байланысқан тізімге айналды.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"«Mario» мен «Mateo» бірінші әріп бойынша хэштелсе не болады?","o":["Соқтығысу: екеуі бір шелекке түседі, тізбектеледі","Біреуі өшіріледі","Бағдарлама құлайды","Екеуі әртүрлі шелекке түседі"],"a":0,"e":"Хэш-кестеде соқтығысулар байланысқан тізім арқылы шешіледі.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"Trie-дің басты кемшілігі қандай?","o":["Іздеу O(<em>n</em>)","Ұзын сөздерді сақтай алмайды","Өте көп жад пайдаланады, көрсеткіштердің көбі NULL","Кемшілігі жоқ"],"a":2,"e":"Әр түйінде 26 көрсеткіш бар, бірақ олардың көбі пайдаланылмайды.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"<code>realloc</code> нәтижесін неге бірден <code>list</code>-ке емес, <code>tmp</code>-ке сақтаймыз?","o":["Бұл стиль ғана","Сәтсіз болса, NULL қайтарады да, ескі жадтың мекенжайын жоғалтып аламыз","realloc тек tmp атты айнымалымен жұмыс істейді","Жылдамырақ болады"],"a":1,"e":"realloc сәтсіз болса, ескі жадқа тиіспейді. Оны free арқылы босату үшін мекенжайы керек.","l":"5-апта: Деректер құрылымдары","u":"lectures/week-5.html#quiz"},{"q":"<code>x = input(\"x: \")</code> және <code>y = input(\"y: \")</code>, 1 мен 2 енгізілсе, <code>print(x + y)</code> не шығарады?","o":["3","Қате","12","x + y"],"a":2,"e":"<code>input</code> жол қайтарады, ал жолдарда <code>+</code> біріктіреді.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"Python-да <code>7 / 2</code> нәтижесі қандай?","o":["3.5","3","4","1"],"a":0,"e":"Python-да бөлу float береді. Бүтін бөлу үшін <code>7 // 2</code> = 3.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"<code>range(3)</code> қандай мәндерді береді?","o":["1, 2, 3","0, 1, 2","0, 1, 2, 3","3"],"a":1,"e":"0-ден басталады, 3-ке дейін, бірақ 3-ті қоспайды.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"Python-да do-while циклінің орнына не қолданылады?","o":["<code>do:</code> ... <code>while</code>","<code>repeat</code>","<code>for i in range(1)</code>","<code>while True:</code> және <code>break</code>"],"a":3,"e":"Мәңгілік цикл жасап, дұрыс кіріс алынғанда break арқылы шығамыз.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"<code>people = {\"Kelly\": \"+1-617\", \"John\": \"+1-949\"}</code> болса, Джонның нөмірін қалай аламыз?","o":["<code>people[1]</code>","<code>people.John</code>","<code>people[\"John\"]</code>","<code>people(John)</code>"],"a":2,"e":"Сөздікті кілт (жол) арқылы индекстейміз.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"<code>int(\"cat\")</code> қандай ерекше жағдай тудырады?","o":["<code>ValueError</code>","<code>NameError</code>","<code>ModuleNotFoundError</code>","Ешқандай, 0 қайтарады"],"a":0,"e":"Оны <code>try</code> / <code>except ValueError</code> арқылы ұстайсыз.","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"<code>python greet.py David</code> командасында <code>len(sys.argv)</code> неге тең?","o":["3","2","1","0"],"a":1,"e":"<code>python</code> интерпретаторы саналмайды: [\"greet.py\", \"David\"].","l":"6-апта: Python","u":"lectures/week-6.html#quiz"},{"q":"SQL қандай тіл?","o":["Процедуралық: компьютерге қадамдарды айтамыз","Декларативті: не керек екенін айтамыз","Компиляцияланатын, C сияқты","Белгілеу тілі, HTML сияқты"],"a":1,"e":"SQL-да нәтижені сипаттаймыз, ал оны қалай табуды база өзі шешеді.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"Әр тілді неше адам таңдағанын санау үшін қандай сөз керек?","o":["<code>ORDER BY language</code>","<code>WHERE language</code>","<code>GROUP BY language</code>","<code>DISTINCT language</code>"],"a":2,"e":"<code>SELECT language, COUNT(*) FROM favorites GROUP BY language;</code>","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"<code>DELETE FROM favorites;</code> (WHERE-сіз) не істейді?","o":["Кестедегі барлық жолды өшіреді","Қате береді","Соңғы жолды ғана өшіреді","Кестенің өзін өшіреді"],"a":0,"e":"Сондықтан <code>DELETE</code> және <code>UPDATE</code>-те <code>WHERE</code>-ді ұмытпаңыз. Кестені өзін <code>DROP TABLE</code> өшіреді.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"Шоулар мен актерлер арасындағы байланыс қандай?","o":["Бір-біріне","Бір-көпке","Байланыс жоқ","Көп-көпке"],"a":3,"e":"Бір шоуда көп актер, бір актер көп шоуда. Сондықтан <code>stars</code> кестесі керек.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"Индекстің кемшілігі қандай?","o":["Іздеуді баяулатады","Қосымша жад алады және енгізу/жаңартуды баяулатады","Тек сандарға жұмыс істейді","Кемшілігі жоқ"],"a":1,"e":"Әр <code>INSERT</code>/<code>UPDATE</code> кезінде B-ағашты да жаңарту керек.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"SQL инъекциясынан қалай қорғанамыз?","o":["Сұрауды f-жолмен құрастырамыз","Пайдаланушыға тырнақша жазуға тыйым саламыз","<code>?</code> орын толтырғыштарын қолданамыз","<code>--</code> түсініктемелерін өшіреміз"],"a":2,"e":"Кітапхана мәндерді өзі дұрыс экрандайды.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"Екі сервер бір уақытта «ұнату» санын оқып, екеуі де +1 жазса, не болады?","o":["Бір «ұнату» жоғалады (жарыс жағдайы)","Сан 2-ге артады","База бұзылады","SQLite қате береді"],"a":0,"e":"Транзакция (<code>BEGIN TRANSACTION</code> ... <code>COMMIT</code>) мұның алдын алады.","l":"7-апта: SQL","u":"lectures/week-7.html#quiz"},{"q":"CS50 үйрегін мысық емес, үйрек ретінде әрекет етуге не мәжбүрлейді?","o":["Қолданушы промпты","Жүйелік промпт","Модельдің аты","API кілті"],"a":1,"e":"Жүйелік промпт рөлді, мінезді және шектеулерді анықтайды.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"Минимаксте (O жеңсе −1, X жеңсе +1) O қандай жүрісті таңдайды?","o":["Ұпайы ең жоғары жүрісті","Кездейсоқ жүрісті","Ортадағы ұяшықты әрқашан","Ұпайы ең төмен жүрісті"],"a":3,"e":"O ұпайды минимумға, X максимумға жеткізгісі келеді.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"Тік-так-тоны ойнаудың неше тәсілі бар?","o":["9","362 880","255 168","85 миллиард"],"a":2,"e":"Ойындар ерте аяқталуы мүмкін болғандықтан, 9! = 362 880-нен аз. 85 миллиард - шахматтың алғашқы 4 жұп жүрісі.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"Күшейтілген оқытуда <code>epsilon = 0.1</code> не үшін керек?","o":["10% жағдайда кездейсоқ жүріс жасап, жаңа (мүмкін жақсырақ) жолдарды зерттеу үшін","Қателерді 10%-ға азайту үшін","Оқытуды 10 есе жылдамдату үшін","Марапатты 0.1-ге көбейту үшін"],"a":0,"e":"Бұл зерттеу мен пайдалану арасындағы тепе-теңдік.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"Пайдаланушылар хаттарды «спам» деп белгілеуі - бұл...","o":["Бақылаусыз оқыту","Бақыланатын оқыту","Минимакс","Галлюцинация"],"a":1,"e":"Процесте деректерді белгілейтін адам бар.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"GPT сияқты модельдерде «назар» (attention) нені анықтайды?","o":["Пайдаланушы экранға қаншалықты қарап тұрғанын","Сөздің әріптер санын","Мәтіндегі сөздердің бір-біріне қаншалықты қатысты екенін","Модельдің жауап беру жылдамдығын"],"a":2,"e":"Мысалы, «Massachusetts» пен «state» арасында назар жоғары.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"AI галлюцинациясы дегеніміз не?","o":["AI-дың суреттер жасауы","Модельдің баяу жұмыс істеуі","Промпттың тым ұзын болуы","AI-дың сенімді түрде ойдан шығарылған не қате жауап беруі"],"a":3,"e":"LLM-дер ықтималдыққа негізделген, сондықтан олардың жауабын әрқашан тексеру керек.","l":"Арнайы лекция: Жасанды интеллект","u":"lectures/ai.html#quiz"},{"q":"IPv4 мекенжайы неше бит?","o":["8","16","32","128"],"a":2,"e":"0–255 аралығындағы төрт сан, әрқайсысы 8 бит. 128 бит - IPv6.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"Бір серверде пошта мен веб-сайтты ажыратуға не мүмкіндік береді?","o":["IP-мекенжай","TCP порт нөмірі","DNS","DHCP"],"a":1,"e":"Мысалы, HTTPS үшін 443 порты.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"DNS не істейді?","o":["Деректерді шифрлайды","Құрылғыға IP-мекенжай береді","Пакеттерді бөлшектейді","Домен атауларын IP-мекенжайларға аударады"],"a":3,"e":"IP-мекенжайды DHCP береді, ал бөлшектеу мен қайта жинауды TCP басқарады.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"Сервер <code>301</code> кодын қайтарса, браузер не істейді?","o":["<code>Location</code> тақырыбындағы мекенжайға барады","«Бет табылмады» дейді","Бетті кэштен көрсетеді","Серверді қайта іске қосады"],"a":0,"e":"301 - Moved Permanently, біржола көшірілді.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"Нөмірленген тізім үшін қандай тег керек?","o":["<code>ul</code>","<code>li</code>","<code>ol</code>","<code>list</code>"],"a":2,"e":"ordered list. <code>ul</code> таңбалы, <code>li</code> - тізім элементі.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"CSS-те <code>.large</code> және <code>#harvard</code> нені таңдайды?","o":["<code>large</code> тегін және <code>harvard</code> класын","<code>large</code> класын және ID-і <code>harvard</code> элементті","Екеуі де класс","Екеуі де ID"],"a":1,"e":"Нүкте - класс, <code>#</code> - ID.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"Неге HTML <code>pattern</code> атрибутына қауіпсіздік үшін сенуге болмайды?","o":["Пайдаланушы өз браузерінде HTML-ді өзгерте алады","Барлық браузер оны қолдамайды","Тұрақты өрнектер тым баяу","Ол тек электрондық поштаға жұмыс істейді"],"a":0,"e":"Тексеруді әрқашан серверде де жасау керек.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"JavaScript-те CSS-тің <code>background-color</code> қасиеті қалай жазылады?","o":["<code>background-color</code>","<code>background_color</code>","<code>BackgroundColor</code>","<code>backgroundColor</code>"],"a":3,"e":"camelCase: JavaScript-те дефис - алу амалы.","l":"8-апта: HTML, CSS, JavaScript","u":"lectures/week-8.html#quiz"},{"q":"Flask-та POST арқылы жіберілген форма деректері қайда?","o":["<code>request.args</code>","<code>request.form</code>","<code>request.post</code>","<code>session</code>"],"a":1,"e":"<code>request.args</code> - GET (URL) параметрлері.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"Маршрут тек GET-ті қолдаса, оған POST жіберсек, қандай код шығады?","o":["404","500","405","301"],"a":2,"e":"405 Method Not Allowed. <code>methods=[\"POST\"]</code> қосу керек.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"Flask шаблондарды қай қалтадан іздейді?","o":["<code>templates</code>","<code>static</code>","<code>views</code>","Ағымдағы қалтадан"],"a":0,"e":"Суреттер, CSS, JS - <code>static</code>-та.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"<code>{% extends \"layout.html\" %}</code> не істейді?","o":["<code>layout.html</code>-ды браузерге жібереді","Python модулін импорттайды","<code>layout.html</code>-ды көшіріп, жаңа файл жасайды","Шаблонды <code>layout.html</code> жобасына негіздейді, ал блоктар оның орындарына қойылады"],"a":3,"e":"Ортақ HTML бір жерде жазылады, әр бет тек өз блогын анықтайды.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"Неге <code>/deregister</code> маршруты POST-ты қолдануы керек?","o":["POST жылдамырақ","GET сілтемесін басу арқылы деректер абайсызда өзгеруі мүмкін","ID-лер құпия","Flask GET-пен <code>DELETE</code> орындай алмайды"],"a":1,"e":"Деректерді өзгертетін әрекеттер GET арқылы болмауы керек.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"Cookie-ге не сақтаған дұрыс?","o":["Пайдаланушы аты мен құпиясөзді","Карта нөмірін","Сессияны анықтайтын үлкен кездейсоқ мәнді","Бүкіл дерекқорды"],"a":2,"e":"Деректердің өзі серверде сақталады, cookie - тек «мөр».","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"MVC-да <code>app.py</code> қай рөлде?","o":["Controller","View","Model","Ешқайсысы"],"a":0,"e":"Шаблондар - View, дерекқор - Model.","l":"9-апта: Flask","u":"lectures/week-9.html#quiz"},{"q":"8 биттік таңбасыз екілік сан ең көп қандай санды көрсете алады?","o":["256","128","255","1"],"a":2,"e":"0-ден санағандықтан, 256 мүмкіндіктің бірі 0-ге кетеді, сондықтан ең үлкені 255.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"2038 жылғы мәселенің негізінде не жатыр?","o":["Бүтін санның толып кетуі","Зиянды енгізу","SQL инъекциясы","Жадтың ағуы"],"a":0,"e":"Уақыт 1970 жылғы 1 қаңтардан (epoch) бастап 32 биттік санмен есептеледі, ал 2038 жылы оның мүмкіндіктері бітеді. Заманауи құрылғылар 64 биттік санағышқа көшкен.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"Төмендегілердің қайсысы компиляцияның қадамы емес?","o":["Байланыстыру (linking)","Алдын ала өңдеу (preprocessing)","Ассемблерлеу (assembling)","Интерпретациялау (interpreting)"],"a":3,"e":"Қадамдар: preprocessing (#include, #define), compiling (ассемблер кодына), assembling (машиналық кодқа), linking (кітапханалармен біріктіру).","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"Көрсеткіш нені сақтайды?","o":["Айнымалының атын","Мәннің жадтағы мекенжайын","Мәннің өлшемін","Айнымалының мәнін"],"a":1,"e":"Көрсеткіш - мекенжай.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"Сызықтық іздеудің жұмыс уақыты қандай?","o":["O(1)","O(n)","O(n²)","O(n log n)"],"a":1,"e":"Ең нашар жағдайда тізімнің соңына дейін бару керек. Ω(1) болуы мүмкін, бірақ O(1) емес.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"«Бірінші кірген бірінші шығады» (FIFO) қағидасымен қай құрылым жұмыс істейді?","o":["Кезек (queue)","Байланысқан тізім","Стек (stack)","Хэш-кесте"],"a":0,"e":"Дүкендегі кезек сияқты. Стек - LIFO (асханадағы науалар сияқты).","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"C-да қай оператор айнымалының мекенжайын қайтарады?","o":["*","$","&amp;","-&gt;"],"a":2,"e":"&amp; - «мекенжайы» операторы. * - мекенжайға бару (dereference), -&gt; - көрсеткіш арқылы құрылымның өрісіне бару.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"SQL-да нәтижедегі қайталанатын жолдарды қай сөз алып тастайды?","o":["REMOVE","UNIQUE","DISTINCT","CLEAN"],"a":2,"e":"UNIQUE - кестенің схемасында бағанның мәндері бірегей болуын анықтайды.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"HTTP 418 коды нені білдіреді?","o":["Not Found","I'm a Teapot","Forbidden","Unauthorized"],"a":1,"e":"1 сәуірдегі әзіл: «мен шәйнекпін».","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"malloc жадты қайдан бөледі?","o":["Үйінді (heap)","Стек","Глобалды айнымалылар","Ассемблер"],"a":0,"e":"Стек функция шақыруларына арналған: әр шақыру стектен кадр алады.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"C-да malloc-пен жад бөліп, free шақыруды ұмытсаңыз, не болады?","o":["Жадтың ағуы (memory leak)","Сегментация қатесі","Стектің толып кетуі","Барлығы"],"a":0,"e":"Басқа қателер де болуы мүмкін, бірақ free-ді ұмытудың тікелей салдары - жадтың ағуы.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"safetyschool.org қай сайтқа бағыттайды?","o":["Гарвард","Принстон","Йель","Колумбия"],"a":2,"e":"301 Moved Permanently, Location: yale.edu.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"DNS не үшін керек?","o":["Қараңғы вебтегі деректерді шифрлау","Ең жақын кофеханы табу","Орныңызды хакерлерден қорғау","Домен атауларын IP-мекенжайларға аудару"],"a":3,"e":"Үйдегі, провайдердегі, кампустағы DNS серверлері осындай сұрақтарға жауап береді.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"Қайсысы жарыс жағдайымен күресетін кірістірілген SQL мүмкіндігі емес?","o":["BEGIN TRANSACTION","COMMIT","ROLLBACK","ENROLL"],"a":3,"e":"«Тым көп сүт» мысалы есіңізде ме? ENROLL деген SQL командасы жоқ.","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"Профессор Малан әр лекцияның басында не дейді?","o":["Welcome to Harvard's Computer Science class","Hello everyone, ready to code?","All right, this is CS50","Let's get started with some programming"],"a":2,"e":"«Жарайды, бұл CS50». Ал соңында: «Бұл CS50 болды».","l":"10-апта: Соңы","u":"lectures/week-10.html#quiz"},{"q":"<code>x = input(\"x: \")</code> және <code>y = input(\"y: \")</code> болса, 1 мен 2 енгізгенде <code>print(x + y)</code> не шығарады?","o":["3","Қате","12","x + y"],"a":2,"e":"<code>input</code> әрқашан жол қайтарады, ал жолдар үшін <code>+</code> біріктіреді: \"1\" + \"2\" = \"12\".","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"<code>print(\"hello,\", end=\"\")</code> не істейді?","o":["hello, сөзінен кейін бос жол қалдырады","Шығарғаннан кейін жаңа жолға көшпейді","Ештеңе шығармайды","Қате береді"],"a":1,"e":"<code>end</code> параметрінің әдепкі мәні <code>\"\\n\"</code>. Оны <code>\"\"</code> етсек, келесі <code>print</code> сол жолдан жалғасады.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"<code>\"  david malan \".strip().title()</code> нәтижесі қандай?","o":["\"  David Malan \"","\"david malan\"","\"DAVID MALAN\"","\"David Malan\""],"a":3,"e":"<code>strip</code> шеттегі бос орындарды алады, <code>title</code> әр сөзді бас әріппен бастайды.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"<code>z = 2 / 3</code> болса, <code>print(f\"{z:.2f}\")</code> не шығарады?","o":["0.67","0.66","0.6666666666666666",".67"],"a":0,"e":"<code>:.2f</code> үтірден кейін екі таңбаға дейін дөңгелектеп, жол етіп шығарады.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"Мына бағдарлама іске қосылса, не болады?","o":["hello шығады","Қате шығады","Ештеңе болмайды","main шығады"],"a":2,"e":"Функция анықталды, бірақ шақырылмады. Соңына <code>main()</code> қосу керек.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"<code>def square(n): return n * n</code> болса, <code>square(square(2))</code> неге тең?","o":["4","16","8","Қате"],"a":1,"e":"Алдымен ішкі <code>square(2)</code> = 4, сосын <code>square(4)</code> = 16. <code>return</code> болғандықтан мәнді ары қарай қолдануға болады.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"Python-да <code>int(input(\"x: \"))</code> жолында қай функция бірінші орындалады?","o":["<code>int</code>","Екеуі бір мезетте","<code>print</code>","<code>input</code>"],"a":3,"e":"Ішкі функция бірінші: <code>input</code> жол қайтарады, сосын <code>int</code> оны санға айналдырады.","l":"0-апта: Функциялар, айнымалылар","u":"python/lectures/week-0.html#quiz","c":"python"},{"q":"<code>x = 10</code> болса, мына код не шығарады?","o":["Тек A","Тек B","A, сосын B","Ештеңе"],"a":2,"e":"Бұл екі бөлек <code>if</code>, сондықтан екеуі де тексеріледі. 10 &gt; 0 те, 10 &gt; 5 те ақиқат, демек екі жол да шығады.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"Енді екінші <code>if</code>-ті <code>elif</code>-ке ауыстырдық. <code>x = 10</code> болса, не шығады?","o":["Тек A","Тек B","A, сосын B","Қате"],"a":0,"e":"<code>if</code> ақиқат болған соң, Python <code>elif</code>-ті мүлде тексермейді. Сондықтан тек A шығады.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"<code>if x = 5:</code> деп жазылған бағдарламаны іске қоссақ, не болады?","o":["x-ке 5 меншіктеліп, шарт ақиқат болады","x 5-ке тең болса ғана блок орындалады","Шарт әрдайым жалған болады","Python қате (<code>SyntaxError</code>) береді"],"a":3,"e":"Салыстыру үшін екі теңдік белгісі (<code>==</code>) керек. Жалғыз <code>=</code> - меншіктеу, ол <code>if</code>-тің шартында рұқсат етілмейді.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"<code>17 % 5</code> неге тең?","o":["3.4","2","3","0"],"a":1,"e":"<code>%</code> бөлудің қалдығын береді: 17 = 5 × 3 + 2, демек қалдық 2.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"Мына кодта қате бар. <code>score = 85</code> болса, не шығады?","o":["Grade: D","Grade: B","Grade: C","Grade: F"],"a":0,"e":"85 &gt;= 60 ақиқат, сондықтан бірінші тармақ орындалады да, қалғаны тексерілмейді. Шарттардың реті маңызды: ең үлкен шекарадан бастау керек.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"<code>def is_even(n): return n % 2 == 0</code> болса, <code>is_even(4)</code> нені қайтарады?","o":["<code>0</code>","<code>\"Even\"</code>","<code>True</code>","Ештеңе (<code>None</code>)"],"a":2,"e":"4 % 2 = 0, ал <code>0 == 0</code> салыстыруының нәтижесі - <code>True</code> логикалық мәні. Функция соны қайтарады.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"Студент былай жазды. Қолданушы <code>Draco</code> енгізсе, не шығады?","o":["Who?","Қате","Ештеңе шықпайды","Gryffindor"],"a":3,"e":"Python мұны <code>(name == \"Harry\") or (\"Hermione\")</code> деп оқиды. Бос емес жол <code>\"Hermione\"</code> әрдайым ақиқат деп саналады, сондықтан кім енгізсе де Gryffindor шығады. Дұрысы: <code>name == \"Harry\" or name == \"Hermione\"</code>.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"<code>match</code> нұсқауындағы <code>case _:</code> не істейді?","o":["Бос жолға (<code>\"\"</code>) ғана сәйкес келеді","Кез келген мәнге сәйкес келеді, <code>else</code> сияқты","Астын сызу таңбасына (<code>\"_\"</code>) ғана сәйкес келеді","Бағдарламаны тоқтатады"],"a":1,"e":"<code>_</code> - «қалған кез келгені» деген белгі. Жоғарыдағы <code>case</code>-тердің ешқайсысы сәйкес келмесе, осы орындалады.","l":"1-апта: Шарттар","u":"python/lectures/week-1.html#quiz","c":"python"},{"q":"Бұл код неше рет «meow» шығарады?","o":["3","2","1","Шексіз"],"a":1,"e":"<code>i</code> 1-ден басталады: <code>i</code> = 1 және 2 үшін шарт ақиқат, ал 3 болғанда <code>3 &lt; 3</code> жалған. Демек, екі рет.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"Бұл кодтың қатесі неде?","o":["<code>while</code>-тан кейін жақша керек","<code>!=</code> деген оператор жоқ","Ештеңе шықпайды, себебі <code>i</code> 0 емес","<code>i</code> өзгермейді, сондықтан цикл шексіз"],"a":3,"e":"Циклдің ішінде <code>i</code> ешқашан азаймайды, шарт әрқашан ақиқат. <code>i -= 1</code> қосу керек.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"<code>for i in range(4): print(i)</code> қандай сандарды шығарады?","o":["0, 1, 2, 3","1, 2, 3, 4","0, 1, 2, 3, 4","4"],"a":0,"e":"<code>range(4)</code> 0-ден басталып, 4-ке дейін барады, бірақ 4-ті қоспайды.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"<code>print(\"ha\" * 3)</code> не шығарады?","o":["Қате: жолды санға көбейтуге болмайды","ha ha ha","hahaha","ha3"],"a":2,"e":"Жолды санға көбейткенде, ол сонша рет бос орынсыз қайталанып жалғанады.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"<code>students = [\"Hermione\", \"Harry\", \"Ron\"]</code> болса, <code>students[1]</code> неге тең?","o":["\"Hermione\"","\"Harry\"","\"Ron\"","Қате"],"a":1,"e":"Индекс нөлден басталады: 0 - Hermione, 1 - Harry, 2 - Ron.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"<code>d = {\"Harry\": \"Gryffindor\", \"Draco\": \"Slytherin\"}</code> болса, <code>for x in d: print(x)</code> не шығарады?","o":["Gryffindor, Slytherin","Harry Gryffindor, Draco Slytherin","0, 1","Harry, Draco"],"a":3,"e":"Сөздікті <code>for</code> арқылы аралағанда, цикл кілттерді аралайды. Мәнді алу үшін <code>d[x]</code> керек.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"Қолданушы алдымен <code>-1</code>, сосын <code>5</code> енгізсе, бағдарлама неше рет «What's n?» деп сұрайды?","o":["2","1","Шексіз","5"],"a":0,"e":"-1 үшін шарт жалған, цикл қайта сұрайды. 5 үшін <code>break</code> орындалып, циклден шығамыз. Барлығы 2 рет.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"Мына кірістірілген циклдер не шығарады?","o":["3 жол, әрқайсысында 2 кірпіш","Бір жолда 6 кірпіш","2 жол, әрқайсысында 3 кірпіш","6 жол, әрқайсысында 1 кірпіш"],"a":2,"e":"Сыртқы цикл 2 қатар жасайды, ішкі цикл әр қатарға 3 кірпіш салады, ал <code>print()</code> қатар соңында жаңа жолға көшіреді.","l":"2-апта: Циклдер","u":"python/lectures/week-2.html#quiz","c":"python"},{"q":"Қолданушы <code>x = int(input(\"What's x? \"))</code> жолына <code>cat</code> деп жауап берсе, қай ерекше жағдай туындайды?","o":["<code>SyntaxError</code>","<code>ValueError</code>","<code>NameError</code>","<code>ZeroDivisionError</code>"],"a":1,"e":"<code>int</code> «cat» мәтінін санға айналдыра алмайды, сондықтан <code>ValueError</code> лақтырады. Код грамматикалық тұрғыдан дұрыс, бұл орындалу кезіндегі қате.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"Мына бағдарламаға <code>cat</code> енгізілсе, не болады?","o":["Тек <code>x is not an integer</code> шығады","<code>x is cat</code> шығады","Бағдарлама қайта сұрайды","<code>x is not an integer</code> шығады, сосын <code>NameError</code>"],"a":3,"e":"<code>int</code> қате бергендіктен, <code>x</code>-ке ешқашан мән меншіктелмейді. <code>except</code> хабарды шығарады, бірақ соңғы <code>print</code> анықталмаған <code>x</code>-ті таба алмай, <code>NameError</code> береді.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"<code>try</code> / <code>except</code> / <code>else</code> құрылымында <code>else</code> блогы қашан орындалады?","o":["<code>try</code> ішінде ешқандай ерекше жағдай туындамаса","Ерекше жағдай туындаса","Әрқашан, <code>except</code>-тен кейін","Ешқашан, ол тек <code>if</code>-пен жұмыс істейді"],"a":0,"e":"<code>else</code> тек <code>try</code> сәтті аяқталғанда орындалады. Қате болса, <code>except</code> орындалып, <code>else</code> өткізіп жіберіледі.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"Қолданушы кезекпен <code>cat</code>, <code>dog</code>, <code>50</code> енгізеді. <code>x is not an integer</code> неше рет шығады?","o":["0","1","2","3"],"a":2,"e":"«cat» пен «dog» - екі қате, әрқайсысынан кейін хабар шығады. «50» сәтті болып, <code>else</code> ішіндегі <code>break</code> циклді тоқтатады да, <code>x is 50</code> шығады.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"<code>except ValueError:</code> астындағы <code>pass</code> не істейді?","o":["Бағдарламаны тоқтатады","Ештеңе істемейді: қате үнсіз ұсталып, бағдарлама ары қарай жүреді","Қатені қолданушыға көрсетеді","Циклден шығады"],"a":1,"e":"<code>pass</code> - бос толтырғыш. Ерекше жағдай ұсталады, бірақ ешқандай хабар шықпайды; циклдің ішінде болса, сұрақ жай ғана қайталанады.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"<code>get_int</code> ішінде <code>while True:</code> циклінің ішіндегі <code>return int(input(prompt))</code> сәтті орындалса, не болады?","o":["Мән қайтарылады, бірақ цикл жалғаса береді","Алдымен <code>break</code> керек, әйтпесе қате","<code>except</code> блогы орындалады","Мән қайтарылып, функциядан да, циклден де бірден шығады"],"a":3,"e":"<code>return</code> функцияны толығымен аяқтайды, сондықтан ішіндегі цикл де бірге үзіледі. <code>break</code> қажет емес.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"Файлдың бірінші жолы <code>print(\"hi\")</code>, ал екінші жолы <code>print(\"hello, world)</code> (тырнақша жабылмаған). Іске қоссақ, не болады?","o":["Ештеңе шықпайды, бірден <code>SyntaxError</code>","<code>hi</code> шығады, сосын <code>SyntaxError</code>","<code>hi</code> және <code>hello, world</code> шығады","<code>ValueError</code>"],"a":0,"e":"Python кодты орындамас бұрын бүкіл файлдың грамматикасын тексереді. Синтаксистік қате болса, бірде-бір жол орындалмайды. Сол себепті оны <code>try</code> арқылы ұстай алмаймыз, өзіміз түзетеміз.","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"Мына мәндердің қайсысын <code>int(...)</code>-ке берсек, <code>ValueError</code> шығады?","o":["<code>\"50\"</code>","<code>\"-3\"</code>","<code>\"1.5\"</code>","<code>\" 50 \"</code>"],"a":2,"e":"<code>int</code> бүтін санды білдіретін жолды ғана қабылдайды: теріс таңба мен шеттегі бос орындар рұқсат, ал ондық нүкте жоқ. <code>\"1.5\"</code> - <code>ValueError</code>. Бұл Fuel Gauge тапсырмасында керек болады!","l":"3-апта: Ерекше жағдайлар","u":"python/lectures/week-3.html#quiz","c":"python"},{"q":"<code>from random import choice</code> деп жазғаннан кейін функцияны қалай шақырамыз?","o":["<code>random.choice([\"heads\", \"tails\"])</code>","<code>choice([\"heads\", \"tails\"])</code>","<code>random(choice([\"heads\", \"tails\"]))</code>","<code>import choice</code> деп тағы жазу керек"],"a":1,"e":"<code>from ... import</code> функцияны бағдарламаға тікелей жүктейді, сондықтан модуль атынсыз, жай <code>choice</code> деп жазамыз. Ал <code>random</code> деген атау бұл жағдайда анықталмаған.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>cards = [\"jack\", \"queen\", \"king\"]</code> болса, <code>x = random.shuffle(cards)</code> орындалғаннан кейін <code>x</code>-те не болады?","o":["Араластырылған тізім","Бастапқы тізім","Кездейсоқ бір карта","<code>None</code>"],"a":3,"e":"<code>shuffle</code> тізімнің өзін орнында араластырады және ешқандай мән қайтармайды, яғни <code>None</code> қайтарады. Араластырылған тізім <code>cards</code>-тың өзінде.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>python name.py David Malan</code> деп іске қосылса, <code>sys.argv</code> неге тең?","o":["<code>[\"name.py\", \"David\", \"Malan\"]</code>","<code>[\"David\", \"Malan\"]</code>","<code>[\"python\", \"name.py\", \"David\", \"Malan\"]</code>","<code>\"David Malan\"</code>"],"a":0,"e":"<code>sys.argv</code> - жолдар тізімі. Оның 0-элементі бағдарламаның аты, ал қолданушы аргументтері 1-ден басталады. <code>python</code> сөзі тізімге кірмейді.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>python name.py</code> деп (атсыз) іске қосылса, <code>print(sys.argv[1])</code> қандай қате береді?","o":["<code>ValueError</code>","<code>NameError</code>","<code>IndexError</code>","Қате болмайды, бос жол шығады"],"a":2,"e":"Тізімде тек <code>name.py</code> бар, 1-индексте ешнәрсе жоқ: <code>list index out of range</code>.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>sys.exit(\"Too few arguments\")</code> не істейді?","o":["Хабарды шығарып, бағдарламаны жалғастырады","Терминалды жабады","<code>IndexError</code> көтереді","Хабарды шығарып, бағдарламаны сол жерде тоқтатады"],"a":3,"e":"<code>sys.exit</code> бағдарламадан бірден шығады, сондықтан одан кейінгі код орындалмайды. Сол себепті қате тексерулерін бағдарламаның басына «күзетші» етіп қоюға болады.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>names = [\"name.py\", \"David\", \"Carter\", \"Rongxin\"]</code> болса, <code>names[1:]</code> неге тең?","o":["<code>[\"David\", \"Carter\", \"Rongxin\"]</code>","<code>[\"name.py\"]</code>","<code>\"David\"</code>","<code>[\"name.py\", \"David\"]</code>"],"a":0,"e":"<code>[1:]</code> - 1-индекстен бастап соңына дейінгі кесінді. Тек 0-элемент, <code>name.py</code>, қалып қояды.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>import cowsay</code> жолы <code>ModuleNotFoundError</code> берсе, ең алдымен не істеу керек?","o":["<code>import cowsay</code>-ды <code>from cowsay import *</code> деп ауыстыру","Файлдың атын <code>cowsay.py</code> деп өзгерту","Терминалда <code>pip install cowsay</code> орындау","Python-ды қайта орнату"],"a":2,"e":"<code>cowsay</code> - Python-мен бірге келмейтін сыртқы пакет. Оны алдымен <code>pip</code> пакет менеджерімен PyPI-дан орнату керек. (Файлды <code>cowsay.py</code> деп атасаңыз, керісінше, Python өз файлыңызды импорттап, шатасады!)","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"<code>sayings.py</code> файлында <code>goodbye</code> функциясы бар. Оны <code>say.py</code>-да қолдану үшін қай жол дұрыс?","o":["<code>import sayings.py</code>","<code>from sayings import goodbye</code>","<code>from goodbye import sayings</code>","<code>pip install sayings</code>"],"a":1,"e":"Модульдің аты - файл атының <code>.py</code>-сіз бөлігі. <code>from</code>-нан кейін модуль, <code>import</code>-тан кейін ондағы функция жазылады. Өз файлыңызды <code>pip</code> арқылы орнатудың қажеті жоқ, ол бір папкада тұрса жеткілікті.","l":"4-апта: Кітапханалар","u":"python/lectures/week-4.html#quiz","c":"python"},{"q":"Тест файлының атын неге <code>test_calculator.py</code> деп қоямыз?","o":["Python басқа атпен файлды іске қоспайды","Бұл - дәстүр: <code>pytest</code> <code>test_</code> деп басталатын файлдар мен функцияларды іздейді","Файл аты бағдарлама атынан ұзын болуы тиіс","Бұл тек <code>calculator.py</code> үшін ғана жұмыс істейді"],"a":1,"e":"Атау дәстүрі қатаң болмаса да, <code>pytest</code> тесттерді дәл осы <code>test_</code> префиксі арқылы тауып алады.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>square(n)</code> функциясында қателесіп <code>n * n</code> орнына <code>n + n</code> жазылған. Қай тест қатені <em>таппайды</em>?","o":["<code>assert square(3) == 9</code>","<code>assert square(-3) == 9</code>","<code>assert square(10) == 100</code>","<code>assert square(2) == 4</code>"],"a":3,"e":"2 + 2 және 2 * 2 екеуі де 4 болады, сондықтан бұл тест қатені байқамайды. Сондықтан бірнеше түрлі мәнмен тексеру керек.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>assert square(3) == 9</code> орындалмаса, Python не істейді?","o":["<code>AssertionError</code> қатесін шығарады","<code>False</code> деп шығарады да, жалғастыра береді","<code>square</code> функциясын автоматты түзетеді","Ештеңе істемейді"],"a":0,"e":"<code>assert</code> шарт ақиқат болмаса, <code>AssertionError</code> көтереді. Шарт ақиқат болса, үнсіз өтіп кетеді.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"Тесттерді <code>test_positive</code>, <code>test_negative</code>, <code>test_zero</code> деген бірнеше функцияға бөлудің басты артықшылығы қандай?","o":["Код жылдамырақ жұмыс істейді","<code>assert</code> қажет болмай қалады","Бір функция құласа да, <code>pytest</code> қалғандарын орындайды, сондықтан қателер туралы көбірек ақпарат аламыз","<code>pytest</code> тек бірнеше функциямен жұмыс істейді"],"a":2,"e":"Бір функцияның ішінде бірінші құлаған <code>assert</code>-тен кейін қалғандары орындалмайды. Бөлек функциялар бөлек іске қосылады.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>square(\"cat\")</code> шақырылғанда <code>TypeError</code> шығуын күтетін тест қалай жазылады?","o":["<code>assert square(\"cat\") == TypeError</code>","<code>with pytest.raises(TypeError):</code> блогының ішінде <code>square(\"cat\")</code>","<code>assert not square(\"cat\")</code>","<code>try: square(\"cat\")</code> және <code>except: pass</code> жеткілікті"],"a":1,"e":"<code>pytest.raises</code> блоктағы код көрсетілген қатені көтерсе, тест өтеді; көтермесе, құлайды.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"Мына <code>hello</code> функциясын <code>assert hello(\"David\") == \"hello, David\"</code> арқылы тексеруге бола ма?","o":["Иә, <code>print</code> нәтижесі <code>assert</code>-ке түседі","Иә, бірақ тек <code>pytest</code> арқылы","Жоқ, себебі функцияның аты <code>test_</code> деп басталмайды","Жоқ, себебі функция жолды қайтармайды, тек экранға жазады: оның қайтарған мәні <code>None</code>"],"a":3,"e":"Тестілеу үшін функция <code>return</code> жасауы керек. Сондықтан <code>print</code> тек <code>main</code>-де қалады.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>test</code> қалтасындағы барлық тестті <code>pytest test</code> арқылы іске қосу үшін қалтаға не қосу керек?","o":["Бос болса да, <code>__init__.py</code> файлын","<code>main.py</code> файлын","<code>pytest.txt</code> файлын","Ештеңе қосудың қажеті жоқ"],"a":0,"e":"<code>__init__.py</code> болғанда, <code>pytest</code> бүкіл қалтада орындалатын тесттер бар екенін біледі.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>pytest</code> шығысындағы қызыл <code>F</code> әрпі нені білдіреді?","o":["Тест файлы табылмады","Тест өте жақсы өтті (fine)","Тест құлады (fail): бірдеңе дұрыс емес","Функция аяқталды (finished)"],"a":2,"e":"<code>F</code> - құлаған тест, ал қызыл <code>E</code> жолдары қатенің қайда екенін көрсететін кеңестер береді.","l":"5-апта: Модульдік тесттер","u":"python/lectures/week-5.html#quiz","c":"python"},{"q":"<code>names.txt</code> файлында бірнеше ат бар. <code>open(\"names.txt\", \"w\")</code> деп ашып, бір ат жазсақ, не болады?","o":["Жаңа ат бұрынғы аттардың соңына қосылады","Файлдағы бұрынғы аттар өшіп, тек жаңа ат қалады","Қате шығады, себебі файл бұрыннан бар","Файл өзгермейді"],"a":1,"e":"<code>\"w\"</code> режимі файлды басынан қайта жазады. Бұрынғы мазмұнды сақтап, соңына қосу үшін <code>\"a\"</code> керек.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>file.write(name)</code> арқылы үш ат жазылды, бірақ файлда олар <code>HermioneHarryRon</code> болып жабысып тұр. Неге?","o":["Файл жабылмаған","<code>\"a\"</code> режимі жолдарды біріктіреді","<code>write</code> бос орындарды өшіреді","<code>write</code> <code>print</code> сияқты соңына <code>\\n</code> қоспайды"],"a":3,"e":"<code>write</code> мәтінді дәл сол күйінде жазады. Әр атты жаңа жолдан бастау үшін <code>f\"{name}\\n\"</code> деп жазу керек.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>with open(\"names.txt\") as file:</code> жазуының <code>file = open(...)</code>-тен басты артықшылығы неде?","o":["Блок аяқталғанда файл автоматты түрде жабылады","Файл тезірек оқылады","Файл жоқ болса, қате шықпайды","Файлды тек оқуға болады"],"a":0,"e":"<code>with</code> блогынан шыққан сәтте Python файлды өзі жабады, <code>close</code>-ты ұмытып кету мүмкін емес.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>names.txt</code> файлының әр жолында бір ат бар. <code>for line in file: print(\"hello,\", line)</code> неге аттардың арасында бос жол қалдырады?","o":["<code>print</code> екі рет орындалады","Файлда әр аттан кейін бос жол бар","Жолдың соңындағы <code>\\n</code> мен <code>print</code>-тің өз <code>\\n</code>-і қосылады","Үтір бос жол қосады"],"a":2,"e":"Файлдан оқылған әр жол <code>\\n</code>-мен аяқталады, оған <code>print</code>-тің әдепкі <code>\\n</code>-і қосылады. <code>line.rstrip()</code> мұны түзетеді.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"Жолда <code>Harry,\"Number Four, Privet Drive\"</code> тұр. <code>name, home = line.rstrip().split(\",\")</code> не істейді?","o":["<code>name = \"Harry\"</code>, <code>home = \"Number Four, Privet Drive\"</code>","<code>ValueError: too many values to unpack</code> қатесін береді","<code>home</code>-ға тек <code>\"Number Four</code> түседі","Тырнақшаларды өзі алып тастайды"],"a":1,"e":"<code>split</code> тырнақшаны білмейді, жолды үш бөлікке бөледі, ал айнымалы екеу ғана. Мұндай файлдарды <code>csv.reader</code> дұрыс оқиды.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>sorted(students, key=lambda student: student[\"name\"])</code> жолында <code>lambda</code> не істейді?","o":["Әр оқушының сөздігінен атын қайтаратын атсыз функция жасайды","Тізімді кері ретпен сұрыптайды","Сөздіктің барлық кілттерін қайтарады","<code>name</code> деген айнымалы жасайды"],"a":0,"e":"<code>lambda</code> - анонимді функция. <code>sorted</code> оны әр элементке қолданып, нәтижесі (аты) бойынша сұрыптайды.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"CSV файлдың бірінші жолы <code>name,home</code>. <code>csv.DictReader</code> оқыған әр <code>row</code> қандай болады?","o":["<code>[\"Harry\", \"Number Four, Privet Drive\"]</code> сияқты тізім","<code>\"Harry,Number Four, Privet Drive\"</code> сияқты жол","Бірінші жолдың өзі де <code>row</code> ретінде келеді","<code>{\"name\": \"Harry\", \"home\": \"Number Four, Privet Drive\"}</code> сияқты сөздік"],"a":3,"e":"<code>DictReader</code> тақырып жолын кілт ретінде алады да, қалған әр жолды сөздік етіп береді. Сондықтан <code>row[\"name\"]</code> деп жаза аламыз.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>python costumes.py costume1.gif costume2.gif</code> іске қосылғанда <code>sys.argv[1:]</code> неге тең?","o":["<code>[\"costumes.py\", \"costume1.gif\", \"costume2.gif\"]</code>","<code>[\"costume1.gif\"]</code>","<code>[\"costume1.gif\", \"costume2.gif\"]</code>","<code>\"costume1.gif\"</code>"],"a":2,"e":"<code>[1:]</code> тізімді екінші элементтен бастап соңына дейін кеседі, яғни бағдарламаның өз атынсыз барлық аргументті береді.","l":"6-апта: Файлдармен жұмыс","u":"python/lectures/week-6.html#quiz","c":"python"},{"q":"<code>re.search(r\"^\\w+@\\w+\\.edu$\", s)</code> үлгісіне қай жол сәйкес келеді?","o":["malan@cs50.harvard.edu","malan@harvard.edu","@harvard.edu","malan@harvard?edu"],"a":1,"e":"<code>\\w+</code> кем дегенде бір сөз таңбасын талап етеді (c жарамсыз), <code>\\.</code> нақты нүкте (d жарамсыз), ал <code>\\w</code> нүктені қамтымайды (a жарамсыз).","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"Тұрақты өрнекте жалғыз <code>.</code> нені білдіреді?","o":["Нақты нүктені","Жолдың соңын","Жаңа жолдан басқа кез келген бір таңбаны","Нөл не одан көп таңбаны"],"a":2,"e":"Нақты нүкте үшін оны <code>\\.</code> деп экрандау керек. Қайталауды <code>*</code> мен <code>+</code> білдіреді.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>re.search(r\"^[^@]+@[^@]+\\.edu$\", \"malan@@@harvard.edu\")</code> нәтижесі қандай?","o":["Сәйкестік нысаны (сәйкес келеді)","Қате (exception)","True","None (сәйкес келмейді)"],"a":3,"e":"<code>[^@]</code> «@-тен басқа таңба» дегенді білдіреді, сондықтан қатар тұрған бірнеше <code>@</code> үлгіге сыймайды. <code>search</code> нәтиже таппаса, <code>None</code> қайтарады, <code>True</code> емес.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>matches = re.search(r\"^(.+), *(.+)$\", \"Malan,David\")</code> болса, <code>matches.group(2)</code> неге тең?","o":["David","Malan","Malan,David",", David"],"a":0,"e":"Топтар бірден нөмірленеді: <code>group(1)</code> - <code>Malan</code>, <code>group(2)</code> - <code>David</code>. Бүкіл сәйкес келген мәтін - <code>group(0)</code>.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>re.search(r\"^colou?r$\", s)</code> үлгісіне <code>color</code>, <code>colour</code>, <code>colouur</code> жолдарының қайсысы сәйкес келеді?","o":["Тек color","color және colour","Үшеуі де","Ешқайсысы"],"a":1,"e":"<code>u?</code> «u 0 не 1 рет» дегенді білдіреді, ал <code>^</code> мен <code>$</code> кез келген артық таңбаға жол бермейді, сондықтан екі <code>u</code> сәйкес келмейді.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>r\"^\\w+@(\\w+\\.)?\\w+\\.edu$\"</code> үлгісіндегі <code>(\\w+\\.)?</code> нені білдіреді?","o":["Домен міндетті түрде нүктемен аяқталады","Нүктеден кейін сұрақ белгісі тұруы керек","Бұл бөлік кемінде екі рет қайталанады","Бұл бөлік бір рет болуы мүмкін немесе болмауы мүмкін (мысалы, cs50.)"],"a":3,"e":"Топқа қойылған <code>?</code> бүкіл топты міндетті емес етеді. Сондықтан <code>malan@cs50.harvard.edu</code> да, <code>malan@harvard.edu</code> да жарамды.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"Тұрақты өрнекті <code>r\"...\"</code> түрінде жазғанда <code>r</code> әрпі не істейді?","o":["Нәтижені қайтарады (return)","Үлгіні бас әріпке айналдырады","Жолды «шикі» етеді: <code>\\</code> арнайы таңба ретінде өңделмейді","Үлгіні қайталап іздейді"],"a":2,"e":"Шикі жолда <code>\\n</code> жаңа жол емес, жай <code>\\</code> мен <code>n</code>. Сондықтан <code>\\.</code> немесе <code>\\w</code> сияқты белгілер <code>re</code> кітапханасына өзгеріссіз жетеді.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>re.sub(r\"^(https?://)?(www\\.)?twitter\\.com/\", \"\", \"https://www.twitter.com/davidjmalan\")</code> нені қайтарады?","o":["davidjmalan","https://www.twitter.com/davidjmalan","www.twitter.com/davidjmalan","twitter.com"],"a":0,"e":"Үлгі жолдың басындағы хаттама, <code>www.</code> және <code>twitter.com/</code> бөлігіне сәйкес келеді де, оны бос жолмен ауыстырады. Қолданушы аты қалады.","l":"7-апта: Тұрақты өрнектер","u":"python/lectures/week-7.html#quiz","c":"python"},{"q":"<code>student = (\"Padma\", \"Gryffindor\")</code> болса, <code>student[1] = \"Ravenclaw\"</code> не істейді?","o":["Үйді Ravenclaw етіп өзгертеді","<code>TypeError</code> береді","Атты Ravenclaw етіп өзгертеді","Кортежге жаңа элемент қосады"],"a":1,"e":"Кортеж өзгермейтін (immutable), оның элементтеріне жаңа мән меншіктеуге болмайды. Өзгерту керек болса, тізім не сөздік қолданыңыз.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"Дана әдісінің ішіндегі <code>self</code> нені білдіреді?","o":["Класстың атын","Ата-ана класты","Барлық объектілердің тізімін","Әдіс шақырылған нақты объектіні"],"a":3,"e":"<code>self</code> - дәл осы объектінің өзі. <code>self.name = name</code> «осы объектінің аты» дегенді білдіреді, Python оны бірінші аргумент ретінде өзі береді.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>print(student)</code> жазғанда Python объектіні қалай көрсетерін қай әдістен біледі?","o":["<code>__str__</code>","<code>__init__</code>","<code>__add__</code>","<code>print</code>"],"a":0,"e":"<code>__str__</code> объектінің жолдық көрінісін қайтарады, <code>print</code> оны өзі шақырады.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>house</code> қасиетінің сеттері бар класта <code>student.house = \"Number Four, Privet Drive\"</code> жазылса, не болады?","o":["<code>_house</code> үнсіз өзгереді","Ештеңе болмайды","Сеттер шақырылып, <code>ValueError</code> көтеріледі","Геттер шақырылады"],"a":2,"e":"Қасиетке мән меншіктелгенде <code>@house.setter</code> әдісі іске қосылады, ол жарамсыз үйді тексеріп, <code>ValueError</code> көтереді.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>@classmethod</code> әдісінің бірінші параметрі әдетте қалай аталады және нені білдіреді?","o":["<code>self</code> - объектінің өзі","<code>cls</code> - класстың өзі","<code>super</code> - ата-ана класс","Бірінші параметр болмайды"],"a":1,"e":"Класс әдісі данаға емес, класқа тиесілі. Сондықтан ол <code>cls</code> қабылдайды және <code>Hat.sort(\"Harry\")</code> немесе <code>Student.get()</code> деп дана жасамай шақырылады.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>class Student(Wizard):</code> ішіндегі <code>super().__init__(name)</code> не істейді?","o":["Жаңа <code>Wizard</code> объектісін бөлек жасайды","<code>Student</code>-тің <code>__init__</code>-ін қайта шақырады","Атты өшіреді","Ата-ана класс <code>Wizard</code>-тың <code>__init__</code>-ін шақырады"],"a":3,"e":"<code>super()</code> ата-ана класқа жетуге мүмкіндік береді. Атты тексеріп сақтау жұмысын <code>Wizard</code> атқарады.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>Vault</code> класында <code>potter + weasley</code> жазғанда, <code>__add__(self, other)</code> ішінде <code>other</code> дегеніміз не?","o":["<code>weasley</code>, яғни <code>+</code>-тің оң жағы","<code>potter</code>, яғни <code>+</code>-тің сол жағы","Екеуінің қосындысы","<code>Vault</code> класының өзі"],"a":0,"e":"<code>self</code> - <code>+</code>-тің сол жағындағы объект, <code>other</code> - оң жағындағы.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>print(type(dict()))</code> не шығарады?","o":["<code>{}</code>","<code>dict</code>","<code>&lt;class 'dict'&gt;</code>","Қате береді"],"a":2,"e":"<code>dict()</code> - <code>dict</code> класының конструкторы, ол бос сөздік жасайды. <code>type</code> оның класын көрсетеді.","l":"8-апта: Объектіге бағытталған бағдарламалау","u":"python/lectures/week-8.html#quiz","c":"python"},{"q":"<code>print(len({1, 2, 2, 3, 3, 3}))</code> не шығарады?","o":["6","1","3","Қате"],"a":2,"e":"Жиында қайталанатын мәндер сақталмайды: <code>{1, 2, 3}</code>, яғни 3 элемент.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"<code>[n * 2 for n in range(4) if n % 2 == 0]</code> нәтижесі қандай?","o":["[0, 4]","[0, 2, 4, 6]","[2, 6]","[0, 2]"],"a":0,"e":"<code>range(4)</code> - 0, 1, 2, 3. Жұптары (0 мен 2) ғана шарттан өтіп, екіге көбейтіледі: 0 мен 4.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"Мына код не шығарады?","o":["[1, 2] [3]","(1, 2, 3) {}","Қате: аргументтер тым көп","(1, 2) {'x': 3}"],"a":3,"e":"Позициялық аргументтер <code>args</code>-қа кортеж болып, ал атымен берілгендер <code>kwargs</code>-қа сөздік болып жиналады.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"<code>def total(a, b, c): return a * 100 + b * 10 + c</code> болса, <code>total(*[1, 2, 3])</code> неге тең?","o":["Қате: тізім бір ғана аргумент","123","6","321"],"a":1,"e":"<code>*</code> тізімді тарқатады: <code>total(1, 2, 3)</code> = 100 + 20 + 3 = 123.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"Мына код не шығарады?","o":["0 1","0 0","[0, 1, 2]","1 2"],"a":0,"e":"Генератор әр сұрағанда келесі мәнді береді де, тоқтаған жерінен жалғасады: алдымен 0, сосын 1.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"Функцияның ішінде <code>balance += n</code> жолы <code>UnboundLocalError</code> береді. <code>balance</code> файлдың басында жасалған болса, мұны қалай түзетуге болады?","o":["<code>balance</code>-ты бас әріппен жазу","Функцияның басына <code>import balance</code> жазу","Функцияның басына <code>global balance</code> жазу","<code>balance: int</code> тип нұсқамасын қосу"],"a":2,"e":"<code>global</code> Python-ға бұл айнымалы жергілікті емес, жаһандық екенін айтады. Ал ең таза жол - класс қолдану.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"<code>{w: len(w) for w in [\"hi\", \"cat\"]}</code> нәтижесі қандай?","o":["[2, 3]","{'hi', 'cat'}","{2: 'hi', 3: 'cat'}","{'hi': 2, 'cat': 3}"],"a":3,"e":"Сөздіктік өрнек: кілт - сөздің өзі, мән - оның ұзындығы.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"<code>def meow(n: int): ...</code> болса, <code>python meows.py</code> арқылы іске қосқанда <code>meow(\"3\")</code> шақыруы туралы қай тұжырым дұрыс?","o":["Python бағдарламаны іске қоспай, тип қатесін көрсетеді","Python тип нұсқамасын тексермейді, мұндай қатені <code>mypy</code> табады","Python \"3\"-ті автоматты түрде <code>int</code>-ке айналдырады","Тип нұсқамасы бар функцияны тек <code>mypy</code> арқылы іске қосуға болады"],"a":1,"e":"Тип нұсқамалары - тек кеңес. Python оларды орындау кезінде тексермейді, ал <code>mypy</code> кодты іске қоспай-ақ тексереді.","l":"9-апта: Тағы басқалар","u":"python/lectures/week-9.html#quiz","c":"python"},{"q":"Бұл сұрау не қайтарады?","o":["Рейтингі ең жоғары 10 кітаптың атауы","Кестедегі алғашқы 10 жолдың атауы (кестедегі ретімен)","Кез келген 10 кітаптың атауы, әр жолы басқа","Әліпби бойынша алғашқы 10 атау"],"a":1,"e":"<code>LIMIT</code> тек жол санын шектейді. Реттеу жазылмағандықтан, жолдар кестедегі ретімен шығады.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"Аудармашысы жоқ кітаптарды қай сұрау дұрыс табады?","o":["<code>WHERE \"translator\" = NULL</code>","<code>WHERE \"translator\" = ''</code>","<code>WHERE \"translator\" IS NULL</code>","<code>WHERE NOT \"translator\"</code>"],"a":2,"e":"NULL ештеңеге, тіпті өзіне де тең емес, сондықтан <code>= NULL</code> ешқашан жолды таппайды. Тек <code>IS NULL</code> дұрыс.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"Жақшасыз жазылған мына шарт нені таңдайды?","o":["2022 жылғы барлық кітапты (қатты мұқабалысын да) және 2023 жылғы қатты мұқабалы емес кітаптарды","Ештеңе өзгермейді, жақшамен бірдей","SQLite қате береді","2022 және 2023 жылдардың қатты мұқабалы емес кітаптарын"],"a":0,"e":"<code>AND</code> оператор <code>OR</code>-дан бұрын есептеледі. Сондықтан бұл «2022 НЕМЕСЕ (2023 ЖӘНЕ қатты мұқабалы емес)». Екі жылға бірдей қолдану үшін жақша керек.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"<code>COUNT(*)</code> 65 береді, ал <code>COUNT(\"translator\")</code> 65-тен аз береді. Себебі:","o":["<code>COUNT(\"translator\")</code> тек бірегей мәндерді санайды","аудармашылар тек соңғы жылдарда бар","бағанның аты қос тырнақшада тұр","<code>COUNT(баған)</code> <code>NULL</code> мәндерін санамайды"],"a":3,"e":"Аудармашысы жоқ кітаптарда <code>translator</code> - NULL. Бірегей мәндерді санау үшін <code>DISTINCT</code> керек еді.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"Қай атау <code>LIKE 'Қыз%'</code> үлгісіне сәйкес келеді, бірақ <code>LIKE 'Қыз %'</code> үлгісіне келмейді?","o":["Қыз бала көші","Қызғалдақ тағдыры","Қыз Назым","Үшеуі де екі үлгіге сәйкес келеді"],"a":1,"e":"«Қызғалдақ» сөзінде «Қыз» әріптерінен кейін бос орын жоқ, сондықтан тек бос орынсыз үлгі оны табады.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"<code>WHERE \"year\" BETWEEN 2019 AND 2022</code> қай жылдарды қамтиды?","o":["Тек 2020 және 2021","2019, 2020 және 2021","2019, 2020, 2021 және 2022","2020, 2021 және 2022"],"a":2,"e":"<code>BETWEEN</code> шеттерін қоса алады, яғни <code>&gt;= 2019 AND &lt;= 2022</code> дегенмен бірдей.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"<code>ORDER BY \"rating\" DESC, \"votes\" DESC</code> ішіндегі <code>\"votes\" DESC</code> не істейді?","o":["Рейтингі тең кітаптардың ішінде дауысы көбі жоғары тұрады","Алдымен дауыс бойынша, сосын рейтинг бойынша реттейді","Дауысы жоқ кітаптарды алып тастайды","Ештеңе істемейді"],"a":0,"e":"Екінші баған тек бірінші баған тең болғанда ғана қолданылады: бұл «тай-брейк».","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"<code>SELECT MAX(\"title\") FROM \"longlist\";</code> нені қайтарады?","o":["Ең ұзын атауды","Ең көп дауыс жинаған кітаптың атауын","Қате: <code>MAX</code> тек сандарға арналған","Реттеу бойынша «ең үлкен», яғни соңғы атауды"],"a":3,"e":"<code>MAX</code> мәтінде де жұмыс істейді: әліпби (дәлірек, кодтау) бойынша соңғысын табады, ұзындығына қарамайды.","l":"0-апта: Сұраулар","u":"sql/lectures/week-0.html#quiz","c":"sql"},{"q":"Студенттер мен курстар арасында көп-көпке байланыс бар (студент көп курс алады, курста көп студент оқиды). Оны дерекқорда қалай іске асырамыз?","o":["<code>students</code> кестесіне курстардың барлық атауын бір ұяшыққа жазамыз","<code>courses</code> кестесіне сыртқы кілт қосамыз, одан басқа ештеңе керек емес","Екі сыртқы кілті бар үшінші (аралық) кесте жасаймыз","Екі кестені бір кестеге біріктіреміз де, студент аты қайталана берсін"],"a":2,"e":"Көп-көпке байланыс аралық кестемен іске асады: оның бір бағаны <code>students</code> кілтіне, екіншісі <code>courses</code> кілтіне сілтейді. Қалған нұсқалар артық деректер мен қателерге апарады.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"<code>ratings</code> кестесінде <code>book_id</code> бағанында бірдей мәндер бірнеше рет қайталанады. Бұл дұрыс па?","o":["Иә, ол сыртқы кілт, сыртқы кілт мәндері қайталана алады","Жоқ, кез келген кілт мәні бірегей болуы керек","Иә, бірақ тек бастапқы кілт болса ғана","Жоқ, бұл кестенің бүлінгенін білдіреді"],"a":0,"e":"Бір кітаптың бірнеше бағасы бар (бір-көпке байланыс). <code>book_id</code> - сыртқы кілт, оның мәндері қайталана алады. Бірегей болу талабы тек бастапқы кілтке қойылады.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Мына сұрау не қайтарады?","o":["Барлық кітаптың атауын","Қате хабарламасын","Бір жол, оның мәні <code>NULL</code>","Бос нәтижені (жол жоқ)"],"a":3,"e":"Ішкі сұрау ештеңе таппайды, сондықтан сыртқы шарт ешбір жолға сәйкес келмейді және нәтиже бос болады. Қате болмайды.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Автор көп кітап жазған болуы мүмкін. Қай сұрау дұрыс жұмыс істейді?","o":["<code>WHERE \"id\" = (SELECT \"book_id\" FROM \"authored\" WHERE \"author_id\" = 3)</code>","<code>WHERE \"id\" IN (SELECT \"book_id\" FROM \"authored\" WHERE \"author_id\" = 3)</code>","<code>WHERE \"id\" HAVING (SELECT \"book_id\" FROM \"authored\" WHERE \"author_id\" = 3)</code>","Екеуі де бірдей дұрыс"],"a":1,"e":"Ішкі сұрау бірнеше жол қайтара алатындықтан, <code>IN</code> керек. <code>=</code> тек бір мәнмен салыстырады және қалғанын өткізіп жібереді.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"<code>sea_lions</code> кестесінде 6 арыстан, <code>migrations</code> кестесінде 5 жазба бар, олардың 4-і арыстандарға сәйкес келеді. <code>sea_lions LEFT JOIN migrations</code> неше жол қайтарады?","o":["6 жол: сәйкес келмеген 2 арыстанның көші-қон бағандары <code>NULL</code>","4 жол: тек сәйкес келгендері","5 жол","7 жол"],"a":0,"e":"<code>LEFT JOIN</code> сол жақтағы кестенің барлық жолын сақтайды: 6 арыстанның 6-сы да шығады, 4-іне көші-қон деректері қосылады, 2-іне <code>NULL</code> қалады. Бір жазба (ID 99) оң жақта қалып қояды, нәтижеге кірмейді.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Авторлар жиыны: Аян, Бану, Ғалым. Аудармашылар жиыны: Ғалым, Дана. Мына сұрау не қайтарады?","o":["Ғалым","Аян, Бану, Ғалым, Дана","Дана","Аян, Бану"],"a":3,"e":"<code>EXCEPT</code> бірінші жиыннан екінші жиынды алып тастайды: авторлардан Ғалымды (ол аудармашы да) шығарсақ, Аян мен Бану қалады.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Студент орташа бағасы 4-тен жоғары кітаптарды іздеді де, қате тапты. Қатесі неде?","o":["<code>GROUP BY</code> жолы <code>WHERE</code>-ден бұрын тұруы керек","Топқа шарт <code>WHERE</code> емес, <code>HAVING</code> арқылы жазылады","<code>AVG</code> орнына <code>COUNT</code> қолдану керек","Қате жоқ, сұрау жұмыс істейді"],"a":1,"e":"<code>WHERE</code> топтау алдында жеке жолдарды сүзеді, сондықтан онда <code>AVG(...)</code> қолдануға болмайды. Дұрысы: <code>GROUP BY \"book_id\" HAVING AVG(\"rating\") &gt; 4</code>.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Мына сұрау қанша жол қайтарады, егер <code>ratings</code> кестесінде 12 түрлі кітапқа 53 баға берілген болса?","o":["51 жол","1 жол","12 жол: әр кітапқа бір жол","63 жол"],"a":2,"e":"<code>GROUP BY</code> жолдарды кітап бойынша топтайды, әр топ бір жолға айналады. Топтың ішіндегі бағалар санын <code>COUNT</code> есептейді.","l":"1-апта: Байланыстар","u":"sql/lectures/week-1.html#quiz","c":"sql"},{"q":"Бір кестеде жолаушының аты 1000 жолда қайталанып тұр. Нормалау бұған не істейді?","o":["Барлық аттарды бас әріппен жазуға мәжбүрлейді","Жолаушыларды бөлек кестеге шығарып, негізгі кестеде тек олардың <code>id</code>-ін сақтайды","Қайталанатын жолдарды автоматты түрде жояды","Кестені екі дерекқорға бөледі"],"a":1,"e":"Нормалау - әр нысанды өз кестесіне шығару. Атты бір рет сақтап, басқа кестелерден <code>id</code> (сыртқы кілт) арқылы сілтейміз.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"Жолаушылар мен станциялар көп-көптік байланыста. Мұны кестелермен қалай бейнелейміз?","o":["<code>riders</code> кестесінің ішіне барлық станция аттарын үтірмен жазамыз","<code>stations</code> кестесіне жолаушының аты бағанын қосамыз","Екі кестені бір атпен біріктіреміз","Үшінші, аралық кесте жасаймыз (<code>rider_id</code>, <code>station_id</code>)"],"a":3,"e":"Көп-көптік байланысты аралық кесте (junction table) шешеді: әр жолы «мына жолаушы мына станцияға барды» дегенді білдіреді.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"Жол ақысын неге <code>REAL</code> бағанында сақтау қауіпті бола алады?","o":["Қалқымалы үтірлі сандар екілік жүйеде дәл сақталмайды, есептеулерде ұсақ қате жиналуы мүмкін","<code>REAL</code> тек теріс сандарды сақтайды","<code>REAL</code> бағанына сан салуға болмайды","<code>REAL</code> бағандары <code>SUM</code>-мен қосылмайды"],"a":0,"e":"Мысалы, <code>0.1 + 0.2 = 0.3</code> SQLite-та 0 (жалған) береді. Сондықтан ақшаны көбіне центпен, Integer ретінде сақтайды.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"<code>\"a\" INTEGER</code> бағанына <code>INSERT</code>-пен <code>'25'</code> (мәтін) салынды. <code>typeof(\"a\")</code> не қайтарады?","o":["<code>text</code>, баған мәнді өзгертпейді","Қате шығады","<code>integer</code>, Integer афинитеті мәнді бүтін санға түрлендіреді","<code>null</code>"],"a":2,"e":"Тип афинитеті - баған кіріс мәнін өзі ұнататын типке түрлендіруге тырысады. «25» мәтіні бүтін 25-ке айналады.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"Мына схема бар: <code>\"name\" TEXT NOT NULL UNIQUE</code>. Қай <code>INSERT</code> сәтсіз болады, егер <code>'Harvard'</code> аты кестеде бұрыннан бар болса?","o":["<code>VALUES ('Kendall')</code>","<code>VALUES ('Harvard')</code> немесе аты көрсетілмеген (NULL) жол","<code>VALUES ('harvard station')</code>","Ешқайсысы, бәрі өтеді"],"a":1,"e":"<code>UNIQUE</code> қайталануға, ал <code>NOT NULL</code> бос мәнге жол бермейді.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"<code>visits</code> кестесіне <code>PRIMARY KEY(\"rider_id\", \"station_id\")</code> қойдық. Қандай проблема шығады?","o":["Кестеге ешқандай жол қосуға болмайды","Жолаушылар аттары қайталана алмайды","Станция тек бір жолаушыға тиесілі болады","Жолаушы бір станцияға екінші рет бара алмайды, өйткені жұп бірегей болуы керек"],"a":3,"e":"Құрама кілт жұптың бірегейлігін талап етеді. Біз жолаушының бір станцияға бірнеше рет баруына рұқсат бергіміз келеді, сондықтан бұл жол жарамайды.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"<code>swipes</code> кестесіндегі <code>\"type\"</code> бағанының атын <code>\"swipetype\"</code>-тан <code>\"type\"</code>-қа өзгертетін команда қайсы?","o":["<code>ALTER TABLE \"swipes\" RENAME COLUMN \"swipetype\" TO \"type\";</code>","<code>ALTER TABLE \"swipes\" RENAME TO \"type\";</code>","<code>UPDATE \"swipes\" SET \"swipetype\" = \"type\";</code>","<code>DROP COLUMN \"swipetype\";</code>"],"a":0,"e":"<code>RENAME TO</code> кестенің атын өзгертеді, ал бағанның атын <code>RENAME COLUMN ... TO ...</code> өзгертеді.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"<code>CHECK(\"amount\" != 0)</code> шектеуі бар. Қай жол <code>INSERT</code> кезінде қабылданбайды?","o":["<code>amount = -2.4</code>","<code>amount = 20</code>","<code>amount = 0</code>","<code>amount = 0.5</code>"],"a":2,"e":"Шарт «0-ге тең емес» дейді, сондықтан тек <code>0</code> өтпейді. Теріс сома (жол ақысы) да, оң сома (ақша салу) да дұрыс.","l":"2-апта: Жобалау","u":"sql/lectures/week-2.html#quiz","c":"sql"},{"q":"<code>collections</code> кестесінде бастапқы кілт <code>id</code> бар және қазір ең үлкен <code>id</code> = 5. Мына команданы орындасақ, жаңа жолдың <code>id</code>-і не болады?","o":["<code>NULL</code>, себебі <code>id</code> көрсетілмеген","Қате шығады: <code>id</code> міндетті түрде жазылуы керек","6: SQLite ең үлкен мәнге бірді қосады","1: ең кіші бос нөмір беріледі"],"a":2,"e":"<code>id</code> бағанын жазбасақ, SQLite бастапқы кілтті өзі береді: кестедегі ең үлкен мәнді тауып, бірге арттырады.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"<code>DELETE FROM \"collections\";</code> командасы (<code>WHERE</code> жоқ) орындалса, не болады?","o":["Кестедегі барлық жол өшеді, ал кестенің өзі (схемасы) қалады","Қате шығады: <code>WHERE</code> міндетті","Тек бірінші жол өшеді","Кесте де, ішіндегі деректер де жоғалады"],"a":0,"e":"Шарт болмаса, <code>DELETE</code> барлық жолға қолданылады. Кестенің өзін өшіру үшін <code>DROP TABLE</code> керек.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"Бір <code>INSERT</code>-пен үш жол қосып жатырмыз, бірақ екінші жолдың <code>accession_number</code>-і кестедегі барымен қайталанады (<code>UNIQUE</code>). Нәтиже қандай?","o":["Бірінші жол қосылады, қалғаны өтіп кетеді","Бірінші және үшінші жол қосылады, екіншісі өтіп кетеді","Үшеуі де қосылады, қайталанған нөмір автоматты өзгереді","Қате шығады және үш жолдың бірде-бірі қосылмайды"],"a":3,"e":"Бір команда ретінде қосылатын топтамада шектеу бұзылса, бүкіл команда сәтсіз аяқталады.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"Суретші өшірілгенде, <code>created</code> кестесіндегі жолдар өшпей, тек <code>artist_id</code> бағаны <code>NULL</code> болып қалуын қаласақ, сыртқы кілтке не жазамыз?","o":["<code>ON DELETE CASCADE</code>","<code>ON DELETE SET NULL</code>","<code>ON DELETE RESTRICT</code>","<code>ON DELETE NO ACTION</code>"],"a":1,"e":"<code>SET NULL</code> өшіруге рұқсат береді, ал сілтеме жасаушы сыртқы кілтті <code>NULL</code> етеді. <code>CASCADE</code> жолдардың өзін өшірер еді, <code>RESTRICT</code> өшіруге тыйым салар еді.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"Кодтағы қатені табыңыз. Мақсат: тек «Spring outing» суретінің күнін <code>NULL</code> ету.","o":["<code>NULL</code> мәнін <code>SET</code>-те қолдануға болмайды","<code>UPDATE</code> орнына <code>INSERT</code> керек","Баған аты тырнақшасыз жазылуы керек","<code>WHERE \"title\" = 'Spring outing'</code> жоқ: барлық суреттің күні <code>NULL</code> болады"],"a":3,"e":"<code>WHERE</code> жоқ <code>UPDATE</code> кестенің барлық жолын өзгертеді. Алдымен сол шартпен <code>SELECT</code> жасап тексеру - жақсы әдет.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"Мына триггерде <code>NEW.\"title\"</code> нені білдіреді?","o":["Жаңа ғана <code>collections</code>-қа қосылған жолдың <code>title</code> мәнін","<code>transactions</code> кестесінің жаңа бағанын","Өшірілген жолдың <code>title</code> мәнін","Кез келген алдыңғы жолдың <code>title</code> мәнін"],"a":0,"e":"<code>INSERT</code> триггерінде <code>NEW</code> қосылып жатқан жолға сілтейді. Өшіру триггерінде оның орнына <code>OLD</code> қолданылады.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"Жұмсақ жою қолданған кестеден «өшірілмеген» жолдарды таңдау үшін қай сұрау дұрыс (<code>deleted</code> бағанының әдепкісі 0)?","o":["<code>DELETE FROM \"collections\" WHERE \"deleted\" = 0;</code>","<code>SELECT * FROM \"collections\" WHERE \"deleted\" = 1;</code>","<code>SELECT * FROM \"collections\" WHERE \"deleted\" != 1;</code>","<code>SELECT * FROM \"collections\";</code> (қосымша шартсыз)"],"a":2,"e":"Жұмсақ жоюда жол жойылмайды, тек <code>deleted = 1</code> деп белгіленеді. Сондықтан оқығанда <code>deleted != 1</code> шартымен сүзгіден өткіземіз.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"CSV-ден импорттағаннан кейін <code>acquired</code> бос болған жолда <code>\"acquired\" IS NULL</code> шарты орындалмай жатыр. Себебі және түзету жолы қандай?","o":["Импорт қате болды, кестені қайта жасау керек","Бос ұяшық бос мәтін (<code>''</code>) болып импортталған; <code>UPDATE ... SET \"acquired\" = NULL WHERE \"acquired\" = ''</code> арқылы түзетеміз","<code>IS NULL</code> CSV-дегі кестелермен жұмыс істемейді","<code>DELETE</code> арқылы осы жолды өшіріп, қайта қосу керек"],"a":1,"e":"Бос мәтін мен <code>NULL</code> - екі түрлі мән. Импорттан кейін бос мәтіндерді <code>NULL</code>-ға айналдыру - деректерді тазалаудың типтік қадамы.","l":"3-апта: Жазу","u":"sql/lectures/week-3.html#quiz","c":"sql"},{"q":"<code>CREATE VIEW \"longlist\" AS SELECT ...</code> орындалғаннан кейін көрініс туралы қайсысы дұрыс?","o":["Нәтиже жолдары жаңа кестеге көшіріліп, диск орнын көп алады","Көрініс бір рет жасалады да, негізгі кестелер өзгергенде өзгермейді","Көрініс деректі өзінде сақтамайды, оны сұраған сайын негізгі кестелерден есептейді","Көріністі тек оны жасаған байланыста ғана көруге болады"],"a":2,"e":"Көрініс - виртуалды кесте, яғни сақталған сұрау. Деректі әр сұрау сайын негізгі кестелерден алады, сондықтан әрқашан жаңа болады.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"<code>ratings</code> кестесіне жаңа баға қосылды. <code>average_book_ratings</code> көрінісіндегі орташа баға қалай жаңарады?","o":["Ештеңе істеудің керегі жоқ: көріністі қайта <code>SELECT</code> жасасақ, жаңа орташа шығады","Көріністі <code>DROP VIEW</code> арқылы өшіріп, қайта жасау керек","Көрініске <code>UPDATE</code> жасау керек","Көрініс жаңармайды, ол жасалған сәттегі күйінде қалады"],"a":0,"e":"Көрініс әр сұрауда негізгі кестелерден деректі қайтадан оқиды, сондықтан қайта сұрау жеткілікті.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"Бір күрделі сұрау ішінде ғана керек уақытша кесте қажет. Қайсысы ең дұрыс таңдау?","o":["<code>CREATE VIEW</code>, себебі ол ең жылдам","<code>CREATE TEMPORARY VIEW</code>, ол дерекқорды біржола өзгертеді","Жаңа кесте жасап, оған дерек көшіру","<code>WITH ... AS (...)</code>: CTE тек сол бір сұрауда өмір сүреді және схемаға ештеңе қалдырмайды"],"a":3,"e":"CTE бір сұраудың ішінде ғана тұрады. Уақытша көрініс байланыс жабылғанша қалады, ал қалыпты көрініс схемада мәңгі тұрады.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"Мына сұраудың нәтижесі не?","o":["Жаңа кітап есепке алынбайды, себебі көрініс жасалған кезде оның жолы жоқ еді","Жаңа кітап саналады, себебі көрініс әр сұрауда <code>books</code> кестесінен деректі қайта оқиды","Қате шығады, себебі көрініс аты саннан басталады","Қате шығады, себебі көрініс бар кестеге <code>INSERT</code> жасауға болмайды"],"a":1,"e":"Көрініс тырнақшамен жазылған болса, аты санмен басталса да болады. <code>INSERT</code> негізгі <code>books</code> кестесіне жасалды, ал көрініс оны келесі сұрауда көреді.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"Талдаушыға тек <code>analysis</code> көрінісін беріп, <code>rides</code> кестесін жасырмадық. SQLite-та не болады?","o":["Талдаушы аттарды көре алмайды, себебі көріністе жасырылған","Талдаушы көріністі де көре алмайды","SQLite-та қолжетімділікті басқару жоқ, сондықтан талдаушы <code>rides</code> кестесін сұрап, жолаушы аттарын көре алады","<code>rides</code> кестесінің аттары автоматты түрде <code>Anonymous</code> болып өзгереді"],"a":2,"e":"Көрініс негізгі кестені қорғамайды. Нағыз қорғаныс үшін қолжетімділікті басқаратын дерекқор жүйесі керек.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"<code>SELECT \"title\" FROM \"current_collections\"</code> сұрауы жұмсақ жойылған туындыны не үшін көрсетпейді?","o":["Себебі жұмсақ жойылған жол кестеден физикалық түрде өшіріледі","Себебі көріністі жасайтын сұрауда <code>WHERE \"deleted\" = 0</code> шарты бар","Себебі <code>current_collections</code> бос көрініс","Себебі триггер жолды көрініске жазбаған"],"a":1,"e":"Жұмсақ жоюда жол кестеде қалады, тек <code>deleted</code> = 1 болады. Көрініс оны <code>WHERE</code> шартымен сүзіп тастайды.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"<code>INSTEAD OF DELETE ON \"current_collections\"</code> триггерінің ішіндегі <code>OLD.\"id\"</code> нені білдіреді?","o":["Жаңадан қосылатын жолдың ID-ін","Кестедегі ең бірінші жолдың ID-ін","<code>deleted</code> бағанының ескі мәнін","Көріністен өшірілмекші болған жолдың ID-ін, соның негізінде негізгі кестедегі сәйкес жолды табамыз"],"a":3,"e":"<code>OLD</code> - өшірілетін (немесе өзгертілетін) жолдың ескі күйі. Триггер сол ID арқылы <code>collections</code>-тағы жолды <code>deleted = 1</code> етеді.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"<code>average_book_ratings</code> көрінісінен жыл бойынша <code>AVG(\"rating\")</code> алынды. Бұл нені береді?","o":["Әр кітаптың орташа бағасының жыл бойынша орташасы (орташаның орташасы)","Жылдағы барлық жеке бағаның орташасы, әр кітаптың баға санын ескеріп","Жылдағы кітап саны","Қате, себебі агрегатты көрініске қайта қолдануға болмайды"],"a":0,"e":"Көріністегі <code>rating</code> бағанында әр кітаптың орташасы тұр. Оны жыл бойынша қайта орташалау «орташаның орташасын» береді, әр кітап бір «дауыс» болады.","l":"4-апта: Көріністер","u":"sql/lectures/week-4.html#quiz","c":"sql"},{"q":"<code>\"email\"</code> бағанында индекс жоқ. <code>EXPLAIN QUERY PLAN SELECT * FROM \"users\" WHERE \"email\" = 'a@b.kz';</code> қандай жоспар шығарады?","o":["<code>SEARCH users USING INDEX email</code>","<code>SCAN users</code>: кесте жолдарын түгел қарап шығады","Қате: индекс жоқ болса, сұрау орындалмайды","<code>SEARCH users USING INTEGER PRIMARY KEY</code>"],"a":1,"e":"Бағанда индекс болмаса, SQLite-тың басқа амалы жоқ: кестені сканерлейді. Сұрау орындалады, тек баяу болуы мүмкін.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"<code>SELECT * FROM \"movies\" WHERE \"id\" = 100;</code> сұрауы үшін индексті өзіміз құрмасақ та, жоспарда <code>SEARCH ... USING INTEGER PRIMARY KEY</code> шығады. Неге?","o":["SQLite әр сұрау алдында индекс құрады","<code>id</code> саны кіші болғандықтан","<code>EXPLAIN QUERY PLAN</code> индексті өзі құрып жібереді","Бастапқы кілт бағанына арналған индекс автоматты түрде бар"],"a":3,"e":"Бастапқы кілт бойынша іздеуге арналған индексті SQLite кесте құрылғанда өзі жасайды. Қарапайым бағандарға (мысалы, <code>title</code>) ондай индекс болмайды.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"<code>stars</code> кестесінде <code>(\"person_id\", \"movie_id\")</code> индексі бар. Қай сұрау үшін ол <em>жабық индекс</em> болады?","o":["<code>SELECT \"movie_id\" FROM \"stars\" WHERE \"person_id\" = 5;</code>","<code>SELECT * FROM \"stars\" WHERE \"movie_id\" = 5;</code>","<code>SELECT \"title\" FROM \"movies\" WHERE \"id\" = 5;</code>","Ешқайсысы үшін емес"],"a":0,"e":"Бірінші сұрауда іздейтін (<code>person_id</code>) және қайтаратын (<code>movie_id</code>) мәндер екеуі де индекстің ішінде, сондықтан кестеге бару керек емес. Екінші сұраудың басты бағаны <code>movie_id</code> емес, үшіншісі басқа кестеге қатысты.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"Әріптесіңіз «кестенің әр бағанына индекс құрайық, сонда ешқашан баяу болмайды» дейді. Басты қарсы дәлел қандай?","o":["Индекстер сұрауды баяулатады","Бір кестеге бірден артық индекс құруға болмайды","Әр индекс қосымша орын алады және әр <code>INSERT</code> кезінде барлық индекс жаңартылады","Индекс <code>SELECT</code>-те ғана жұмыс істейді, <code>WHERE</code>-де істемейді"],"a":2,"e":"Индекс іздеуді жылдамдатады, бірақ орын алады және деректі қосуды баяулатады: жаңа мән әр B-ағашқа орналасуы тиіс.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"<code>CREATE INDEX \"recents\" ON \"movies\" (\"title\") WHERE \"year\" = 2023;</code> индексі бар. Қай сұрау бұл индексті қолдана алады?","o":["<code>SELECT \"title\" FROM \"movies\" WHERE \"year\" = 1994;</code>","<code>SELECT \"title\" FROM \"movies\" WHERE \"title\" LIKE 'A%';</code>","<code>SELECT * FROM \"movies\";</code>","<code>SELECT \"title\" FROM \"movies\" WHERE \"year\" = 2023;</code>"],"a":3,"e":"Ішінара индексте тек 2023 жылғы жолдар бар, сондықтан тек сол шартты қамтитын сұрау оны қолдана алады.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"Үлкен индексті <code>DROP INDEX</code> арқылы жойдыңыз, бірақ <code>du -b movies.db</code> файл өлшемі кішірейгенін көрсетпейді. Не істеу керек?","o":["Дерекқорды қайта құру ғана көмектеседі","<code>VACUUM;</code> орындау: бос белгіленген орын файлдан шынымен алынады","Индексті қайта құру","Ештеңе: файл өлшемі ешқашан кішірейе алмайды"],"a":1,"e":"<code>DROP INDEX</code> орынды тек «бос» деп белгілейді. <code>VACUUM</code> файлды қайта жинап, бос орынды қайтарады.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"Транзакция ішінде екі <code>UPDATE</code> бар; екіншісі <code>CHECK</code> шектеуін бұзады. Орындалған бірінші <code>UPDATE</code> мен <code>ROLLBACK</code>-тен кейін кестедегі деректер қандай болады?","o":["Транзакцияға дейінгі күйінде: екі өзгеріс те жоққа шығарылады","Тек бірінші <code>UPDATE</code> қолданылған","Тек екінші <code>UPDATE</code> қолданылған","Кесте жойылады"],"a":0,"e":"<code>ROLLBACK</code> транзакция басталғаннан бергі барлық өзгерісті қайтарады. Бұл транзакцияны атомарлы және үйлесімді етеді.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"Бір терминалда <code>BEGIN EXCLUSIVE TRANSACTION;</code> орындалды және аяқталмады. Екінші терминал сол дерекқордан оқып көрсе, не болады?","o":["Ол ескі деректі қатесіз оқиды","Оқуға болады, тек жазуға болмайды","Дерекқор құлыпталған деген қате алады","Бірінші транзакция өздігінен тоқтатылады"],"a":2,"e":"Айрықша (EXCLUSIVE) құлып басқа транзакцияларға оқуға да тыйым салады. SQLite-та бұл бүкіл дерекқорды құлыптайды.","l":"5-апта: Оңтайландыру","u":"sql/lectures/week-5.html#quiz","c":"sql"},{"q":"<code>mysql -u root -h 127.0.0.1 -P 3306 -p</code> командасындағы соңғы <code>-p</code> нені білдіреді?","o":["Порт нөмірін","Дерекқордың атын","Қосылғанда құпиясөзді сұрауды","Пайдаланушының рөлін (<code>root</code>)"],"a":2,"e":"Порт - <code>-P</code> (бас әріп), пайдаланушы - <code>-u</code>, хост - <code>-h</code>. Кіші <code>-p</code> серверге «құпиясөзді сұра» дегенді айтады.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"Станцияның метро желісі тек <code>blue</code>, <code>green</code>, <code>orange</code>, <code>red</code> болуы мүмкін. MySQL-де бұған қай тип қолайлы?","o":["<code>ENUM('blue', 'green', 'orange', 'red')</code>","<code>TEXT</code>, себебі ол кез келген жолды сақтайды","<code>BLOB</code>","<code>DECIMAL(4,0)</code>"],"a":0,"e":"Мүмкін мәндерді алдын ала білсек, <code>ENUM</code> бағанды сол тізіммен шектейді. Жаңа желі (мысалы, silver) қосылса, <code>ALTER TABLE ... MODIFY</code> жасаймыз.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"MySQL-де сақталған процедураны жасамас бұрын неге <code>delimiter //</code> деп жазамыз?","o":["Процедура тек <code>//</code> арқылы ғана іске қосылады","Бұл процедураның атын көрсетеді","Бұл кестедегі баған шектеуін қояды","Әйтпесе процедура денесіндегі бірінші <code>;</code> көрген бойда MySQL команданы бітті деп санап, процедураны үзіп жібереді"],"a":3,"e":"Процедураның ішіндегі әр команда <code>;</code>-пен аяқталады. Бөлгішті уақытша <code>//</code> қылсақ, MySQL процедураны <code>END//</code> дейін бір бүтін ретінде оқиды. Соңында <code>delimiter ;</code> деп қайтарамыз.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"Әлеуметтік желіде пост «лайктарының» саны бірнеше секундқа ескі көрінсе де, жауап жылдамдығы өте маңызды. Қай репликацияны таңдаймыз?","o":["Синхронды: жетекші барлық репликаның көшіргенін күтеді","Асинхронды: жетекші күтіп тұрмайды, өзгерісті репликаларға ақырындап жеткізеді","Репликация қажет емес, тек <code>root</code> дерекқор қызметін атқарады","Қателікті болдырмау үшін тек қолмен көшіру"],"a":1,"e":"Деректің бірнеше секундқа «ескіруі» әлеуметтік желіге қауіпсіз, ал жылдамдық маңызды. Қаржы мен денсаулық сақтауда керісінше синхронды әдіс таңдалады.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"Дерекқор 3 серверге <strong>шардталған</strong>, бірақ реплика жоқ. Серверлердің бірі істен шықты. Не болады?","o":["Дерекқор толық емес болып қалады: бұл - жалғыз ақаулық нүктесі мәселесі","Қалған екі сервер құлаған серверді автоматты түрде толық көшіреді","Ештеңе өзгермейді, себебі шардинг репликацияны қамтиды","Қызу нүкте жоғалады"],"a":0,"e":"Шардингте әр серверде деректің тек бір бөлігі болады. Көшірмесіз сервер құласа, сол бөлік қолжетімсіз, ал жүйе жартылай жарамсыз. Шешім - шардтарға репликаларды қосу.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"<code>root</code> ретінде <code>GRANT SELECT ON `rideshare`.`analysis` TO 'carter';</code> орындалды (<code>analysis</code> - view). Carter-ге не қолжетімді?","o":["<code>rideshare</code> дерекқорындағы барлық кестелер","Сервердегі барлық дерекқор","Тек <code>analysis</code> view-інен <code>SELECT</code> жасау; түпнұсқа <code>rides</code> кестесі көрінбейді","Ештеңе, view-ге құқық беруге болмайды"],"a":2,"e":"Құқық дәл көрсетілген объектіге ғана беріледі. Сондықтан атаулары анонимделген view-ді көреді, ал жолаушылардың шын аттары бар <code>rides</code> кестесін көрмейді.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"Қолданба сұрауды жолдарды жымдастырып жасайды: <code>WHERE user = 'Carter' AND password = '...'</code>. Зиянкес құпиясөз өрісіне <code>x' OR '1' = '1</code> жазды. Не болады?","o":["Ештеңе: сервер қате шығарады және сұрауды тоқтатады","Тек Carter-дің жолы қайтады","Нәтиже бос болады, себебі құпиясөз дұрыс емес","<code>OR '1' = '1'</code> әрдайым ақиқат, сондықтан барлық пайдаланушының жолдары қайтады"],"a":3,"e":"Жымдастырылған сұрау: <code>... password = 'x' OR '1' = '1'</code>. Шарттың екінші бөлігі әрдайым ақиқат, сондықтан кестедегі әр жол сәйкес келеді. Қорғаныс - дайындалған сұрау (<code>?</code> орынбасары).","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"<code>PREPARE</code> жасалған <code>... WHERE `id` = ?</code> сұрауына <code>SET @id = '1 UNION SELECT * FROM `accounts`';</code> беріп, <code>EXECUTE</code> істеді. Нәтижесі қандай?","o":["<code>accounts</code> кестесіндегі барлық шот","Тек ID-і 1 шот; <code>UNION</code> бөлігі орындалмайды, ол мәннің бір бөлігі ретінде өңделеді","Синтаксис қатесі, себебі <code>UNION</code> жазуға болмайды","<code>accounts</code> кестесі жойылады"],"a":1,"e":"Дайындалған сұраудағы <code>?</code> орнына қойылған мән SQL коды болып орындалмайды, ол - тек деректің мәні. Сондықтан шабуыл орындалмайды.","l":"6-апта: Масштабтау","u":"sql/lectures/week-6.html#quiz","c":"sql"},{"q":"Іздеу есебінде <strong>ауысу моделі</strong> (<code>Result(s, a)</code>) нені қайтарады?","o":["Күйдегі мүмкін әрекеттер жиынын","<code>s</code> күйінде <code>a</code> әрекетін жасағаннан шығатын жаңа күйді","Күйдің мақсат екенін көрсететін True/False","Бастапқы күйден <code>s</code>-ке дейінгі жол құнын"],"a":1,"e":"<code>Actions(s)</code> әрекеттер жиынын, ал <code>Result(s, a)</code> нәтиже күйді береді. Мақсатты тексеру True/False қайтарады, жол құны бөлек ұғым.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Түйін (<code>Node</code>) мен шекараның (frontier) рөлі қалай бөлінеді?","o":["Түйін іздейді, ал шекара деректерді сақтайды","Екеуі де тек күйді сақтайды","Шекара жолдың құнын есептейді, түйіннің қажеті жоқ","Түйін күй, ата-ана, әрекет, құнды сақтайды; шекара келесіде қай түйінді алуды басқарады"],"a":3,"e":"Түйін - жай ғана деректер құрылымы, ол іздемейді. Іздеуді шекара басқарады: стек болса DFS, кезек болса BFS. Ата-ана мен әрекет жолды артқа қарай қайта жинауға керек.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Шекараны стек етіп алсақ (<code>self.frontier[-1]</code>), қандай алгоритм шығады?","o":["Тереңдік бойынша іздеу (DFS)","Ені бойынша іздеу (BFS)","Ашкөз ең жақсыны алдымен іздеу","A* іздеу"],"a":0,"e":"Соңғы қосылған түйін бірінші алынады (LIFO): алгоритм бір бағытпен мүмкіндігінше терең кетеді. Кезек (<code>[0]</code>) BFS береді.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Лабиринтте BFS жолы 10 қадам, DFS жолы 22 қадам шықты. Бұл нені көрсетеді?","o":["BFS-тің коды қате, екеуі бірдей болуы тиіс","DFS әрқашан BFS-тен ұзын жол табады","BFS ең қысқа жолды табуға кепіл береді, ал DFS кездейсоқ ұзын жолды таңдап қалуы мүмкін","DFS-те қарап шыққан күйлер жиыны жоқ"],"a":2,"e":"DFS «бағына қарай» дұрыс жолды тез табуы да, ұзын айналма жолға кетіп қалуы да мүмкін. Барлық қадамның құны бірдей болғанда BFS әрқашан оңтайлы. «Әрқашан ұзын» деу қате: кейде DFS те оңтайлы жолды табады.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Манхэттен қашықтығы (4, 1) ұяшығынан (1, 5) мақсатына дейін неге тең?","o":["3","7","4","5"],"a":1,"e":"|4 - 1| + |1 - 5| = 3 + 4 = 7. Қабырғалар есепке алынбайды.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"A* іздеу ашкөз іздеуден нешімен ерекшеленеді?","o":["A* тек <em>h(n)</em>-ді қолданады, ашкөз <em>g(n)</em>-ді де қолданады","A* үшін эвристика қажет емес","A* әрқашан ашкөзден аз күй қарап шығады","A* <em>g(n) + h(n)</em> қосындысын қарайды, яғни жүріп өткен құнды да ескереді"],"a":3,"e":"Ашкөз тек болжамды құнға (<em>h</em>) қарайды. A* оған осы уақытқа дейінгі құнды (<em>g</em>) қосады, сондықтан ұзақ жолға түсіп кетсе, оралып, басқа нұсқаны қарастырады. Қарап шығатын күй саны әрқашан аз бола бермейді.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Minimax-та минимайзер (O) қай мәнді таңдайды?","o":["Ең төмен мәнді (utility -1-ге жақын)","Ең жоғары мәнді","Ең бірінші табылған мәнді","Әрқашан 0-ді"],"a":0,"e":"X (максимайзер) утилитаны арттырады, ал O (минимайзер) азайтады. Алгоритм екі деңгейде кезек-кезек <code>max</code> және <code>min</code> алады.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"Альфа-бета кесу туралы қайсысы дұрыс?","o":["Ол minimax нәтижесін жуықтап, кейде басқа жүріс береді","Ол тек шахматта жұмыс істейді","Ол minimax-тың нәтижесін өзгертпейді, тек бос тармақтарды қарамай, жылдамдатады","Ол бағалау функциясын қажет етеді"],"a":2,"e":"Қиылған тармақтар қорытынды шешімге әсер ете алмайтыны дәлелденген, сондықтан жауап дәл сол күйінде қалады. Бағалау функциясы тереңдігі шектелген minimax-қа керек.","l":"0-апта: Іздеу","u":"ai/lectures/week-0.html#quiz","c":"ai"},{"q":"«Егер жаңбыр жауса, мен үйдемін» (<code>P → Q</code>) деп айттыңыз. Жаңбыр жауған жоқ, ал сіз көшедесіз. Бұл сөйлем қандай?","o":["Жалған, себебі сіз үйде емессіз","Анықталмаған, ақиқат кестесінде мұндай жол жоқ","Ақиқат, алғышарт жалған болғандықтан","Ақиқат, себебі <code>Q</code> ақиқат"],"a":2,"e":"Алғышарт <code>P</code> жалған болса, импликация (салдар қандай болса да) тривиальды түрде ақиқат. Сөзіңізді жоққа шығаратын ештеңе болған жоқ.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Білім қорында 4 ұсыныстық символ бар. Модельдерді тексеру алгоритмі неше модельді қарауы керек?","o":["16","8","4","24"],"a":0,"e":"Әр символға екі мән берілетіндіктен, <code>n</code> символ үшін 2<sup>n</sup> модель бар: 2⁴ = 16.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Резолюция арқылы <code>KB ⊨ α</code> екенін дәлелдеу үшін не істейміз?","o":["<code>KB ∨ α</code> ақиқат екенін тексереміз","Барлық модельді санап шығамыз","<code>α</code> ақиқат екенін ұйғарып, қайшылық іздейміз","<code>(KB ∧ ¬α)</code> өрнегін CNF-ке келтіріп, бос дизъюнкт шығатынын іздейміз"],"a":3,"e":"Қайшылық арқылы дәлелдеу: <code>KB ∧ ¬α</code> қайшылыққа (бос дизъюнктке) әкелсе, <code>¬α</code> жалған, демек <code>KB ⊨ α</code>.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Екі ұсыныс <code>P</code>, <code>Q</code>. KB = <code>P ∧ (P → Q)</code>. KB неше модельде ақиқат және нені қамтиды?","o":["Үш модельде, <code>Q</code> ілеспейді","Бір модельде (<code>P</code> және <code>Q</code> ақиқат), <code>KB ⊨ Q</code>","Бір модельде, бірақ <code>Q</code> ілеспейді","Екі модельде, <code>KB ⊨ Q</code>"],"a":1,"e":"<code>P</code> ақиқат болуы керек, ал <code>P → Q</code> ақиқат болуы үшін <code>Q</code> да ақиқат. KB тек {P = True, Q = True} моделінде ақиқат, онда <code>Q</code> ақиқат, демек <code>KB ⊨ Q</code>.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Мына екі өрнектің қайсысы <code>P → Q</code> өрнегіне логикалық тең?","o":["<code>¬P ∨ Q</code>","<code>P ∨ ¬Q</code>","<code>¬P ∧ Q</code>","<code>Q → P</code>"],"a":0,"e":"Импликацияны жою ережесі: <code>P → Q</code> ≡ <code>¬P ∨ Q</code>. Ақиқат кестесі де сол мәндерді береді.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Де Морган заңы бойынша <code>¬(P ∨ Q)</code> неге тең?","o":["<code>¬P ∨ ¬Q</code>","<code>P ∧ Q</code>","<code>¬P ∧ ¬Q</code>","<code>¬P → Q</code>"],"a":2,"e":"«Гарри немесе Рон өтті деген рас емес» дегені «Гарри өтпеді және Рон өтпеді» дегенмен бірдей: <code>¬P ∧ ¬Q</code>.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Білім қорында <code>(A ∨ B)</code> және <code>(¬B ∨ C)</code> бар. Резолюциядан қандай дизъюнкт шығады?","o":["<code>B</code>","<code>A ∧ C</code>","<code>¬A ∨ ¬C</code>","<code>A ∨ C</code>"],"a":3,"e":"<code>B</code> пен <code>¬B</code> қарама-қарсы литералдар. Оларды алып тастап, қалғандарын біріктіреміз: <code>A ∨ C</code>.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"<code>∀x. Person(x) → (∃y. House(y) ∧ BelongsTo(x, y))</code> сөйлемі нені білдіреді?","o":["Бір ғана адам бар және ол үйге тиесілі","Әр адам қандай да бір үйге тиесілі","Әр үйде бір адам бар","Кез келген нәрсе үй болып табылады"],"a":1,"e":"Кез келген <code>x</code> үшін, егер <code>x</code> адам болса, онда <code>x</code> тиесілі болатын үй <code>y</code> бар. Яғни әр адам қандай да бір үйге тиесілі.","l":"1-апта: Білім","u":"ai/lectures/week-1.html#quiz","c":"ai"},{"q":"Жаңбырлы түстердің 80%-ы бұлтты таңнан басталады, күндердің 40%-ында таң бұлтты, 10%-ында түстен кейін жаңбыр жауады. Таң бұлтты болса, түстен кейін жаңбыр жауу ықтималдығы қанша?","o":["0.8","0.2","0.32","0.5"],"a":1,"e":"Байес ережесі: P(rain | clouds) = P(clouds | rain) P(rain) / P(clouds) = 0.8 × 0.1 / 0.4 = 0.2. 0.8 - кері бағыттағы ықтималдық, P(clouds | rain), оны P(rain | clouds) деп шатастыруға болмайды.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Екі әділ сүйек лақтырылды. Қосындысы 7 болу ықтималдығы қандай?","o":["1/36","1/12","1/6","1/2"],"a":2,"e":"36 тең ықтималды әлемнің ішінде қосындысы 7 болатыны алты: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). Демек 6/36 = 1/6.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Мен күндердің 80%-ында балмұздақ, 70%-ында печенье жеймін, ал екеуін де 60%-ында жеймін. Балмұздақ немесе печенье жеу ықтималдығы қанша?","o":["0.9","1.5","0.56","0.6"],"a":0,"e":"Қосу-алып тастау ережесі: P(a ∨ b) = P(a) + P(b) - P(a ∧ b) = 0.8 + 0.7 - 0.6 = 0.9. Алып тастамасақ, 1.5 шығар еді, ал ықтималдық 1-ден аспайды.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Біздің Байес желісінде (Rain → Maintenance, Rain → Train, Maintenance → Train, Train → Appointment) жеңіл жаңбыр, жөндеу жоқ, пойыз кешікті, кездесуді жіберіп алдық деген оқиғаның бірлескен ықтималдығы қалай есептеледі?","o":["P(light) P(no) P(delayed) P(miss)","P(light) P(no | light) P(delayed | no) P(miss | light)","P(light, no) P(delayed, miss)","P(light) P(no | light) P(delayed | light, no) P(miss | delayed)"],"a":3,"e":"Әр түйіннің ықтималдығы тек оның ата-аналарына шартты болады. Train-нің ата-аналары - Rain мен Maintenance, ал Appointment-тің жалғыз ата-анасы - Train. Нәтиже 0.2 × 0.8 × 0.3 × 0.4 = 0.0192.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Бірлескен кестеде P(cloud, rain) = 0.08 және P(¬cloud, rain) = 0.02. Нормалаудан кейін P(C | rain) қандай?","o":["⟨0.08, 0.02⟩","⟨0.5, 0.5⟩","⟨0.8, 0.2⟩","⟨0.4, 0.1⟩"],"a":2,"e":"⟨0.08, 0.02⟩ қосындысы 0.1, сондықтан α = 10. Нормаланған үлестірім ⟨0.8, 0.2⟩ болады. Нормалау қатынасты (4 : 1) сақтап, қосындыны 1-ге жеткізеді.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Қабылдамау семплдеуімен салыстырғанда ықтималдықпен өлшеудің басты артықшылығы не?","o":["Нақты (дәл) жауап береді, жуық емес","Дәлелге сай келмейтін үлгілерді тастамайды: дәлел мәнін бекітіп, үлгіні дәлелдің ықтималдығымен өлшейді","Жасырын айнымалыларды семплдемейді","Байес желісін қажет етпейді"],"a":1,"e":"Қабылдамау семплдеуінде көп үлгі босқа кетеді (әсіресе дәлел сирек болса). Ықтималдықпен өлшеуде дәлел айнымалысына әрдайым бақыланған мән беріледі, ал үлгінің салмағы - сол дәлелдің семплделген ата-аналары берілгендегі ықтималдығы. Ол да жуық әдіс.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Ертеңгі ауа райын тек бүгінгі ауа райына қарап болжайтын модель қандай жорамалға сүйенеді?","o":["Марков жорамалы: қазіргі күй алдыңғы күйлердің тек соңғы тұрақты санына (мұнда біреуіне) тәуелді","Күнделікті ауа райы өзара тәуелсіз","Ауа райы жасырын, оны ешқашан бақылай алмаймыз","Ертеңгі ауа райы өткен жылдың бүкіл деректеріне тәуелді"],"a":0,"e":"Бұл Марков жорамалы. Ол есепті орындалатын етеді, өйткені бүкіл тарихты есептемейміз. Мұнда оқиғалар тәуелсіз емес (ертеңгі күн бүгінгіге байланысты), ал ауа райы бақыланады.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Ғимаратқа қолшатырмен келген адамдарды санайтын камера арқылы сырттағы ауа райын анықтағымыз келеді. Бұл жасырын Марков моделінде жасырын күй пен бақылау қайсысы?","o":["Жасырын күй - қолшатыр, бақылау - ауа райы","Екеуі де ауа райы","Жасырын күй - камера, бақылау - адам саны","Жасырын күй - ауа райы, бақылау - қолшатырдың бар-жоғы"],"a":3,"e":"Біз ауа райын тікелей көрмейміз, ол жасырын күй. Бізде тек қолшатыр туралы бақылау бар. Сенсор моделі P(бақылау | жасырын күй), мысалы P(umbrella | rain) = 0.9.","l":"2-апта: Белгісіздік","u":"ai/lectures/week-2.html#quiz","c":"ai"},{"q":"Төбеге өрмелеу алгоритмі қай кезде тоқтайды?","o":["Мақсатқа дейінгі ең қысқа жол табылғанда","Барлық күй қарап шығылғанда","Ең жақсы көрші ағымдағы күйден жақсы болмағанда","Температура нөлге жеткенде"],"a":2,"e":"Төбеге өрмелеу тек көршілерді қарайды. Ешбір көрші жақсырақ болмаса, ағымдағы күйді қайтарады, бұл жергілікті максимум/минимум болуы мүмкін.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"Күйдіру имитациясында температура <em>T</em> жоғары, ал көрші нашар (ΔE &lt; 0). Нашар көршіге көшу ықтималдығы e<sup>ΔE/T</sup> туралы не айтуға болады?","o":["1-ге жақын: ыстық кезде нашар көршіге көшуге бейім","0-ге жақын: ыстық кезде ешқашан көшпейді","Әрдайым дәл 0,5","Температураға тәуелсіз"],"a":0,"e":"T үлкен болса, ΔE/T 0-ге жақындайды, ал e<sup>0</sup> = 1. Температура төмендеген сайын ықтималдық азаяды.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"Мына шектеулердің қайсысы <em>унарлы</em>?","o":["A ≠ B","5x₁ + 2x₂ ≤ 20","A мен B пәні бір күнге түспейді","A пәні дүйсенбіде болмайды"],"a":3,"e":"Унарлы шектеу тек бір айнымалыға қатысты ({A ≠ Mon}). A ≠ B екі айнымалыны байланыстырады, сондықтан ол бинарлы.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"A: {Tue, Wed}, B: {Wed}, шектеу A ≠ B. A-ны B-ге қатысты доға-келісімді ету үшін не істейміз?","o":["B-ның доменінен Wed-ті аламыз","A-ның доменінен Wed-ті аламыз","A-ның доменінен Tue-ді аламыз","Ештеңе істемейміз, A қазірдің өзінде келісімді"],"a":1,"e":"A = Wed болса, B-ге мән қалмайды. Сондықтан Wed-ті A-дан алып тастаймыз. Revise тек бірінші айнымалының (X) доменін өзгертеді.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"AC-3-те X-тің домені өзгерген соң, кезекке қандай доғалар қосылады?","o":["Есептегі барлық доға қайтадан","(X, Y) доғасының өзі","Әр Z үшін (Z, X), мұнда Z - X-тің Y-тен басқа көршісі","Ештеңе қосылмайды"],"a":2,"e":"X-тің мәндері азайғандықтан, оның көршілері X-ке сүйеніп тұрған мәндерін жоғалтуы мүмкін. Сондықтан (Z, X) доғаларын қайта тексереміз.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"Кері іздеуде барлық айнымалыға мән берілмей, ең бірінші айнымалының барлық мәні сәтсіз болса, бұл нені білдіреді?","o":["Шектеулерді қанағаттандыратын шешім жоқ","Алгоритмді кездейсоқ қайта бастау керек","Ең жақсы жергілікті шешім табылды","Температураны көтеру керек"],"a":0,"e":"Кері қайту ең бірінші айнымалыға дейін жетіп, барлық мән сынап болса, барлық мүмкін меншіктеу тексерілген: шешім жоқ, функция <em>failure</em> қайтарады.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"Домендері бірдей үлкен айнымалылардың ішінде E-нің көршілері басқаларынан көп (дәрежесі жоғары). Қай эвристика E-ні таңдайды?","o":["MRV","LCV","Стохастикалық төбеге өрмелеу","Дәреже эвристикасы"],"a":3,"e":"MRV доменнің өлшеміне қарайды, ал домендер тең. Тең түскенде дәреже эвристикасы көршісі ең көп айнымалыны таңдайды. LCV айнымалыны емес, мәнді таңдайды.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"C айнымалысына Tue берсек B, E және F-тің мәндері азаяды, ал Wed берсек тек B мен E-нікі азаяды. LCV қайсысын таңдайды?","o":["Tue, себебі ол көбірек айнымалыға әсер етеді","Wed, себебі ол ең аз айнымалыны шектейді","Кез келгенін, олар тең","Екеуін де қабылдамайды"],"a":1,"e":"LCV (ең аз шектейтін мән) көрші айнымалыларға мүмкіндікті көбірек қалдыратын мәнді таңдайды.","l":"3-апта: Оңтайландыру","u":"ai/lectures/week-3.html#quiz","c":"ai"},{"q":"Белгісіз нүктеге ең жақын бақылау қызыл. Одан кейінгі екі жақын көрші көк. <code>k = 3</code> болғанда нүкте қандай түске боялады?","o":["Қызыл, себебі ең жақыны қызыл","Көк, себебі 3 көршінің екеуі көк","Екі түс те тең, сондықтан бағдарлама қате береді","Түсі кездейсоқ таңдалады"],"a":1,"e":"k ең жақын көрші көршілердің көпшілік дауысын алады: екі көк бір қызылдан артық. Ең жақын көршінің бір өзі шешпейді.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Перцептрон үшін <code>w₁ = 0.4</code>, <code>α = 0.5</code>, <code>x₁ = 2</code>. Бақыланған мән <code>y = 1</code> (<code>Rain</code>), ал модель <code>h(x) = 0</code> деп болжады. Ереже бойынша <code>w₁</code> қандай болады?","o":["0.4, өзгермейді","-0.6","0.9","1.4"],"a":3,"e":"<code>w₁ ← 0.4 + 0.5 · (1 - 0) · 2 = 1.4</code>. Төмен болжағанда (<code>y - h(x) = 1</code>) салмақ артады. Өзгермеу болжам дұрыс болғанда ғана болар еді.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Төмендегі тапсырмалардың қайсысы <em>регрессияға</em> жатады?","o":["Ертеңгі температураны градуспен болжау","Хат спам немесе спам емес екенін анықтау","Банкноттың шынайы не жалған екенін анықтау","Ертең жаңбыр жауады не жаумайды деп болжау"],"a":0,"e":"Регрессияның шығысы үздіксіз сан (температура). Қалған үшеуінің шығысы дискретті екі нұсқа: бұл жіктеу.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Нақты мәндер <code>[10, 20]</code>, болжамдар <code>[12, 15]</code>. L₁ және L₂ шығындарының қосындысы қандай?","o":["L₁ = 3, L₂ = 9","L₁ = 7, L₂ = 7","L₁ = 7, L₂ = 29","L₁ = 29, L₂ = 7"],"a":2,"e":"L₁ = |10-12| + |20-15| = 2 + 5 = 7. L₂ = 2² + 5² = 4 + 25 = 29. Үлкен қателік (5) квадраттағанда қатты өседі: сондықтан L₂ ауытқуларды қаттырақ жазалайды.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Модель оқыту деректерінде 100%, ал оқытуда қолданылмаған тест деректерінде 60% дәлдік көрсетті. Не болды?","o":["Модель тым қарапайым, оны күрделендіру керек","Модель артық үйренген: оқыту деректерін жаттап алған, жалпыламайды","Тест деректері қате, ескермеуге болады","Бұл өте жақсы нәтиже, ештеңе істеудің қажеті жоқ"],"a":1,"e":"Оқыту мен тест нәтижелерінің арасындағы үлкен алшақтық - артық үйренудің басты белгісі. Оны регуляризация және кросс-валидация арқылы бақылайды.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Q-оқытуда <code>Q(s, a) = 0</code>, <code>α = 0.5</code>, жаңа әрекеттен кейінгі сыйақы <code>-1</code>, болашақ сыйақы бағасы <code>0</code>. Жаңартудан кейін <code>Q(s, a)</code> неге тең?","o":["-1","0","-0.5","0.5"],"a":2,"e":"<code>Q ← 0 + 0.5 · ((-1 + 0) - 0) = -0.5</code>. α = 1 болса ғана жаңа баға ескіні толық алмастырар еді (-1). α = 0.5 кезінде қадам жартылай ғана жасалады.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"ε-ашкөз алгоритмде <code>ε = 0.1</code>. Бұл нені білдіреді?","o":["Агент әрқашан ең жақсы әрекетті таңдайды","Агент 90% жағдайда кездейсоқ жүреді","Оқу коэффициенті 0.1-ге тең","Агент шамамен 10% жағдайда кездейсоқ әрекет жасайды (зерттейді), қалғанында ең жақсысын таңдайды (пайдаланады)"],"a":3,"e":"ε ықтималдығымен кездейсоқ жүріс (зерттеу), 1-ε ықтималдығымен ең жақсы жүріс (пайдалану). ε = 0 болса, алгоритм таза ашкөз болып, жаңа жолдарды ешқашан сынамайды.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"Қайсысы k-means кластерлеуін (бақылаусыз оқыту) дұрыс сипаттайды?","o":["Белгілер жоқ; алгоритм нүктелерді жақын орталыққа бөліп, орталықтарды жылжытады және ештеңе өзгермей қалғанда тоқтайды","Әр нүктенің дұрыс жауабы алдын ала беріледі, алгоритм соны жаттайды","Алгоритм әр қадамда сыйақы мен жаза алады","Кластер саны <code>k</code>-ны алгоритм өзі автоматты түрде анықтайды"],"a":0,"e":"Бақылаусыз оқытуда тек кіріс бар. Орталықтар кездейсоқ қойылып, нүктелерді бөлу мен орталықты жылжыту қайталанады. <em>k</em>-ны бағдарламашы алдын ала таңдайды.","l":"4-апта: Оқыту","u":"ai/lectures/week-4.html#quiz","c":"ai"},{"q":"«НЕМЕСЕ» амалының нейроны <em>g(-1 + 1·x₁ + 1·x₂)</em> функциясын есептейді, шегі 0. <em>x₁</em> = 0, <em>x₂</em> = 0 болғанда шығыс не болады?","o":["1, өйткені салмақтардың екеуі де 1","0, өйткені қосынды -1, ол шектен төмен","-1, өйткені шығыс әрдайым қосындыға тең","Шығыс анықталмаған, себебі кірістер нөл"],"a":1,"e":"Ығысу -1, ал кірістер 0, сондықтан қосынды -1. Ол шектен (0) төмен, демек <em>g</em> 0 қайтарады. Кірістердің бірі 1 болғанда ғана қосынды 0-ге жетеді.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Қай активация функциясы теріс кірісті 0 етеді, ал оң кірісті өзгеріссіз өткізеді?","o":["Қадамдық функция: ол оң кірісті де 1 етіп қояды","Логистикалық функция: ол теріс кірісті дәл 0 етеді","Кез келген активация функциясы","ReLU"],"a":3,"e":"ReLU = max(0, x). Қадамдық функция тек 0 не 1 береді, ал сигмоид 0-ге өте жақын, бірақ дәл 0 емес мән береді және оң мәнді өзгертеді.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Мына 4×4 матрицаға 2×2 max-pooling қолданылады: <code>[[1, 5, 2, 0], [3, 2, 7, 1], [0, 4, 1, 1], [6, 2, 3, 9]]</code>. Нәтиже қандай?","o":["<code>[[5, 7], [6, 9]]</code>","<code>[[1, 0], [0, 9]]</code>","<code>[[5, 7], [4, 3]]</code>","<code>[[11, 10], [12, 14]]</code>"],"a":0,"e":"Әр 2×2 аймақтан ең үлкен мән алынады: жоғарғы сол жақ {1,5,3,2} → 5; жоғарғы оң {2,0,7,1} → 7; төменгі сол {0,4,6,2} → 6; төменгі оң {1,1,3,9} → 9. Қосынды (d нұсқасы) - average/sum pooling, ал max емес.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Деректер бір түзу сызықпен бөлінбейді (бір топ екіншісін қоршап тұр). Не істейміз?","o":["Бір перцептронды ұзағырақ үйретеміз, ақыры бөледі","Үйрену жылдамдығын (rate) арттырамыз","Кемінде бір жасырын қабаты бар көп қабатты желіні қолданамыз","Dropout қосамыз"],"a":2,"e":"Бір перцептрон тек түзу (сызықты) шекара сыза алады, қанша үйретсек те. Сызықты емес деректер үшін жасырын қабат қажет. Dropout бөлінбейтін деректі бөлмейді, ол артық үйренуге қарсы.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Кері таралу (backpropagation) алгоритмі қай бағытта жұмыс істейді?","o":["Кіріс қабатынан бастап шығысқа қарай, қатені көрмей","Шығыс қабатының қатесінен бастап, қабаттан қабатқа кіріске қарай, әр қабаттың салмақтарын жаңартып","Қабаттарды кездейсоқ ретпен","Тек соңғы қабаттың салмақтарын жаңартып, қалғандарын өзгертпей"],"a":1,"e":"Қате алдымен шығыс бірліктерінде есептеледі, содан кейін қабат сайын алдыңғы қабатқа таратылып, салмақтар жаңартылады. Бұл жасырын қабаттардың салмақтарын да үйретуге мүмкіндік береді.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Үйрету кезінде <code>Dropout(0.5)</code> қолданылды. Үйрету біткеннен кейін, жаңа суретті жіктегенде модельде не болады?","o":["Бірліктердің жартысы әрдайым өшіп тұра береді","Модель қайта үйретіледі","Шығыс қабаты алынып тасталады","Бүкіл желі, барлық бірліктерімен, қайтадан пайдаланылады"],"a":3,"e":"Dropout тек үйрету кезінде желінің бір бірлікке тым тәуелді болуына жол бермеу үшін қолданылады. Үйрету аяқталған соң бүкіл желі жұмыс істейді.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Ядро <code>[[0, -1, 0], [-1, 5, -1], [0, -1, 0]]</code> суреттің барлық пикселі 10 болатын біркелкі бөлігіне қолданылады. Ортаңғы пиксельдің жаңа мәні қандай?","o":["0","50","10","40"],"a":2,"e":"Есептейміз: 5·10 - 4·(1·10) = 50 - 40 = 10. Бұл ядро біркелкі аймақтарды өзгертпейді, тек айырмашылық бар жерлерді күшейтеді. (Шекараны табатын ядро <code>[-1,…,8,…,-1]</code> біркелкі аймақта 0 береді.)","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"Суретті сөйлеммен сипаттайтын жүйе үшін неге рекуррент желі қолайлы?","o":["Шығыс (сөздер тізбегі) ұзындығы өзгереді, ал рекуррент желі өз шығысын қайта кіріс етіп, қажетінше шығыс шығара алады","Себебі ол конволюцияны қолданбайды","Себебі ол градиентті түсуді қажет етпейді","Себебі ол әрдайым тікелей таралатын желіден тезірек үйренеді"],"a":0,"e":"Тікелей таралатын желінің шығыс саны бекітілген. Рекуррент желі шығысын қайтадан пайдаланады, сондықтан тізбектермен (сөйлем, бейне, аударма) жұмыс істей алады.","l":"5-апта: Нейрондық желілер","u":"ai/lectures/week-5.html#quiz","c":"ai"},{"q":"«Colorless green ideas sleep furiously» сөйлемі туралы қайсысы дұрыс?","o":["Синтаксис бойынша да, семантика бойынша да дұрыс","Синтаксис бойынша қате, бірақ мағынасы түсінікті","Синтаксис бойынша дұрыс, бірақ семантикасы (мағынасы) жоқ","Сөздері бар болғандықтан, оны сөздер қапшығы дұрыс деп санайды"],"a":2,"e":"Грамматикасы мінсіз (сын есім, сын есім, зат есім, етістік, үстеу), бірақ мағынасы бос. Құрылым мен мағына бөлек нәрсе.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Мына грамматика бойынша қай сөйлемді талдауға болады?","o":["the car walked the city","car the saw","she saw the the city","walked she saw"],"a":0,"e":"«the car» = NP (D N), «walked the city» = VP (V NP). Мағынасы ақылға сыймайды, бірақ грамматикалық құрылым дұрыс: бұл - CFG-нің мағынаға қарамайтынының мысалы. «the the» екі детерминатив қатар келетін ереже жоқ.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Жеті сөзден тұратын сөйлемде қанша сөздік биграмма болады?","o":["7","8","14","6"],"a":3,"e":"Әр сөз өзінен кейінгі сөзбен жұп құрайды, ал соңғы сөздің «келесісі» жоқ. Сондықтан <i>n</i> сөзден <i>n - 1</i> биграмма шығады: 7 - 1 = 6.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Аңғал Байестегі «аңғалдық» нені білдіреді?","o":["Модель тек оң сөйлемдерге үйретіледі","Сөйлемдегі әр сөздің ықтималдығы басқа сөздерге тәуелсіз деп есептеледі","Байес ережесі қолданылмайды","Сөздердің ретін міндетті түрде ескереді"],"a":1,"e":"Шындығында сөздер бір-біріне байланысты, бірақ тәуелсіздік жорамалы есепті жеңілдетеді, және соған қарамастан нәтиже жақсы.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Лаплас тегістеуі (әр санауышқа 1 қосу) нені болдырмау үшін керек?","o":["Мәтінде тыныс белгілерінің көп болуын","Сөз векторларының тым ұзын болуын","Бір сөз белгілі бір түрдегі сөйлемде кездеспегендіктен, бүкіл көбейтіндінің 0 болып кетуін","Сөйлемнің ұзын болуын"],"a":2,"e":"Егер P(сөз | оң) = 0 болса, көбейтінді толық нөл болады. Тегістеу барлық мәнге «кемінде бір рет кездескен» деп қарауға мәжбүр етеді.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"One-hot ұсынудың басты кемшілігі қандай?","o":["Сөздерді бір-бірінен ажырата алмайды","Тек ағылшын тілінде жұмыс істейді","Векторлары тым қысқа болады","50&nbsp;000 сөзге ұзындығы 50&nbsp;000 векторлар керек және сөздердің ұқсастығын көрсете алмайды"],"a":3,"e":"One-hot әр сөзге бірегей вектор береді (ажырата алады), бірақ вектор ұзын және барлық сөз бір-бірінен бірдей алшақ, «wrote» мен «authored» ұқсас екені көрінбейді.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"word2vec векторларымен «king - man + woman» есептесек, нәтиже векторына ең жақын сөз қандай болады?","o":["queen","man","kings","burritos"],"a":0,"e":"King мен man арасындағы айырма queen мен woman арасындағы айырмаға ұқсас, сондықтан king - man + woman нәтижесі queen-ге жақын. («burritos» - ramen, japan, america мысалынан.)","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Трансформерлер неге рекурренттік желілерден жылдамырақ оқытылады, және позициялық кодтау неге қажет?","o":["Олар сөздерді кезекпен өңдейді, ал позициялық кодтау жылдамдықты арттырады","Барлық сөз бір мезгілде өңделеді (параллель), сондықтан сөз ретін сақтау үшін позициялық кодтау қосылады","Олар назар аударуды қолданбайды, сондықтан жеңіл","Олар тек one-hot векторларымен жұмыс істейді"],"a":1,"e":"Параллель өңдеу жылдамдық береді, бірақ сөз ретін жоғалтуы мүмкін, сондықтан сөздің орны да кодталады. Сонымен қатар self-attention контексті түсіндіреді.","l":"6-апта: Тіл","u":"ai/lectures/week-6.html#quiz","c":"ai"},{"q":"Сурет жүктелмей қалса, оның орнына мәтін көрсететін <code>img</code> атрибуты қайсы?","o":["<code>src</code>","<code>href</code>","<code>alt</code>","<code>lang</code>"],"a":2,"e":"<code>alt</code> суреттің сипаттамасын сақтайды: сурет жүктелмесе немесе экранды дауыстап оқитын бағдарлама қолданылса, соны көрсетеді/айтады.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"Тақырыптың класы бойынша түсі қызыл, ал id бойынша көк деп жазылған. Жол ішіндегі <code>style</code> жоқ. Тақырып қандай түсті болады?","o":["Қызыл, өйткені класс алдымен жазылған","Көк, өйткені id айқындылығы класстан жоғары","Екі түстің қоспасы","Түсі өзгермейді, браузер қате шығарады"],"a":1,"e":"Айқындылық тәртібі: жол ішіндегі стиль, id, class, элемент түрі. Id класстан күштірек, сондықтан көк түс жеңеді.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"<code>ul li { color: blue; }</code> ережесі қолданылса, ішкі нүктелі тізімі бар нөмірленген тізімде қай элементтер көк болады?","o":["Нөмірленген тізімнің барлық элементтері","Тек нөмірленген тізімнің бірінші элементі","Ешқайсысы, себебі селектор қате","Тек <code>ul</code> ішіндегі <code>li</code> элементтері"],"a":3,"e":"Ұрпақ селекторы <code>ul li</code> тек <code>ul</code> ішінде орналасқан <code>li</code> элементтерін таңдайды. <code>ol</code> тікелей балалары көк болмайды.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"<code>button:hover</code> селекторы нені білдіреді?","o":["Меңзер батырма үстінде тұрғанда ғана қолданылатын стиль","Батырма басылып қойғанда ғана қолданылатын стиль","Бетте екі батырма болса қолданылатын стиль","Барлық батырмаға әрдайым қолданылатын стиль"],"a":0,"e":"<code>:hover</code> - псевдокласс: ол элементке белгілі бір жағдайда (меңзер үстінде тұрғанда) қосымша стиль береді.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"<code>&lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;</code> жолының мақсаты қандай?","o":["Беттің атауын телефонның қойындысында көрсету","Мобильді құрылғыға көру аймағын құрылғының еніне тең етіп алуды айту","Бетті автоматты түрде қараңғы режимге ауыстыру","Бетті тек компьютерде ашуға рұқсат ету"],"a":1,"e":"Бұл жол болмаса, телефон өзін кең экран деп есептеп, бетті кішірейтіп көрсетеді. Мета-тег көру аймағының енін құрылғы еніне теңейді.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"<code>display: flex; flex-wrap: wrap;</code> қолданылған контейнерде элементтер қатарға сыймай қалса, не болады?","o":["Артық элементтер жасырылады","Барлық элементтер кішірейіп, қатарға сыйып кетеді","Бетте көлденең айналдыру жолағы пайда болады","Сыймаған элементтер келесі жолға түседі"],"a":3,"e":"Дәл осы <code>flex-wrap: wrap</code> қасиетінің міндеті: сыймаған элементтерді келесі жолға орау.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"Bootstrap-та <code>col-lg-3 col-sm-6</code> класстары бар төрт элемент бір <code>row</code>-да тұр. Шағын экранда нәтиже қандай?","o":["Қатарға екіден, барлығы екі жолда","Төртеуі де бір қатарда","Біреуден төрт жолда","Үшеуі бір қатарда, біреуі келесі жолда"],"a":0,"e":"Шағын экранда әр элемент 6 бағанды алады, 6 + 6 = 12, сондықтан бір жолға екі элемент сыяды. Ал үлкен экранда әрқайсысы 3 бағанды алып, 4 x 3 = 12 болғандықтан бір қатарда тұрады.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"Браузер <code>.scss</code> файлын неге тікелей оқи алмайды және не істеу керек?","o":["<code>.scss</code> файлдары тек Windows-та жұмыс істейді; Mac-қа ауысу керек","Браузер <code>.scss</code> файлын оқи алады, тек <code>&lt;link&gt;</code> қолдану керек","Браузер тек <code>.css</code> таниды, сондықтан <code>sass</code> командасымен <code>.scss</code>-ті <code>.css</code>-ке компиляциялау керек","Sass айнымалыларын браузер қолдамайды, сондықтан оларды қолданбау керек"],"a":2,"e":"Sass - CSS-тен жоғары тіл: браузер оны түсінбейді. Алдымен <code>sass variables.scss:variables.css</code> секілді команданы орындап, CSS файлын аламыз, ал HTML-ге сол CSS-ті қосамыз.","l":"0-апта: HTML және CSS","u":"web/lectures/week-0.html#quiz","c":"web"},{"q":"Ана GitHub-тағы репозиторийдің компьютерінде көшірмесін алғысы келеді. Қай команда керек?","o":["<code>git push</code>","<code>git commit</code>","<code>git clone &lt;сілтеме&gt;</code>","<code>git merge</code>"],"a":2,"e":"<code>git clone</code> қашықтағы репозиторийдің жергілікті көшірмесін жасайды. <code>push</code> керісінше, жергілікті коммиттерді GitHub-қа жібереді.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"Ана жаңа <code>style.css</code> файлын жасап, бұрыннан бар <code>index.html</code> файлын да өзгертті. Содан кейін <code>git commit -am \"стиль\"</code> жазды. Не болады?","o":["Коммит жасалады, бірақ тек <code>index.html</code> өзгерісі кіреді, жаңа файл кірмейді: оған алдымен <code>git add</code> керек еді","Жаңа файл да коммитке кіреді","Файл GitHub-қа автоматты түрде жіберіледі","Git қате шығарып, ештеңе істемейді"],"a":0,"e":"<code>-a</code> тек бұрыннан қадағаланатын файлдардағы өзгерістерді қосады. Жаңа файл үшін алдымен <code>git add</code> орындау қажет.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"<code>git commit</code> жасадыңыз, бірақ GitHub бетінде өзгерісті көрмейсіз. Неге?","o":["Коммит әрқашан бір күннен кейін ғана көрінеді","Репозиторий жеке болғандықтан","Алдымен <code>git log</code> жазу керек","Коммит жергілікті репозиторийде тұр, оны GitHub-қа <code>git push</code> арқылы жіберу керек"],"a":3,"e":"Коммит - жергілікті сурет. GitHub-қа жіберу үшін бөлек <code>git push</code> қажет, <code>git status</code> «ahead by 1 commit» деп еске салады.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"Мына файлда не болды?","o":["Файл зақымданды, оны қайта жүктеу керек","Біріктіру қайшылығы: бір жолды екі адам әртүрлі өзгертті, біреуін таңдап, белгілерді өшіру керек","Git екі нұсқаны сәтті біріктірді","Бұл Git-тің жаңа тармақ жасағаны"],"a":1,"e":"<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code> және <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> белгілері қайшылықты көрсетеді. Қалдыратын бөлікті таңдап, белгілерді өшірген соң, файлды қайта <code>add</code> және <code>commit</code> жасаймыз.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"<code>feature</code> тармағындағы жұмысты <code>main</code>-ге қосу үшін дұрыс ретті таңдаңыз.","o":["<code>git checkout main</code>, сосын <code>git merge feature</code>","<code>git checkout feature</code>, сосын <code>git push main</code>","<code>git merge main</code>, сосын <code>git checkout feature</code>","<code>git branch main feature</code>"],"a":0,"e":"Біріктіру қалдыратын тармақта жасалады: алдымен <code>main</code>-ге ауысамыз, сосын <code>feature</code>-ды соған қосамыз.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"<code>git branch</code> шығысы мынадай болса, сіз қазір қай тармақтасыз?","o":["<code>main</code>","<code>feature</code>","<code>login</code>","Үшеуінде бірден"],"a":2,"e":"Қазіргі тармақтың атының сол жағында жұлдызша (<code>*</code>) тұрады. <code>HEAD</code> дәл соған нұсқап тұр.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"Біреудің ашық репозиторийіне өз түзетуіңізді ұсынғыңыз келеді, бірақ оған жазу рұқсатыңыз жоқ. Қалай жасайсыз?","o":["<code>git reset --hard</code> арқылы репозиторийді өзгертесіз","GitHub Pages арқылы жариялайсыз","Иесінен құпия сөзін сұрайсыз","Репозиторийді форктап, өз көшірмеңізде өзгертесіз де, pull request жібересіз"],"a":3,"e":"Ашық бастапқы кодты жобалардың дәстүрлі жолы осы: fork, өзгерту, pull request. Иесі қарап, қабылдауы немесе қабылдамауы мүмкін.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"Жобаңыздағы кодты екі коммит бұрынғы күйге қайтарғыңыз келеді, ал соңғы екі коммиттегі жұмысты керек етпейсіз. Қай команда сәйкес келеді?","o":["<code>git pull</code>","<code>git reset --hard &lt;керекті коммиттің хэші&gt;</code>","<code>git status</code>","<code>git add .</code>"],"a":1,"e":"<code>git log</code> арқылы керекті коммиттің хэшін тауып, <code>git reset --hard</code> береміз. Соңғы коммиттер тарихтан алынып тасталады, сондықтан абай болу керек.","l":"1-апта: Git","u":"web/lectures/week-1.html#quiz","c":"web"},{"q":"Python-ның интерпретатор екені нені білдіреді?","o":["Бағдарлама алдымен бүтіндей машина кодына аударылып, сосын іске қосылады","Python кодын тек бір рет қана іске қосуға болады","Интерпретатор файлды жол-жолымен оқып, әр жолды орындайды","Бағдарлама жұмыс істеу үшін міндетті түрде интернет керек"],"a":2,"e":"C мен Java-дағыдай бөлек компиляция қадамы Python-да жоқ: интерпретатор кодты тікелей оқып жүре береді.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Қолданушы <code>7</code> деп жазды. <code>num = input(\"Number: \")</code> болғанда, <code>num > 0</code> неге <code>TypeError</code> береді?","o":["<code>input</code> әрқашан <code>str</code> қайтарады, ал жолды бүтін сан <code>0</code>-мен <code>&gt;</code> белгісімен салыстыра алмаймыз","<code>0</code> сан емес","<code>&gt;</code> белгісі Python-да жоқ","<code>num</code> айнымалысы әлі жасалмаған"],"a":0,"e":"Түзету: <code>num = int(input(\"Number: \"))</code>.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Мына код не шығарады?","o":["<code>3</code>","<code>1</code>","Қате (<code>1</code> екі рет қосылды)","<code>2</code>"],"a":3,"e":"Жиын әр мәнді бір рет қана сақтайды, сондықтан <code>1</code> екі рет қосылса да, ішінде <code>{1, 2}</code> ғана бар.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"<code>houses = {\"Harry\": \"Gryffindor\"}</code> болса, <code>houses[\"Harry\"]</code> не береді?","o":["<code>\"Harry\"</code>","<code>\"Gryffindor\"</code>","<code>0</code> индексіндегі элемент","<code>KeyError</code>"],"a":1,"e":"Сөздікте кілт арқылы оның мәнін аламыз. Тізімдегідей нөмір емес, кілт қолданылады.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"<code>Flight(2)</code> рейсіне үш жолаушыны ретімен <code>add_passenger</code> арқылы қостық. Үшінші шақыру не қайтарады?","o":["<code>True</code>","<code>None</code>","<code>False</code>","<code>2</code>"],"a":2,"e":"Екі жолаушыдан кейін <code>open_seats()</code> нөлге тең, <code>not 0</code> - <code>True</code>, сондықтан әдіс <code>False</code> қайтарады.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Декоратор <code>@announce</code> қолданылған <code>hello()</code> шақырылғанда не болады?","o":["Тек түпнұсқа <code>hello</code> орындалады","Орағыш функция орындалады: алдында хабар, ортасында түпнұсқа <code>hello</code>, соңында тағы хабар","Ештеңе болмайды, декоратор функцияны өшіреді","Қате шығады, себебі функцияны өзгертуге болмайды"],"a":1,"e":"<code>@announce</code> деп жазғанда <code>hello</code> аты <code>wrapper</code>-ге ауысады, ал түпнұсқа <code>f</code> ретінде <code>wrapper</code> ішінде шақырылады.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Мына лямбда нені істейді?","o":["Тізімнен «name» кілті бар адамдарды өшіреді","Барлық адамның атын бір жолға біріктіреді","Тізімді үйлері (<code>house</code>) бойынша сұрыптайды","Тізімді әр адамның аты (<code>name</code>) бойынша сұрыптайды"],"a":3,"e":"<code>key</code> әр элементтен сұрыптау үшін қай мәнді алу керегін айтады, лямбда сол мәнді қайтарады.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Қолданушы <code>x</code> үшін <code>cat</code> деп жазса, төмендегі кодта қай ерекше жағдай шығады және оны қайсысы ұстайды?","o":["<code>int(\"cat\")</code> <code>ValueError</code> шығарады, оны <code>except ValueError</code> ұстап, хабар жазады","<code>ZeroDivisionError</code> шығады, оны ешкім ұстамайды","<code>TypeError</code> шығады, <code>except</code> оны ұстамайды","Ештеңе шықпайды, <code>x</code> жол болып қалады"],"a":0,"e":"Сан емес жолды <code>int</code>-ке айналдыру <code>ValueError</code> береді. <code>except ValueError</code> дәл осыны ұстайды.","l":"2-апта: Python","u":"web/lectures/week-2.html#quiz","c":"web"},{"q":"Мына сайттардың қайсысы «динамикалық» деп аталады?","o":["Әр кірген адамға дәл бірдей <code>index.html</code> файлын беретін сайт","Тек CSS-пен безендірілген сайт","Бағдарлама (мысалы, Python) HTML-ді сұрау келген сәтте жасап беретін сайт","Көп суреті бар сайт"],"a":2,"e":"Динамикалық сайтта HTML алдын ала дайын тұрмайды, оны код сұрау кезінде жасайды. Сондықтан мазмұн күн сайын өзгере алады.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Браузер сұрау жіберіп, <code>404</code> күй коды бар жауап алды. Бұл не дегенді білдіреді?","o":["Сервер сұралған бетті таппады, мысалы URL-ге сәйкес жол анықталмаған","Серверде код қатесі шықты","Бәрі жақсы, бет сәтті жүктелді","Пайдаланушының бетке кіруге рұқсаты жоқ"],"a":0,"e":"404 - Not Found. Код қатесі 500 береді, рұқсат жоқ - 403, сәтті жауап - 200.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Жобаның <code>urls.py</code> ішінде <code>path('hello/', include(\"hello.urls\"))</code>, ал қосымшаның <code>urls.py</code> ішінде <code>path(\"david\", views.david, name=\"david\")</code> бар. <code>localhost:8000/hello/david</code> URL-іне кіргенде не болады?","o":["404, өйткені <code>hello/david</code> жобаның <code>urls.py</code> ішінде толық жазылмаған","Django <code>views.index</code> функциясын шақырады","Django <code>admin</code> бетін ашады","Django <code>hello/</code> бөлігін жобада «жеп», қалған <code>david</code> бөлігін қосымшаның <code>urls.py</code> ішінен тауып, <code>views.david</code> шақырады"],"a":3,"e":"Django алдымен жоба деңгейіндегі префиксті сәйкестендіріп, қалған бөлікті <code>include</code> арқылы қосымшаның жолдарымен салыстырады.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"<code>localhost:8000</code> (соңында ештеңесіз) адресіне кіргенде 404 шықты, ал <code>localhost:8000/hello</code> жұмыс істеді. Неге?","o":["<code>runserver</code> дұрыс қосылмаған","Жоба деңгейінде тек <code>admin/</code> және <code>hello/</code> жолдары бар, бос жол үшін ештеңе анықталмаған","Django басты бетті мүлде көрсете алмайды","<code>views.index</code> функциясы қате жазылған"],"a":1,"e":"Django тек анықталған жолдарға жауап береді. Бос жол үшін жобаның <code>urlpatterns</code> тізімінде жол жоқ, сондықтан 404.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Шаблонда <code>&lt;h1&gt;Hello, {{ name }}!&lt;/h1&gt;</code> бар. Көрініс <code>render(request, \"hello/greet.html\", {\"name\": \"Harry\"})</code> шақырды. Браузер нені алады?","o":["<code>&lt;h1&gt;Hello, {{ name }}!&lt;/h1&gt;</code>, ал ауыстыруды браузер жасайды","Қате, өйткені контекст сөздік болмауы тиіс","<code>&lt;h1&gt;Hello, Harry!&lt;/h1&gt;</code>: шаблонды Django серверде өңдеп, дайын HTML жібереді","Тек <code>Harry</code> сөзі"],"a":2,"e":"Шаблон тілі серверде орындалады. Браузерге <code>{{ }}</code> да, <code>{% %}</code> да жетпейді, тек дайын HTML барады.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Формадан <code>{% csrf_token %}</code> жолын алып тастап, POST жібердік. Не болады және неге?","o":["Django сұрауды қабылдамайды (403), себебі сұраудың сіздің сайтыңыздан келгенін растайтын токен жоқ","Бәрі қалыпты жұмыс істейді, токен тек әдемілік үшін","Форма <code>GET</code> болып жіберіледі","Деректер сессияға жазылмайды, бірақ сұрау өтеді"],"a":0,"e":"CSRF токені зиянды сайттан келген жалған сұрауларды тоқтатады. Токенсіз POST ортаңғы қабатта бұғатталады.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Пайдаланушы бос не жарамсыз форма жіберді, <code>form.is_valid()</code> нәтижесі <code>False</code>. Лекциядағы <code>add</code> функциясы не істейді?","o":["Тапсырманы бәрібір тізімге қосады","Пайдаланушыны бірден тізім бетіне қайта бағыттайды","<code>500</code> қатесін қайтарады","<code>add.html</code> бетін пайдаланушы жіберген <code>form</code> объектісімен қайта көрсетеді, ол енгізгенін көріп, түзете алады"],"a":3,"e":"Тек жарамды форма ғана тізімге жазылып, қайта бағыттауға әкеледі. Әйтпесе бет қайта көрсетіледі.","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"Тапсырмалар жаһандық <code>tasks = [...]</code> тізімінде сақталған. Айгүл мен Данияр бір серверге кірді. Айгүл «сүт алу» тапсырмасын қосты. Данияр тізімді ашса, не көреді және мәселені не шешеді?","o":["Данияр бос тізім көреді; шешімі - <code>HttpResponse</code> қолдану","Данияр да «сүт алу» тапсырмасын көреді, себебі тізім ортақ; шешімі - <code>request.session[\"tasks\"]</code> арқылы әр пайдаланушыға жеке тізім беру","Данияр қате алады; шешімі - <code>{% for %}</code> циклын өзгерту","Данияр көрмейді; шешім қажет емес"],"a":1,"e":"Жаһандық айнымалы бүкіл серверге ортақ. Сессия әр кіру үшін жеке деректі сақтайды (алдымен <code>python manage.py migrate</code> керек).","l":"3-апта: Django","u":"web/lectures/week-3.html#quiz","c":"web"},{"q":"<code>flights</code> кестесінде <code>origin</code>, <code>destination</code>, <code>duration</code> бағандары бар. Қай сұрау ұзақтығы 500-ден асатын рейстердің <em>тек</em> шығу қалаларын қайтарады?","o":["<code>SELECT * FROM flights WHERE duration &gt; 500;</code>","<code>SELECT origin WHERE duration &gt; 500;</code>","<code>SELECT origin FROM flights WHERE duration &gt; 500;</code>","<code>SELECT duration FROM flights WHERE origin &gt; 500;</code>"],"a":2,"e":"Қай бағанды алатынымызды <code>SELECT</code>-тен кейін, қай кестеден алатынымызды <code>FROM</code>-нан кейін, ал жолдарды сүзу шартын <code>WHERE</code>-нан кейін жазамыз. Жұлдызша барлық бағанды қайтарар еді.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"Мына команда нені жояды?<br><code>DELETE FROM flights;</code>","o":["<code>flights</code> кестесіндегі барлық жолды, ал кестенің өзі қалады","Тек бірінші жолды","Ештеңені, себебі <code>WHERE</code> жоқ","Бүкіл дерекқор файлын"],"a":0,"e":"<code>WHERE</code> болмаса, команда кестедегі барлық жолға қолданылады. Сондықтан <code>DELETE</code> және <code>UPDATE</code> алдында шартты <code>SELECT</code> арқылы тексерген жөн.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"Бір адам көп рейсте ұша алады, бір рейсте көп адам болады. Мұндай байланыс қалай жүзеге асады?","o":["<code>flights</code> кестесіне <code>person_id</code> бағанын қосамыз","<code>people</code> кестесіне барлық рейсті үтірмен бір жолға жазамыз","Әр адамға жеке кесте жасаймыз","Адам id-і мен рейс id-ін жұптайтын ассоциация кестесін (<code>passengers</code>) жасаймыз"],"a":3,"e":"Көп-көпке қатынасы бір ғана сыртқы кілтпен сипатталмайды: ортада жұптарды сақтайтын ассоциация кестесі керек. Django-да мұны <code>ManyToManyField</code> өзі жасайды.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"<code>flights JOIN passengers ON passengers.flight_id = flights.id</code> сұрауында ешқандай жолаушысы жоқ рейс нәтижеде қалай болады?","o":["<code>NULL</code> жолаушымен көрінеді","Көрінбейді, өйткені бұл INNER JOIN және сәйкестігі жоқ жолдар алынып тасталады","Қате шығады","Оның <code>id</code>-і 0 болады"],"a":1,"e":"INNER JOIN екі жақта да сәйкестігі бар жолдарды ғана қалдырады. Сәйкестіксіз рейсті де көру үшін <code>LEFT JOIN</code> қолдану керек.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"Login формасына хакер <code>harry\" --</code> деп жазды. Не себепті ол құпиясөзсіз кіре алады?","o":["<code>--</code> жолды жасырады да, дерекқор өшіп қалады","SQL құпиясөзді мүлде тексермейді","<code>--</code> SQL-де комментарий, сондықтан <code>AND password = ...</code> бөлігі орындалмай қалады","<code>harry</code> әрқашан админ болады"],"a":2,"e":"Енгізілген мәтін код ретінде қабылданды. Қорғану: escape-таңбалар немесе Django модельдері сияқты абстракция қабаты.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"Django-да <code>models.py</code> өзгертілді. Дерекқор жаңаруы үшін қай ретпен команда беру керек?","o":["Алдымен <code>makemigrations</code>, сосын <code>migrate</code>","Алдымен <code>migrate</code>, сосын <code>makemigrations</code>","Тек <code>runserver</code> жеткілікті","Тек <code>makemigrations</code> жеткілікті, ол дерекқорды да жаңартады"],"a":0,"e":"<code>makemigrations</code> өзгеріс жоспарын (миграция файлын) жасайды, ал <code>migrate</code> оны дерекқорда орындайды. Біріншісінсіз екіншісінің орындайтыны жоқ.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"<code>Flight</code> моделінде <code>origin = models.ForeignKey(Airport, on_delete=models.CASCADE, related_name=\"departures\")</code> бар. <code>astana</code> - <code>Airport</code> объектісі. Астанадан ұшатын рейстерді қалай аламыз?","o":["<code>astana.origin.all()</code>","<code>Flight.departures(astana)</code>","<code>astana.flights.all()</code>","<code>astana.departures.all()</code>"],"a":3,"e":"<code>related_name</code> кері бағытта іздеудің атын береді: әуежай объектісінен оны шығу орны ретінде алатын рейстерге <code>departures</code> арқылы жетеміз.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"Банк шотында 150 бар. Екі құрылғыдан бір мезгілде 100 алуға тырыстық, ал екеуі де сәтті болды. Бұл қандай осалдық және оған қарсы қандай шара бар?","o":["SQL инъекциясы; escape-таңбалар","Жарыс жағдайы; дерекқорды (не әрекетті) құлыптау","Индекс жетіспеуі; <code>CREATE INDEX</code>","Көп-көпке қатынасы; ассоциация кестесі"],"a":1,"e":"Екі сұрау бір мезгілде қалдықты оқып, екеуі де «жеткілікті» деп шешті. Бұл жарыс жағдайы. Бір транзакция біткенше екіншісін күттіру (құлып) оны болдырмайды.","l":"4-апта: SQL, модельдер, миграциялар","u":"web/lectures/week-4.html#quiz","c":"web"},{"q":"<code>button.onclick = count;</code> мен <code>button.onclick = count();</code> жолдарының айырмашылығы неде?","o":["Айырмашылық жоқ, жақша міндетті емес","Біріншісі функцияны «түйме басылғанда шақыр» деп береді, екіншісі функцияны бірден шақырып, нәтижесін береді","Біріншісі қате береді, екіншісі дұрыс жұмыс істейді","Екіншісі түйме басылған сайын емес, тек бір рет жұмыс істейді, ал біріншісі әр екі секунд сайын"],"a":1,"e":"Жақшасыз <code>count</code> функцияның өзі (мән ретінде), оны браузер кейін шақырады. Жақшамен <code>count()</code> функция дереу орындалады.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"Мына кодтың шығысы қандай? <code>console.log(5 === \"5\", 5 == \"5\");</code>","o":["<code>true true</code>","<code>false false</code>","<code>true false</code>","<code>false true</code>"],"a":3,"e":"<code>===</code> түрді де салыстырады: сан мен жол әртүрлі, сондықтан <code>false</code>. Ал <code>==</code> жолды санға айналдырып, <code>true</code> береді. Сондықтан <code>===</code> қолданған дұрыс.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"Скрипт <code>&lt;head&gt;</code>-те тұр және ішінде <code>document.querySelector('button').onclick = count;</code> бар, бірақ <code>DOMContentLoaded</code> жоқ. Консольде <code>TypeError</code> шықты. Неге?","o":["Код орындалғанда түйме әлі DOM-да жоқ, сондықтан <code>querySelector</code> <code>null</code> қайтарады","<code>onclick</code> деген қасиет жоқ","<code>count</code> функциясы анықталмаған","<code>querySelector</code> тек тақырыптарды ғана табады"],"a":0,"e":"Браузер бетті жоғарыдан төмен оқиды. Скрипт түймеден бұрын орындалса, іздеу ештеңе таппайды. Шешім: кодты <code>DOMContentLoaded</code> оқиғасының ішіне салу.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"Жаңа браузерде <code>localStorage.getItem('score')</code> шақырылды, бұрын ештеңе сақталмаған. Нәтиже қандай?","o":["<code>0</code>","Бос жол <code>\"\"</code>","<code>null</code>","Қате (exception) шығады"],"a":2,"e":"Кілт жоқ болса, <code>getItem</code> <code>null</code> қайтарады. Сол себепті <code>if (!localStorage.getItem('counter'))</code> тексеруі «әлі жоқ па?» дегенді білдіреді.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"<code>fetch(url).then(response =&gt; response.json())</code> жолында <code>response</code> деген не?","o":["Біз <code>let response</code> деп алдын ала жариялайтын айнымалы","<code>.then</code>-ге берілген анонимді функцияның параметрі, жауап келгенде оған сол жауап беріледі","<code>fetch</code> функциясының кілт сөзі","Сервердің IP мекенжайы"],"a":1,"e":"<code>.then</code> аргументі әрдайым функция. Параметрдің атын өзіміз таңдаймыз, оған сұраныстың нәтижесі жауап келгенде беріледі.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"Мына код не істейді? <code>const PI = 3.14; PI = 3;</code>","o":["<code>PI</code> мәні <code>3</code> болады","Екінші жол елеусіз қалады, <code>PI</code> <code>3.14</code> күйінде қалады және ешқандай қате шықпайды","<code>PI</code> массивке айналады","<code>TypeError</code> қатесі шығады: <code>const</code> мәнін өзгертуге болмайды"],"a":3,"e":"<code>const</code> тұрақты анықтайды: оған қайта мән беруге тырысу қате береді. Өзгеретін мән үшін <code>let</code> қолданамыз.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"HTML-де <code>&lt;button data-color=\"red\"&gt;</code> бар. Түйменің <code>button</code> айнымалысында тұрғанда, JavaScript-те <code>\"red\"</code> мәніне қалай қол жеткіземіз?","o":["<code>button.dataset.color</code>","<code>button.data-color</code>","<code>button.style.color</code>","<code>button.value</code>"],"a":0,"e":"<code>data-ЕРКІН_АТ</code> атрибуттары элементтің <code>dataset</code> қасиетінде <code>dataset.ЕРКІН_АТ</code> түрінде көрінеді. <code>style.color</code> элементтің CSS түсін өзгертеді, ал <code>button.data-color</code> JavaScript-те қате өрнек (азайту амалы).","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"<code>setInterval(count, 1000);</code> жолы қандай нәтиже береді?","o":["<code>count</code> функциясы 1000 рет орындалады","<code>count</code> функциясы бір рет, 1000 секундтан кейін орындалады","<code>count</code> функциясы әр 1000 миллисекунд, яғни әр секунд сайын қайталанып орындалады","<code>count</code> функциясы 1000 жолдан тұрады деп белгіленеді"],"a":2,"e":"Екінші аргумент - миллисекундпен өлшенген кідіріс. 1000 мс = 1 секунд. Қайталауды тоқтату үшін <code>clearInterval</code> қолданамыз.","l":"5-апта: JavaScript","u":"web/lectures/week-5.html#quiz","c":"web"},{"q":"SPA-да <code>history.pushState({section: 2}, \"\", \"section2\")</code> шақырылды, URL өзгерді. Бірақ пайдаланушы «Артқа» түймесін басқанда, URL бұрынғыға қайтады да, бет мазмұны өзгермей қалады. Негізгі себеп қандай?","o":["<code>pushState</code> тек бірінші рет қана жұмыс істейді","<code>pushState</code> тек тарихқа жазба қосып, URL-ді өзгертеді; бетті жаңартуды <code>window.onpopstate</code> өңдеушісі жасауы керек, ал ол жазылмаған","Тақырып (екінші аргумент) бос болмауы керек","Күйге нөмірді емес, тек жол беруге болады"],"a":1,"e":"<code>pushState</code> бетті өзгертпейді. Бет мазмұнын біз өзіміз <code>showSection</code> арқылы жаңартамыз. «Артқа» басылғанда <code>onpopstate</code> оқиғасы шығады, ал онда <code>event.state</code> арқылы бұрынғы күйді алып, бетті қайта көрсету керек.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"Терезе биіктігі <code>window.innerHeight</code> = 700, <code>window.scrollY</code> = 1250, ал <code>document.body.offsetHeight</code> = 2000. <code>window.innerHeight + window.scrollY &gt;= document.body.offsetHeight</code> шарты қандай болады?","o":["<code>true</code>, себебі 1250 &gt; 700","<code>true</code>, себебі 700 + 1250 = 1950, бұл 2000-ға жақын","Қате шығады, өйткені үш шама әртүрлі нәрсені өлшейді","<code>false</code>: 700 + 1250 = 1950 &lt; 2000, беттің төменгі шетіне әлі 50 пиксель қалды"],"a":3,"e":"<code>scrollY + innerHeight</code> - терезенің төменгі шетінің құжаттағы орны. Ол құжат биіктігіне тең не одан үлкен болғанда ғана төменге жеттік деген сөз.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"Шексіз айналдыру кодында <code>counter = 1</code>, <code>quantity = 20</code>. Бет жүктелгенде <code>load</code> бір рет шақырылды, пайдаланушы төменге жетіп, екінші рет шақырылды. Екінші <code>fetch</code> қандай URL-ге барады?","o":["<code>/posts?start=21&amp;end=40</code>","<code>/posts?start=20&amp;end=40</code>","<code>/posts?start=1&amp;end=20</code> (қайталанады)","<code>/posts?start=21&amp;end=41</code>"],"a":0,"e":"Бірінші шақыруда <code>start = 1</code>, <code>end = 1 + 20 - 1 = 20</code>, содан кейін <code>counter = end + 1 = 21</code>. Екінші шақыруда <code>start = 21</code>, <code>end = 21 + 20 - 1 = 40</code>.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"<code>h1</code> элементіне <code>grow</code> анимациясы (20px-тен 100px-ке) берілген, бірақ <code>animation-fill-mode: forwards</code> жазылмаған. Анимация аяқталған соң не болады?","o":["Тақырып 100px күйінде қалады","Анимация мүлде басталмайды","Анимация біткен соң тақырып бастапқы өлшеміне (CSS-тегі әдепкі стиліне) секіріп оралады","Анимация шексіз қайталанады"],"a":2,"e":"<code>forwards</code> анимацияның соңғы кадрындағы стильді сақтайды. Онсыз элемент анимациядан кейін алғашқы стиліне оралады.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"Жазбаны жасыру кодында неге <code>element.parentElement.remove()</code> шақыруын тікелей емес, <code>animationend</code> оқиғасының ішінде жазамыз?","o":["<code>remove()</code> тек оқиға ішінде жұмыс істейді","Жазбаны бірден жойсақ, өшіп-кішірею анимациясын көре алмаймыз; жою анимация біткен соң болуы керек","<code>animationend</code> анимацияны тезірек орындатады","Әйтпесе <code>animation-play-state</code> <code>paused</code> болып қалады"],"a":1,"e":"Алдымен <code>animationPlayState = 'running'</code> анимацияны іске қосады. Анимация 2 секундқа созылады, ал <code>animationend</code> оқиғасы оның аяқталғанын хабарлайды. Сол кезде ғана жазбаны DOM-нан жоямыз.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"Төмендегілердің қайсысы <strong>декларативті</strong> жазу стиліне жатады?","o":["<code>let num = parseInt(document.querySelector(\"h1\").innerHTML);</code>","<code>document.querySelector(\"h1\").innerHTML = num;</code>","<code>document.querySelectorAll(\"button\").forEach(...)</code>","<code>&lt;h1&gt;{num}&lt;/h1&gt;</code> (<code>num</code> өзгергенде бет өзі жаңарады)"],"a":3,"e":"Үш бірінші нұсқа - DOM-мен қадам-қадаммен жұмыс істейтін императивті код. React-те тек «<code>num</code> мәнін көрсет» деп сипаттаймыз, ал DOM-ды жаңартуды React өзі жасайды.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"React санауышында түйме басылғанда <code>count = count + 1;</code> деп жазылды (<code>setCount</code> орнына). Нәтиже қандай?","o":["React күйдің өзгергенін білмейді, сондықтан бет қайта салынбайды, экрандағы сан өзгермейді","Сан бір-бірден артады, нәтиже бірдей","<code>count</code> бірден 0-ге оралады","React қате туралы хабарлама көрсетіп, қосымшаны тоқтатады"],"a":0,"e":"Күйді жаңартудың жалғыз жолы - <code>useState</code> қайтарған функцияны (<code>setCount</code>) шақыру. Тікелей өзгерту көрініске жетпейді (біздің кодта <code>count</code> - <code>const</code>, сондықтан бұл консольде қате де шығарар еді).","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"Қосу ойынында <code>updateResponse</code> функциясын былай жазып қойдық: <code>setState({response: event.target.value})</code> (<code>...state</code> жоқ). Пайдаланушы өріске бір әріп тергенде не болады?","o":["Ештеңе өзгермейді","Тек <code>score</code> нөлге қайтады","Күй толық ауысады: енді <code>num1</code>, <code>num2</code> және <code>score</code> жоқ, сондықтан есеп пен ұпай экраннан жоғалып, орнында бос жер қалады (<code>undefined</code>)","React жетпейтін өрістерді автоматты түрде ескі күйден толтырады"],"a":2,"e":"<code>setState</code> күйді қосып емес, <em>толық ауыстырады</em> (<code>useState</code>-ның бұл түрінде). Сондықтан қалған өрістерді сақтау үшін <code>...state</code> жазамыз.","l":"6-апта: Пайдаланушы интерфейстері","u":"web/lectures/week-6.html#quiz","c":"web"},{"q":"<code>assert is_prime(7)</code> жолы орындалғанда <code>is_prime(7)</code> нәтижесі <code>True</code> болды. Не болады?","o":["<code>AssertionError</code> шығады","Экранға <code>True</code> жазылады","Ештеңе болмайды, бағдарлама үнсіз жалғаса береді","Бағдарлама тоқтайды"],"a":2,"e":"<code>assert</code> шарт ақиқат болса үнсіз өтеді, жалған болғанда ғана <code>AssertionError</code> көтереді.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Лекциядағы <code>is_prime</code> функциясында <code>range(2, int(math.sqrt(n)))</code> деп жазылған (соңында <code>+ 1</code> жоқ). Қай тест осы қатені <em>ұстайды</em>?","o":["<code>assertTrue(is_prime(11))</code>","<code>assertFalse(is_prime(1))</code>","<code>assertTrue(is_prime(2))</code>","<code>assertFalse(is_prime(25))</code>"],"a":3,"e":"25 үшін квадрат түбір 5, бірақ <code>range(2, 5)</code> 5-ті қоспайды, сондықтан 25 жай болып шығады. 11, 1 және 2 үшін қате білінбейді.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Selenium-дағы веб-драйвер (<code>webdriver.Chrome()</code>) не үшін қажет?","o":["Компьютерде нағыз браузерді ашып, оны кодтан басқару үшін (бетке өту, түймені басу)","Python кодын JavaScript-ке аудару үшін","Дерекқордың көшірмесін жасау үшін","Тесттерді GitHub-қа жүктеу үшін"],"a":0,"e":"Веб-драйвер браузерді басқарады: бет ашады, <code>driver.title</code> оқиды, <code>click()</code> арқылы түймелерді басады. Сол арқылы клиент жағындағы кодты тексереміз.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"<code>unittest</code> шығысы <code>...F.F</code> болды. Бұл нені білдіреді?","o":["Алты тесттің алтауы да құлады","Алты тесттің төртеуі өтті, екеуі құлады (4-ші және 6-шы орындағылар)","Үш тест өтті, үшеуі өткізіп жіберілді","Бағдарламада синтаксис қатесі бар"],"a":1,"e":"Нүкте - өткен тест, <code>F</code> - құлаған тест; белгілер тесттер іске қосылған ретімен жазылады. Мұнда алты белгінің төртеуі нүкте, 4-ші және 6-шы белгі - <code>F</code>.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Django <code>TestCase</code> тесттерді жүргізгенде неге нақты дерекқорды бұзып алу қаупі жоқ?","o":["Тесттер тек оқу режимінде жұмыс істейді","Django дерекқорды әр тесттен кейін қолмен қайтарып қояды","Тесттер үшін уақытша жаңа дерекқор жасалып, тест біткен соң өшіріледі","Тесттер бос дерекқорға қосылмайды"],"a":2,"e":"Django әр тест іске қосылғанда жеке тестілеу дерекқорын жасайды («Creating test database...») және соңында жояды («Destroying test database...»).","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Модельде <code>return self.origin != self.destination or self.duration &gt; 0</code> жазылған. Қай рейс қате түрде «жарамды» (<code>True</code>) болып шығады?","o":["<code>AAA</code> → <code>AAA</code>, 200 минут","<code>AAA</code> → <code>BBB</code>, 100 минут","Қате ешбір рейсте білінбейді","Тек ұзақтығы 0 рейс"],"a":0,"e":"<code>or</code> болғанда екі шарттың біреуі ақиқат болса жетеді: бірдей аэропорттар жалған, бірақ 200 &gt; 0 ақиқат, нәтиже <code>True</code>. Дұрыс нұсқа <code>and</code> қолданады. <code>AAA</code> → <code>BBB</code>, 100 дұрыстап <code>True</code> болады.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"<code>on: push</code> деп жазылған GitHub Actions жұмыс процесі қашан іске қосылады?","o":["Тек <code>main</code> тармағына біреу pull request ашқанда","Әр күні түнде","Тек қолмен батырма басқанда","Біреу репозиторийге код жібергенде (push жасағанда)"],"a":3,"e":"<code>on</code> кілті жұмыс процесінің қашан іске қосылатынын көрсетеді; <code>push</code> болғанда әр push сайын тесттер автоматты түрде жүргізіледі.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Docker контейнері виртуалды машинадан неге жеңіл?","o":["Контейнерде код мүлдем жоқ","Контейнерлер компьютердің бар операциялық жүйесін бірге қолданады, әрқайсысына толық ОЖ керек емес","Контейнер тек интернетте жұмыс істейді","Контейнердің ішінде Python қолданылмайды"],"a":1,"e":"Виртуалды машина өз операциялық жүйесі бар тұтас виртуалды компьютер. Docker контейнері бар жүйенің ішінде оқшауланған орта жасайды, сондықтан орын аз алады.","l":"7-апта: Тестілеу, CI/CD","u":"web/lectures/week-7.html#quiz","c":"web"},{"q":"Сайтқа келетін сұрау бірнеше есе көбейді. «Бұл серверді екі есе қуатты серверге ауыстырамыз» деген шешім қай масштабтауға жатады және оның басты шектеуі қандай?","o":["Көлденең масштабтау: сервер саны шексіз өсе алады","Автомасштабтау: сервер өздігінен өзгереді","Тік масштабтау: жалғыз сервер қаншалықты қуатты болса да, шегі бар","Кэштеу: сұрау саны азаяды"],"a":2,"e":"Бір серверді күшейту - тік масштабтау. Оның шегі бар, сондықтан көбіне көлденең масштабтау қажет болады.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Жүктеме бөлгіш үш серверге сұрауларды A, B, C, A, B, C... тәртібімен жібереді. Бұл қай әдіс?","o":["Кезекпен (round-robin)","Кездейсоқ (random)","Ең аз қосылым (fewest connections)","Жабысқақ сессиялар (sticky sessions)"],"a":0,"e":"Round-robin серверлерді кезекпен ауыстырады. Ең аз қосылым әдісі әр серверде қанша сұрау барын санау үшін қосымша уақыт жұмсайды.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Қолданушы сайтқа кірді, ал келесі сұрауы басқа серверге түскенде жүйе оны «танымай» қалды. Қай шешімнің кемшілігі - әр сұраумен cookie жіберу және жалған cookie жасау қаупі?","o":["Жабысқақ сессиялар","Дерекқордағы сессиялар","Жүрек соғысы","Клиент жағындағы сессиялар"],"a":3,"e":"Мәліметті браузерде cookie ретінде сақтасақ, ол әр сұраумен бірге жүреді, ал қолданушы оны жалғандауы мүмкін. Жабысқақ сессияда басты қауіп - бір серверге қолданушылар тым көп жиналуы.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Көп бастапқылы (multi-primary) репликацияда қай мәселе туындауы мүмкін, бірақ бір бастапқылыда ол болмайды?","o":["Дерекқордан оқу мүмкін болмайды","Екі дерекқорда бір жолды бір мезгілде әртүрлі өзгерту (жаңарту қақтығысы)","Деректің көшірмесі мүлде болмайды","Жүктеме бөлгіш қажет болмай қалады"],"a":1,"e":"Көп бастапқыда жазу бірнеше дерекқорға мүмкін, сондықтан жаңарту, бірегейлік және жою қақтығыстары болады. Бір бастапқыда жазу тек біреуіне ғана жасалады.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Қолданушы парольді ұмытып, «Парольді қалпына келтір» батырмасын басты. Қауіпсіз жүйе не істейді?","o":["Ескі парольді поштамен жібереді","Парольді хэштен кері қайтарып, көрсетеді","Жаңа пароль жасауға мүмкіндік береді, өйткені ескісін білмейді","Парольді 86400 секундқа кэштейді"],"a":2,"e":"Хэш-функция бір бағытты, сондықтан жүйе нақты парольді білмейді және оны қайтара алмайды. Ескі парольді жіберетін сайт оны ашық мәтінмен сақтап отыр.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"<code>query = f\"SELECT * FROM users WHERE name = '{name}'\"</code> кодында <code>name</code> орнына <code>' OR '1'='1</code> жазылса, не болады?","o":["Шарт әрқашан ақиқат болады және барлық жолдар қайтарылады (SQL-инъекция)","Python қате береді де, сұрау орындалмайды","Дерекқор бұл кіріс үшін ешқандай жол қайтармайды","Тек бір жол қайтарылады"],"a":0,"e":"Қолданушы мәтіні сұраудың бөлігіне айналып, мағынасын өзгертті. Шешім: параметрленген сұрау (<code>?</code>).","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Django-сыз жазылған бетте <code>div.innerHTML = \"Сәлем, \" + name</code> бар, ал <code>name</code> URL-ден алынады. Қандай шабуыл мүмкін және қалай қорғанамыз?","o":["CSRF; формаға токен қосу арқылы","DoS; сұрау жиілігін шектеу арқылы","Фишинг; сілтемені тексеру арқылы","XSS; мәтінді <code>textContent</code> арқылы қою не экрандау арқылы"],"a":3,"e":"Қолданушы мәтінін HTML ретінде қою - XSS-тің классикалық жолы. <code>textContent</code> мәтінді жай мәтін ретінде көрсетеді.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Нағыз банк сайты <code>/transfer</code> үшін тек POST қабылдайды, бірақ CSRF-токені жоқ. Шабуылшының беті сізді қалай алдай алады?","o":["Мүмкін емес: POST сұрауын тек сол сайттың өзі жасай алады","Жасырын өрістері бар форманы <code>onload</code> кезінде автоматты түрде жіберу арқылы","Тек <code>&lt;img src=...&gt;</code> арқылы","Тек HTTPS болмаса ғана"],"a":1,"e":"POST-тың өзі жеткіліксіз. Басқа сайттың беті форманы жасырып, <code>onload</code> кезінде жібере алады, ал браузер банктің cookie-ін қосып жібереді. Токен осыны тоқтатады.","l":"8-апта: Масштабтау, қауіпсіздік","u":"web/lectures/week-8.html#quiz","c":"web"},{"q":"Мына бағдарлама нені шығарады? <code>int a = 7; int b = 2; std::cout &lt;&lt; a / b;</code>","o":["<code>3.5</code>","<code>4</code>","<code>3</code>","<code>3.0</code>"],"a":2,"e":"Екі операнд та <code>int</code>, сондықтан бүтін бөлу жасалады, бөлшек бөлігі тасталады: нәтиже <code>3</code>. Қалдық <code>7 % 2 = 1</code> болар еді.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"<code>g++</code> орындайтын үш қадамның дұрыс реті қайсы?","o":["Компилятор, препроцессор, линкер","Препроцессор, компилятор, линкер","Линкер, компилятор, препроцессор","Препроцессор, линкер, компилятор"],"a":1,"e":"Алдымен препроцессор (<code>#include</code> және т.б.), сосын компилятор (машина коды), ең соңында линкер (бөліктерді жалғау).","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"Төмендегі қате қай түрге жатады? Хабарлама: <code>undefined reference to 'ayagy(int)'</code>","o":["Орындалу қатесі","Препроцессор қатесі","Синтаксистік (компиляция) қатесі","Жалғау (link) қатесі"],"a":3,"e":"«undefined reference» - линкер функцияның анықтамасын таппағанда шығатын жалғау қатесі. Прототип бар, дене жоқ.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"<code>std::cout &lt;&lt; (17 % 5);</code> нені шығарады?","o":["<code>2</code>","<code>3</code>","<code>3.4</code>","<code>5</code>"],"a":0,"e":"<code>%</code> қалдықты береді: 17 = 3 · 5 + 2, сондықтан <code>2</code>.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"Қай жолда қате бар? <code>const int guests = 40;</code> кейін <code>guests = 41;</code> деп жазылған.","o":["Қате жоқ, <code>const</code> тек комментарий","Қате орындалу кезінде ғана шығады","Қате жоқ, мән 41 болады","Компиляция қатесі: <code>const</code> айнымалыға жаңа мән беруге болмайды"],"a":3,"e":"<code>const</code> мәнді өзгертуге тыйым салады. Бұл қате компиляция кезінде-ақ ұсталады, бағдарлама іске қосылмайды да.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"Мына жолда <code>x</code> типі қандай? <code>auto x = 3500 * 40LL;</code> (<code>40LL</code> - <code>long long</code> литералы)","o":["<code>int</code>","<code>long long</code>","<code>double</code>","<code>bool</code>"],"a":1,"e":"<code>int</code> мен <code>long long</code> көбейтілгенде нәтиже кеңірек типке, яғни <code>long long</code>-ға келтіріледі. <code>auto</code> соны қабылдайды.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"<code>-Wall -Wextra</code> жалаулары не үшін керек?","o":["Бағдарламаны жылдамдатады","Бағдарламаның көлемін кішірейтеді","Қателерді автоматты түзетеді","Күмәнді жерлер туралы қосымша ескертулер шығарады"],"a":3,"e":"Бұл жалаулар компиляторды сынаушы қылады: қолданылмаған айнымалы, таңбасы әртүрлі салыстыру сияқты күмәнді жерлерді көрсетеді. Бағдарламаны өзгертпейді және түзетпейді.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"<code>std::string s = \"Қош\";</code> болса, <code>s.size()</code> неге 3-тен үлкен шығады?","o":["Кирилл әріптері UTF-8-де екі байттан, ал <code>size()</code> байтты санайды","<code>size()</code> әрқашан бір артық санайды","Жолдың соңында қосымша бос орын бар","Кирилл әріптері жолға сыймайды"],"a":0,"e":"«Қ», «о» және «ш» - үшеуі де кирилл әріптері, UTF-8-де әрқайсысы екі байттан алады, сондықтан «Қош» үшін <code>size()</code> 6 береді. Бұл тіл ерекшелігі, қате емес.","l":"0-апта: C++-ке кіріспе","u":"cpp/lectures/week-0.html#quiz","c":"cpp"},{"q":"Бағдарлама не шығарады? <code>for (int i = 0; i &lt; 5; i += 2) std::cout &lt;&lt; i;</code>","o":["<code>01234</code>","<code>024</code>","<code>0246</code>","<code>246</code>"],"a":1,"e":"<code>i</code> мәндері 0, 2, 4; 6 &lt; 5 жалған болғандықтан цикл тоқтайды. Бос орынсыз шығарылады: <code>024</code>.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"<code>int x = 3; if (x = 5) std::cout &lt;&lt; \"иә\";</code> кодында не болады?","o":["Ештеңе шықпайды, себебі 3 ≠ 5","Компиляция қатесі","<code>x == 5</code> салыстырылады, жалған","<code>x</code>-ке 5 жазылады, шарт ақиқат, «иә» шығады (және ескерту беріледі)"],"a":3,"e":"<code>=</code> - меншіктеу. Өрнектің мәні 5 (нөл емес), яғни ақиқат. <code>-Wall</code> «suggest parentheses around assignment» деп ескертеді.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"Прототип (<span class=\"term-en\">function prototype</span>) дегеніміз не?","o":["Функцияның аты, параметрлері мен қайтару типін компиляторға алдын ала хабарлайтын жол","Функцияның толық денесі","Функцияны шақыру нұсқауы","Функция ішіндегі жергілікті айнымалы"],"a":0,"e":"Прототип денесіз жарияланым: <code>int f(int x);</code>. Ол функцияны анықтамадан бұрын қолдануға мүмкіндік береді.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"Мына <code>switch</code> не шығарады? <code>int x = 2; switch (x) { case 1: cout &lt;&lt; \"A\"; case 2: cout &lt;&lt; \"B\"; case 3: cout &lt;&lt; \"C\"; break; default: cout &lt;&lt; \"D\"; }</code>","o":["<code>B</code>","<code>BCD</code>","<code>BC</code>","<code>C</code>"],"a":2,"e":"<code>case 2</code>-ке өтеді, «B» шығады; <code>break</code> жоқ, сондықтан <code>case 3</code>-ке құлап «C» шығады; сол жерде <code>break</code> тоқтатады. <code>default</code> орындалмайды.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"<code>void f(int a) { a = a + 1; }</code> функциясын <code>int n = 5; f(n);</code> деп шақырғаннан кейін <code>n</code> неге тең?","o":["6","5","0","Компиляция қатесі"],"a":1,"e":"Параметр мәнмен беріледі: функция көшірмені өзгертеді, <code>n</code> өзгермейді.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"<code>show(7.5)</code> шақырылғанда, <code>show(int)</code> және <code>show(double)</code> қатар бар болса, қайсысы таңдалады?","o":["<code>show(int)</code>, себебі ол бірінші жазылған","Екеуі де шақырылады","Компиляция қатесі: екі нұсқа тұрғанда таңдау мүмкін емес","<code>show(double)</code>, себебі аргумент типі дәл сәйкес келеді"],"a":3,"e":"Компилятор аргумент типіне дәл сәйкес келетін нұсқаны таңдайды (<code>7.5</code> - <code>double</code>).","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"Базалық жағдайсыз жазылған рекурсивті функцияны шақырсақ, не болады?","o":["Стек толып, бағдарлама құлайды","Функция 0 қайтарады","Компилятор рекурсияны автоматты тоқтатады","Бағдарлама тек бір рет орындалады"],"a":0,"e":"Әр шақыру стекте кадр алады, ал шақырулар тоқтамайды. Ақырында стек шегіне жетіп, бағдарлама «stack overflow» немесе «Segmentation fault» қатесімен құлайды.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"<code>int i = 10; do { std::cout &lt;&lt; i; } while (i &lt; 5);</code> нені шығарады?","o":["Ештеңе шықпайды","<code>5</code>","<code>10</code>","Шексіз цикл"],"a":2,"e":"<code>do-while</code> шартты соңында тексереді, сондықтан дене кем дегенде бір рет орындалады: <code>10</code> шығады, сосын <code>10 &lt; 5</code> жалған болғандықтан цикл тоқтайды.","l":"1-апта: Шарттар, циклдер және функциялар","u":"cpp/lectures/week-1.html#quiz","c":"cpp"},{"q":"Бағдарлама не шығарады? <code>int a[4] = {3, 6, 9, 12}; std::cout &lt;&lt; a[a[0] / 3];</code>","o":["<code>3</code>","<code>9</code>","<code>6</code>","<code>1</code>"],"a":2,"e":"<code>a[0] / 3 = 3 / 3 = 1</code>, демек <code>a[1] = 6</code>.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"<code>std::vector&lt;int&gt; v(3, 7); v.push_back(1);</code> кодынан кейін <code>v.size()</code> неге тең?","o":["3","4","7","8"],"a":1,"e":"<code>v(3, 7)</code> - үш элемент (7, 7, 7), <code>push_back</code> төртіншіні қосады: өлшемі 4.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"Қайсысы шекарадан шыққанда ерекше жағдай (exception) лақтырады?","o":["<code>v[10]</code>","<code>v.front()</code>","<code>v.size()</code>","<code>v.at(10)</code>"],"a":3,"e":"<code>at()</code> шекараны тексеріп, <code>std::out_of_range</code> лақтырады. <code>[]</code> тексермейді: анықталмаған мінез.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"Төмендегі кодтан кейін <code>v</code> мәндері қандай? <code>std::vector&lt;int&gt; v = {1, 2, 3}; for (int x : v) x = x * 10;</code>","o":["<code>1 2 3</code>, өйткені <code>x</code> - көшірме","<code>10 20 30</code>","<code>10 2 3</code>","Компиляция қатесі"],"a":0,"e":"<code>int x</code> - көшірме. Көшірмені өзгерту векторға әсер етпейді. Өзгерту үшін <code>int&amp; x</code> керек.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"Selection sort қалай жұмыс істейді?","o":["Көрші элементтерді салыстырып, қате тұрғандарын ауыстырады","Тізімді екіге бөліп, әрқайсысын жеке сұрыптайды","Қалған бөліктен ең кіші элементті тауып, оны келесі орынға қояды","Кездейсоқ ауыстырып, сұрыпталғанша қайталайды"],"a":2,"e":"Selection sort: әр қадамда сұрыпталмаған бөліктің ең кішісін таңдап, бастапқы орынға қояды. Бірінші нұсқа - bubble sort сипаттамасы.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"Екілік іздеуді қолдану үшін негізгі шарт қайсы?","o":["Тізімде тек оң сандар болуы","Тізім сұрыпталған болуы","Тізімнің өлшемі екінің дәрежесі болуы","Тізімде қайталанатын мән болмауы"],"a":1,"e":"Екілік іздеу ортасындағы мәнге қарап жартысын тастайды, бұл тек тізім сұрыпталғанда ғана дұрыс.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"<code>int age; std::string name; std::cin &gt;&gt; age; std::getline(std::cin, name);</code> кодында <code>name</code> неге бос шығуы мүмкін?","o":["<code>getline</code> тек латын әріптерін оқиды","<code>age</code> оқылмай қалады","<code>name</code> типі дұрыс емес","<code>cin &gt;&gt; age</code> Enter-дің жаңа жол таңбасын ағында қалдырады, <code>getline</code> оны бос жол деп алады"],"a":3,"e":"Санды оқығаннан кейін <code>\\n</code> ағында қалады. <code>getline</code> оны бірден көріп, бос жолмен тоқтайды. Шешім: <code>cin.ignore(...)</code>.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"<code>std::string s = \"Қазақ\";</code> болса, <code>s.size()</code> неге тең (UTF-8)?","o":["10","5","6","20"],"a":0,"e":"«Қазақ» - 5 кирилл әрпі, әрқайсысы 2 байт, барлығы 10 байт. <code>size()</code> байтты санайды.","l":"2-апта: Массивтер, жолдар және vector","u":"cpp/lectures/week-2.html#quiz","c":"cpp"},{"q":"Бағдарлама не шығарады? <code>int x = 7; int* p = &amp;x; *p = 9; std::cout &lt;&lt; x;</code>","o":["<code>7</code>","<code>9</code>","Мекенжай","Компиляция қатесі"],"a":1,"e":"<code>p</code> - <code>x</code>-тің мекенжайы. <code>*p = 9</code> сол үйдің ішіндегіні өзгертеді, демек <code>x</code> 9 болады.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"<code>&amp;x</code> өрнегі нені білдіреді?","o":["<code>x</code>-тің мәнін","<code>x</code>-тің көшірмесін","<code>x</code>-тің жадтағы мекенжайын","<code>x</code>-ке көрсететін сілтемені, әрдайым"],"a":2,"e":"Өрнектегі унарлы <code>&amp;</code> - «мекенжайын ал». Жариялауда (<code>int&amp; r = x;</code>) <code>&amp;</code> басқа мағына береді: сілтеме типі.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"Сілтеме мен көрсеткіштің қайсы айырмашылығы дұрыс?","o":["Сілтеме жарияланғанда міндетті түрде мән алады және кейін басқа айнымалыға ауыспайды","Сілтеме <code>nullptr</code> бола алады, көрсеткіш бола алмайды","Көрсеткіш жадта орын алмайды","Сілтемені әрдайым <code>delete</code> арқылы жою керек"],"a":0,"e":"Сілтеме - бір айнымалының мәңгілік екінші аты: бос болмайды, ауыспайды. Көрсеткіш бос болуы және басқа мекенжайға ауысуы мүмкін.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"<code>int* a = new int[5];</code> жадын қалай дұрыс босатамыз?","o":["<code>delete a;</code>","<code>free(a);</code>","<code>a = nullptr;</code>","<code>delete[] a;</code>"],"a":3,"e":"<code>new[]</code> арқылы алынған массив <code>delete[]</code> арқылы қайтарылады. Тек <code>a = nullptr</code> жазу жадты қайтармайды, ол ағуға әкеледі.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"Төмендегі функцияның қатесі қайсы? <code>int* f() { int x = 5; return &amp;x; }</code>","o":["Қате жоқ","Жергілікті айнымалының мекенжайы қайтарылады, ал <code>x</code> функция біткенде жойылады (dangling pointer)","<code>int*</code> қайтару типін қолдануға болмайды","<code>x</code> үймеде тұр, сондықтан ағу болады"],"a":1,"e":"<code>x</code> стекте тұр және <code>f</code> аяқталғанда жойылады. Қайтарылған мекенжай жарамсыз. Компилятор бұл жерде «address of local variable returned» деп ескертеді.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"<code>std::unique_ptr&lt;int&gt; a = std::make_unique&lt;int&gt;(5); std::unique_ptr&lt;int&gt; b = a;</code> нәтижесі қандай?","o":["<code>a</code> мен <code>b</code> екеуі де нысанға ие болады","<code>a</code> бос болады, <code>b</code> ие болады","Компиляция қатесі: <code>unique_ptr</code> көшірілмейді","Орындалу кезінде құлайды"],"a":2,"e":"<code>unique_ptr</code> көшіру конструкторы өшірілген. Иелікті беру үшін <code>std::move(a)</code> жазу керек.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"RAII идеясы қандай?","o":["Ресурсты нысанның ішінде ұстап, нысан жойылғанда оны автоматты қайтару","Барлық көрсеткішті <code>nullptr</code>-ға тең ету","Жадты қолмен ғана басқару","Бағдарламаны жылдамдататын компилятор жалауы"],"a":0,"e":"RAII: ресурсты алу нысанды жасаумен, қайтару деструктормен байланысты. Сондықтан ұмыту мүмкін емес.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"Қайсысын <code>-fsanitize=address</code> тауып бере алады?","o":["Тек синтаксистік қателерді","Логикалық қателерді (дұрыс емес формула)","Тек баяу жұмыс істейтін кодты","Жад ағуын, use-after-free және массивтен шығуды"],"a":3,"e":"AddressSanitizer жад қателерін бағдарлама жұмыс істеп тұрғанда ұстайды: ағу, босатылған жадты қолдану, шекарадан шығу. Логикалық қатені (дұрыс емес есеп) ол көрмейді.","l":"3-апта: Жад, көрсеткіштер және сілтемелер","u":"cpp/lectures/week-3.html#quiz","c":"cpp"},{"q":"Мына код нені береді?","o":["<code>7</code> шығады","Құрастыру қатесі: <code>x</code> жабық (private)","<code>0</code> шығады","Орындау кезінде қате"],"a":1,"e":"<code>class</code>-та әдепкі қолжетімділік <code>private</code>. <code>main</code> класстың мүшесі емес, сондықтан <code>c.x</code>-ке қол жеткізе алмайды. Егер <code>struct C</code> болса, <code>7</code> шығар еді.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"Мына бағдарлама экранға не шығарады?","o":["<code>AB</code>","Ештеңе шықпайды","<code>BA</code>","Құрастыру қатесі"],"a":2,"e":"Өрістер тізімдегі ретпен емес, класта жарияланған ретпен жасалады: <code>b_</code> бірінші, содан кейін <code>a_</code>. Нәтиже <code>BA</code>. Компилятор тек <code>-Wreorder</code> ескертуін береді.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"<code>show(const Account&amp; acc)</code> функциясы ішінде <code>acc.balance()</code> шақырылады. Қатесіз жұмыс істеуі үшін не қажет?","o":["<code>balance()</code> әдісі <code>const</code> болуы керек","<code>balance()</code> әдісі <code>static</code> болуы керек","Параметрдегі <code>&amp;</code> белгісін алып тастау жеткілікті","Бұл мүмкін емес"],"a":0,"e":"<code>const</code> нысанмен тек <code>const</code> әдістерді шақыруға болады. Дұрыс жол - әдіске <code>const</code> қосу, өйткені ол нысанды өзгертпейді. Тек <code>&amp;</code> алып тастау көмектеспейді: <code>const Account acc</code> көшірмесі де <code>const</code> болып қала береді.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"Нәтиже қандай?","o":["<code>10 10</code>","<code>11 11</code>","<code>13 11</code>","<code>13 13</code>"],"a":3,"e":"<code>k</code> - static, барлық нысанға ортақ бір ғана айнымалы. Үш нысан жасалғанда ол үш рет артады: 10 + 3 = 13. <code>x.k</code> пен <code>A::k</code> - бір нәрсе.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"Деструктор қашан шақырылады?","o":["Біз оны қолмен шақырғанда ғана","Нысан көрінетін аймақтан шыққанда, автоматты түрде","Нысан жасалған кезде, конструктордан бұрын","Бағдарлама басталғанда"],"a":1,"e":"Қарапайым (автоматты) нысан үшін деструкторды компилятор нысанның аймағы аяқталғанда өзі шақырады, жасалуға кері ретпен.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"<code>std::cout &lt;&lt; b &lt;&lt; \"\\n\" &lt;&lt; c;</code> деп тізбектеп жазу үшін <code>operator&lt;&lt;</code> қандай типті қайтаруы керек?","o":["<code>void</code>","<code>std::string</code>","<code>std::ostream&amp;</code>","<code>bool</code>"],"a":2,"e":"Әр <code>&lt;&lt;</code> келесі <code>&lt;&lt;</code>-ге ағынды беруі керек, ол үшін ағынға сілтеме қайтарылады. <code>void</code> қайтарса, тізбектеу жұмыс істемейді.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"Мына класта <code>inc</code> нысанды <em>көшірме</em> етіп қайтарады. Нәтиже қандай?","o":["<code>1</code>","<code>3</code>","<code>0</code>","Құрастыру қатесі"],"a":0,"e":"Бірінші <code>inc()</code> түпнұсқа <code>c</code>-ны 1-ге арттырады да, көшірме қайтарады. Келесі екі <code>inc()</code> сол көшірмеге қолданылады. Түпнұсқа <code>c.value()</code> = 1. <code>Counter&amp;</code> қайтарсақ, нәтиже 3 болар еді. Екеуін де орындап тексердік.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"<code>Library</code> класының ішінде <code>std::vector&lt;Book&gt; books_;</code> өрісі бар. Бұл қандай қатынас?","o":["Мұрагерлік (is-a): Library - бұл Book","Статикалық байланыс","Қолжетімділік жоқ байланыс","Композиция (has-a): кітапханада кітаптар бар"],"a":3,"e":"Кітапхана кітап емес, оның құрамында кітаптар бар. Бұл «бар» қатынасы, яғни композиция. Мұрагерлікті «болып табылады» қатынасында қолданамыз.","l":"4-апта: Класстар және нысандар","u":"cpp/lectures/week-4.html#quiz","c":"cpp"},{"q":"Мына бағдарлама не шығарады?","o":["<code>Derived</code>, содан кейін <code>Derived</code>","<code>Base</code>, содан кейін <code>Derived</code>","<code>Base</code>, содан кейін <code>Base</code>","Құрастыру қатесі"],"a":1,"e":"<code>show</code> нысанды мәнмен алады, сондықтан <code>Derived</code> бөлігі кесіліп (slicing), тек <code>Base</code> қалады. Сілтеме арқылы нысанның өзі сақталады, сондықтан <code>Derived</code> шығады. Компилятормен тексердік.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Қай жағдайда виртуалды деструктор міндетті?","o":["Класта өріс көп болса","Класта <code>static</code> әдіс болса","Туынды нысанды базалық көрсеткіш арқылы <code>delete</code> жасағанда","Класс <code>const</code> болғанда"],"a":2,"e":"Деструктор виртуалды болмаса, базалық көрсеткіш арқылы <code>delete</code> тек базалық деструкторды шақыруы мүмкін, ал бұл анықталмаған әрекет және жад ағуы.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Таза виртуалды функциясы бар класс туралы қай пікір дұрыс?","o":["Одан тікелей нысан жасауға болмайды","Оның барлық функциясы <code>static</code> болуы керек","Одан мұрагерлене алмайсыз","Ол <code>final</code> кластың синонимі"],"a":0,"e":"Абстрактілі класс тек базалық түрде қолданылады. Мұрагер таза виртуалды функцияларды қайта анықтағанда ғана нысан жасауға болады.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Туынды класта <code>void speak() override</code> жазылған, ал базада <code>virtual void speak() const</code>. Не болады?","o":["Бәрі дұрыс жұмыс істейді","Тек ескерту шығады, бағдарлама іске қосылады","Орындау кезінде қате шығады","Құрастыру қатесі: <code>marked 'override', but does not override</code>"],"a":3,"e":"Қолтаңба сәйкес емес (<code>const</code> жоқ), сондықтан функция базаны қайта анықтамайды. <code>override</code> дәл осындай қателерді құрастыру кезінде ұстау үшін бар.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Мына нысан жасалғанда экранға не шығады?","o":["<code>Fox Animal Tail</code>","<code>Animal Tail Fox</code>","<code>Tail Animal Fox</code>","<code>Animal Fox Tail</code>"],"a":1,"e":"Алдымен базалық бөлік (<code>Animal</code>), содан кейін туынды класстың өрістері (<code>Tail</code>), ең соңында туынды конструктордың денесі (<code>Fox</code>).","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Rule of Three бойынша қай үштік бірге жазылуы керек?","o":["Конструктор, деструктор, <code>operator&lt;&lt;</code>","Конструктор, <code>virtual</code>, <code>override</code>","Деструктор, көшіру конструкторы, көшіру меншіктеуі","Геттер, сеттер, конструктор"],"a":2,"e":"Ресурс иеленетін класта осы үшеуі бірге анықталады. Жылжыту конструкторы мен жылжыту меншіктеуі қосылса, Rule of Five болады.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"<code>protected</code> өріске кім қол жеткізе алады?","o":["Класстың өзі және оның туынды кластары","Тек класстың өзі","Барлығы, <code>main</code> да","Тек <code>friend</code> емес функциялар"],"a":0,"e":"<code>protected</code> - <code>private</code> пен <code>public</code> арасындағы деңгей: мұрагерлер көреді, сырттағы код көрмейді.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Мына код компиляцияланады ма?","o":["Иә, <code>final</code> тек ескерту береді","Иә, <code>public</code> болғандықтан","Тек <code>-O2</code> болмаса","Жоқ: финал кластан мұрагерлену мүмкін емес"],"a":3,"e":"Компилятор <code>cannot derive from 'final' base 'A'</code> деген қате береді. Мұны нақты тексердік.","l":"5-апта: Мұрагерлік және полиморфизм","u":"cpp/lectures/week-5.html#quiz","c":"cpp"},{"q":"Нәтиже қандай?","o":["<code>11 11 1</code>","<code>11 21 21</code>","<code>11 21 1</code>","Құрастыру қатесі"],"a":2,"e":"Lambda <code>x</code>-тің көшірмесін алды және ол шақырулар арасында сақталады (1 → 11 → 21). Сыртқы <code>x</code> өзгермейді. Компилятормен тексердік: <code>11 21 1</code>.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Өлшем неше болады?","o":["<code>1</code>","<code>2</code>","<code>3</code>","<code>0</code>"],"a":1,"e":"<code>m[\"x\"]</code> жоқ кілтті 0-мен қосады, <code>m[\"y\"] = 5</code> тағы біреуін қосады. <code>count</code> ештеңе қоспайды. Барлығы 2.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"<code>std::list&lt;int&gt; l; std::sort(l.begin(), l.end());</code> неге құрастырылмайды?","o":["<code>list</code> бос болғандықтан","<code>sort</code> тек <code>int</code> типімен жұмыс істейді","<code>#include &lt;list&gt;</code> жетіспейді","<code>list</code> итераторлары кездейсоқ қолжетімді емес; <code>l.sort()</code> керек"],"a":3,"e":"<code>std::sort</code> итераторларды азайтып, секіре алуы керек (random access). Тізімнің итераторы тек алға-артқа жүреді, сондықтан тізімнің өз <code>sort</code> әдісі бар.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Вектор итераторы <code>it = v.begin()</code> алынды, содан кейін <code>v.push_back(...)</code> шақырылды. Не туралы айтуға болады?","o":["<code>it</code> жарамсыз болуы мүмкін, оны қолдану қауіпті","<code>it</code> әрқашан жарамды қалады","<code>it</code> автоматты түрде <code>end()</code> болады","Бағдарлама дереу тоқтайды"],"a":0,"e":"Қосқанда вектор жадты қайта бөлуі мүмкін; сонда барлық итератор, көрсеткіш және сілтеме жарамсыз болады. Нақты тексеруде AddressSanitizer <code>heap-use-after-free</code> көрсетті.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Нәтижесі қандай?","o":["<code>1 2 3 2 4 2</code>","<code>2 2 2</code>","<code>1 3 4</code>","<code>1 3 2 4</code>"],"a":2,"e":"<code>remove</code> керекті элементтерді алға жылжытады, <code>erase</code> қалған құйрықты өшіреді. Барлық 2 алынып, <code>1 3 4</code> қалады.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Қай контейнерде кілт бойынша іздеу орташа есеппен O(1)?","o":["<code>std::map</code>","<code>std::unordered_map</code>","<code>std::list</code>","<code>std::set</code>"],"a":1,"e":"<code>unordered_map</code> хэш-кестеге негізделген, іздеу орташа O(1). <code>map</code> мен <code>set</code> - O(log n), <code>list</code> - O(n).","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Нәтижені болжа:","o":["<code>50 1</code>","<code>0 0</code>","<code>2 0</code>","<code>2 1</code>"],"a":3,"e":"<code>reserve</code> тек сыйымдылықты арттырады, өлшемді емес. Екі элемент қосылғандықтан <code>size()</code> = 2, ал <code>capacity()</code> ≥ 50, сондықтан өрнек 1 (<code>true</code>) береді.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Мына цикл не шығарады?","o":["<code>a1 b2 c3</code>","<code>b2 a1 c3</code>","<code>1a 2b 3c</code>","Құрастыру қатесі"],"a":0,"e":"<code>map</code> кілттерді сұрыптап сақтайды, сондықтан реті a, b, c. Құрылымдық байланыстыру кілт пен мәнді <code>k</code>, <code>v</code> аттарына ашады.","l":"6-апта: STL: контейнерлер, итераторлар, алгоритмдер","u":"cpp/lectures/week-6.html#quiz","c":"cpp"},{"q":"Мына код не береді?","o":["<code>4.5</code>","<code>4</code>","Құрастыру қатесі: <code>T</code> бір мезгілде <code>int</code> және <code>double</code> бола алмайды","<code>3</code>"],"a":2,"e":"Екі аргументтің типі әртүрлі (<code>int</code> және <code>double</code>), ал шаблонда екеуі де <code>T</code>. Компилятор <code>deduced conflicting types</code> қатесін береді. Түзету: <code>maxOf&lt;double&gt;(3, 4.5)</code>.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Ерекше жағдай лақтырылды, бірақ ешбір <code>catch</code> оны ұстамады. Не болады?","o":["Ол үнсіз елене алынады","Бағдарлама <code>std::terminate</code> шақырып, аварияға ұшырайды","Автоматты түрде <code>0</code> қайтарылады","Қате келесі функцияға берілмейді"],"a":1,"e":"Ұсталмаған ерекше жағдай <code>main</code>-нен де шығып кетсе, <code>std::terminate</code> шақырылады. Нәтижесі: «terminate called after throwing an instance of ...».","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"RAII принципі нені білдіреді?","o":["Жадты тек қолмен босату","Барлық қатені <code>catch (...)</code> арқылы ұстау","Класты бірнеше файлға бөлу","Ресурсты конструкторда алып, деструкторда қайтару, сонда ол автоматты босатылады"],"a":3,"e":"RAII ресурс өмірін нысан өміріне байлайды. Ерекше жағдай болса да, деструкторлар шақырылады, сондықтан ресурс ағып кетпейді.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Бағдарлама не шығарады?","o":["<code>+a +b -b -a | ұсталды | соңы</code>","<code>+a +b +c -c -b -a | ұсталды | соңы</code>","<code>+a +b | ұсталды | соңы</code>","<code>+a +b -a -b | ұсталды | соңы</code>"],"a":0,"e":"<code>c</code> жасалмайды, себебі <code>throw</code> одан бұрын. Стек тарқатылғанда локалды нысандар жасалуға кері ретпен жойылады: алдымен <code>b</code>, содан кейін <code>a</code>, сосын <code>catch</code> жұмыс істейді.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Жоқ файлды <code>std::ifstream f(\"joq_file.txt\");</code> деп аштық. Әдепкі баптауда не болады?","o":["Бағдарлама дереу құлайды","Автоматты түрде файл жасалады","Ерекше жағдай лақтырылмайды, ағын «сәтсіз» күйге ауысады (<code>is_open()</code> = <code>false</code>)","<code>std::out_of_range</code> лақтырылады"],"a":2,"e":"Fstream әдепкіде exception лақтырмайды, сондықтан ашылғанын өзіміз тексереміз (<code>if (!f)</code>). Орындаған нәтиже: <code>0 fail</code>.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Екі namespace-те де <code>f()</code> бар, екеуі де <code>using namespace</code> арқылы әкелінген. <code>f()</code> шақырылса, не болады?","o":["Соңғы әкелінген нұсқа шақырылады","Құрастыру қатесі: шақыру екіұшты (ambiguous)","Бірінші әкелінген нұсқа шақырылады","Екеуі де шақырылады"],"a":1,"e":"Компилятор қайсысын таңдау керегін білмейді: <code>call of overloaded 'f()' is ambiguous</code>. Шешім: толық атау <code>a::f()</code>.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Include guard (<code>#ifndef</code>/<code>#define</code>/<code>#endif</code>) не үшін керек?","o":["Header-дің жылдамырақ оқылуы үшін","Функцияларды жасыру үшін","Қателерді ұстау үшін","Бір header бір файлға бірнеше рет қосылса да, мазмұны бір рет қана қосылуы үшін"],"a":3,"e":"Guard болмаса, <code>struct Point</code> екі рет анықталып, <code>redefinition of 'struct Point'</code> қатесі шығады (біз бұны нақты көрдік).","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"<code>g++ main.cpp -o app</code> командасын орындадық, бірақ <code>geometry.cpp</code> қосылмады. Қате қай кезеңде шығады?","o":["Препроцессорда: header табылмайды","Линкерде: <code>undefined reference to ...</code>","Орындау кезінде, бағдарлама іске қосылғанда","Компилятор ескерту береді де, бәрі жұмыс істейді"],"a":1,"e":"Header функцияны жариялайды, сондықтан компиляция өтеді. Бірақ денесі жоқ, сондықтан линкер <code>undefined reference to 'geo::circleArea(double)'</code> қатесін береді.","l":"7-апта: Шаблондар, ерекше жағдайлар, файлдар және қорытынды жоба","u":"cpp/lectures/week-7.html#quiz","c":"cpp"},{"q":"Java бағдарламасын әр жүйеде (Windows, macOS, Linux) өзгертусіз іске қосуға мүмкіндік беретін құрамдас қайсы?","o":["<code>javac</code> компиляторы","JVM (Java виртуалды машинасы)","Scanner класы","<code>main</code> әдісі"],"a":1,"e":"Байт-код жүйеге тәуелсіз, ал оны әр жүйенің өз <strong>JVM</strong>-і сол жүйенің процессорына арнап орындайды. <code>javac</code> тек бастапқы кодты байт-кодқа аударады.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Мына жол не шығарады?","o":["<code>2.5</code>","<code>2</code>","<code>3</code>","Компиляция қатесі"],"a":1,"e":"Екі операнд та <code>int</code>, сондықтан бөлу бүтін болады да, бөлшек бөлігі (0,5) тасталады: нәтиже <code>2</code>.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>1234 5</code>","<code>3345</code>","<code>12345</code>","<code>15</code>"],"a":1,"e":"Солдан оңға: <code>1 + 2 = 3</code>, сосын <code>3 + \"3\"</code> мәтінге айналып <code>\"33\"</code>, одан әрі жалғау жалғасып <code>\"3345\"</code> шығады. Нақты нәтиже: 3345.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Қай жол <strong>компиляция қатесін</strong> береді?","o":["<code>long x = 5;</code>","<code>double y = 7;</code>","<code>int z = 3.7;</code>","<code>char c = 'Қ';</code>"],"a":2,"e":"<code>double</code>-ды <code>int</code>-ке автоматты салуға болмайды (ақпарат жоғалады). Дұрысы: <code>int z = (int) 3.7;</code>. Қалған үшеуі заңды: кеңейту не дәл сәйкес тип.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"<code>javac Main.java</code> командасының нәтижесі не?","o":["Бағдарлама терминалға нәтиже шығарады","<code>Main.class</code> байт-код файлы жасалады","Main.java файлы өшіріледі","JDK нұсқасы шығады"],"a":1,"e":"<code>javac</code> - компилятор: ол <code>.java</code> файлын <code>.class</code> байт-код файлына айналдырады. Іске қосуды <code>java Main</code> орындайды.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>A2</code>","<code>67</code>","<code>C</code>","Компиляция қатесі"],"a":2,"e":"<code>c += 2</code> қысқа жазу ішінде автоматты <code>(char)</code> casting жасайды: <code>'A'</code> (65) + 2 = 67, ол - <code>'C'</code>. Нақты нәтиже: C.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Мына код не істейді?","o":["<code>ArithmeticException</code> лақтырып тоқтайды","Компиляция қатесі","<code>Infinity</code> шығарады","<code>0</code> шығарады"],"a":2,"e":"Нөлге бөлу қатесі тек <em>бүтін</em> бөлуде болады. <code>double</code> бөлуінде нәтиже <code>Infinity</code> болады. Нақты нәтиже: Infinity.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"<code>int jas = sc.nextInt(); String at = sc.nextLine();</code> жазылса және алдымен «19», Enter басылса, <code>at</code> не болады?","o":["Келесі енгізілген сөз","Бос жол (\"\")","<code>null</code>","<code>InputMismatchException</code>"],"a":1,"e":"<code>nextInt()</code> Enter таңбасын оқымай қалдырады, сондықтан <code>nextLine()</code> бірден сол қалдықты (бос жолды) алады. Шешімі - араға қосымша <code>sc.nextLine();</code> қою.","l":"0-апта: Java-ға кіріспе","u":"java/lectures/week-0.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>b</code>","<code>bc</code>","<code>abc</code>","<code>bcd</code>"],"a":1,"e":"<code>n = 2</code> болғанда <code>case 2</code>-ден бастап орындалады; онда <code>break</code> жоқ, сондықтан <code>case 3</code> де орындалып, сол жерде <code>break</code> тоқтатады: <code>bc</code>. Нақты нәтиже: bc.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Мына <code>switch</code> өрнегі не береді?","o":["<code>нөл</code>","<code>бір</code>","<code>басқа</code>","Компиляция қатесі"],"a":1,"e":"<code>7 % 3 = 1</code>, сондықтан <code>case 1</code> таңдалады. Көрсеткілі түрде құлау жоқ. Нақты нәтиже: бір.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Цикл неше рет қайталанады және не шығарады?","o":["3 рет: <code>0 3 6</code>","4 рет: <code>0 3 6 9</code>","3 рет: <code>3 6 9</code>","10 рет"],"a":1,"e":"<code>i</code> мәндері: 0, 3, 6, 9; келесісі 12 &lt; 10 емес, цикл тоқтайды. Нақты нәтиже: 0 3 6 9.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Төмендегі әдіс жұбының қайсысы заңды <strong>overloading</strong>?","o":["<code>int f(int a)</code> және <code>double f(int a)</code>","<code>int f(int a)</code> және <code>int f(int a, int b)</code>","<code>void f(int a)</code> және <code>void f(int b)</code>","<code>int f(int a)</code> және <code>int g(int a)</code>"],"a":1,"e":"Overloading-те аттары бірдей, <em>параметр тізімі</em> (саны не типтері) әртүрлі болуы тиіс. Тек қайтару типі немесе параметр аты әртүрлі болса, бұл - қайталанған жариялау қатесі. Соңғы нұсқада аттар әртүрлі, ол overloading емес.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Мына әдіс компиляцияда қандай қате береді?","o":["Ешқандай қате жоқ","<em>missing return statement</em>","<em>incompatible types</em>","<em>cannot find symbol</em>"],"a":1,"e":"<code>x == 0</code> болғанда әдіс ештеңе қайтармайды; компилятор барлық жолдың <code>return</code>-мен аяқталатынын талап етеді. Шешімі: соңғы <code>else</code> не әдіс соңында <code>return 0;</code>.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"<code>f(4)</code> нәтижесі қандай?","o":["4","10","24","<code>StackOverflowError</code>"],"a":1,"e":"<code>f(4) = 4 + 3 + 2 + 1 + 0 = 10</code>. Базалық жағдай бар (<code>n == 0</code>), әр қадам <code>n</code>-ді кішірейтеді. Нақты нәтиже: 10.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Ішкі циклдегі <code>break</code> қалай әсер етеді? Нәтижесі қандай?","o":["<code>11 21 31</code>","<code>11</code>","<code>11 13 21 23 31 33</code>","Ештеңе шықпайды"],"a":0,"e":"<code>break</code> тек <em>ішкі</em> циклді тоқтатады: әр <code>i</code> үшін тек <code>j = 1</code> басылады (<code>j = 2</code>-де шығады). Сыртқы цикл жалғасады. Нақты нәтиже: 11 21 31.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"<code>do-while</code> циклі туралы қай тұжырым дұрыс? Мына кодта <code>x</code> неше рет шығады?","o":["0 рет, шарт басынан жалған","1 рет, өйткені шарт соңында тексеріледі","5 рет","Шексіз рет"],"a":1,"e":"<code>do-while</code> дененің бір рет орындалуына кепілдік береді. Бір <code>x</code> басылып, <code>i = 11</code>, шарт жалған - цикл аяқталады. Нақты нәтиже: x.","l":"1-апта: Шарттар, циклдер және әдістер","u":"java/lectures/week-1.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>[7]</code>","<code>[0, 7, 0]</code>","<code>[null, 7, null]</code>","Орындау қатесі"],"a":1,"e":"<code>new int[3]</code> барлық ұяшықты <code>0</code>-мен толтырады, сосын <code>a[1]</code> 7 болды. Нақты нәтиже: [0, 7, 0].","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Бұл бағдарлама туралы қай тұжырым дұрыс?","o":["Компиляция қатесі береді","Орындалады, «Дайын» шығады","Орындау кезінде <code>ArrayIndexOutOfBoundsException</code> лақтырады","5-орынды автоматты қосады"],"a":2,"e":"Жарамды индекстер - 0-ден 4-ке дейін. Компилятор индекс мәнін тексермейді, қате орындау кезінде шығады. Нақты хабар: <em>Exception in thread \"main\" java.lang.ArrayIndexOutOfBoundsException: Index 5 out of bounds for length 5</em>.","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>ABC</code>","<code>abcd</code>","<code>abc</code>","<code>ABCd</code>"],"a":2,"e":"<code>String</code> өзгермейді: әдістер жаңа мәтін қайтарады, ал біз оны ешқайда сақтамадық. Нақты нәтиже: abc.","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>1 true</code>","<code>9 true</code>","<code>9 false</code>","<code>1 false</code>"],"a":1,"e":"<code>b = a</code> сілтемені көшіреді: екеуі бір массивке көрсетеді. <code>b[0]</code> өзгерсе, <code>a[0]</code> да өзгереді, <code>a == b</code> ақиқат. Нақты нәтиже: 9 true.","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>true true</code>","<code>true false</code>","<code>false false</code>","<code>false true</code>"],"a":1,"e":"Java -128...127 аралығындағы <code>Integer</code> нысандарын кэштейді, сондықтан <code>100 == 100</code> ақиқат. 1000 үшін екі бөлек нысан жасалады, <code>==</code> жалған. Нақты нәтиже: true false. Мұндай салыстыруға <code>equals</code> қолданыңыз.","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"<code>t.remove(1)</code> жолынан кейін тізім қандай?","o":["<code>[20, 30]</code>","<code>[10, 20, 30]</code>","<code>[10, 30]</code>","<code>[10, 20]</code>"],"a":2,"e":"<code>remove(int)</code> <strong>индекс</strong> бойынша өшіреді: 1-индексте 20 тұр. Мәнді өшіру үшін <code>remove(Integer.valueOf(20))</code> керек. Нақты нәтиже: [10, 30].","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"<code>ArrayList</code> неге <code>ArrayList&lt;int&gt;</code> түрінде жариялана алмайды?","o":["Өйткені <code>int</code> тым үлкен","Дженерик тек сілтеме типтермен жұмыс істейді; орнына <code>Integer</code> қолданамыз","Өйткені <code>ArrayList</code> тек мәтін сақтайды","Өйткені <code>int</code> аты кілт сөз емес"],"a":1,"e":"Дженерик тип параметрі нысан болуы керек. Сандар үшін wrapper типтер бар: <code>Integer</code>, <code>Double</code>, ... Java примитив ↔ wrapper аралығын autoboxing арқылы өзі аударады.","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Көпіршікті сұрыптаудың <strong>бір өтуінен</strong> кейін массив қандай болады?","o":["<code>[1, 2, 4, 5]</code>","<code>[1, 4, 2, 5]</code>","<code>[1, 5, 4, 2]</code>","<code>[5, 1, 4, 2]</code>"],"a":1,"e":"Бір өту ең үлкен санды (5) соңына жеткізеді, бірақ қалғандарын толық реттемейді. Толық реттеуге тағы өтулер керек. Нақты нәтиже: [1, 4, 2, 5].","l":"2-апта: Массивтер, String және ArrayList","u":"java/lectures/week-2.html#quiz","c":"java"},{"q":"Қай тұжырым <strong>класс</strong> пен <strong>нысан</strong> қатынасын дұрыс сипаттайды?","o":["Класс - нақты дана, нысан - оның сызбасы","Класс - сызба (үлгі), нысан - сол сызбадан жасалған нақты дана","Класс пен нысан - бір ұғым","Нысан тек <code>static</code> өрістерден тұрады"],"a":1,"e":"Класс өрістер мен әдістерді сипаттайды, ал <code>new</code> оператормен жасалған нысанның өз өріс мәндері болады. Бір класстан қанша болса да нысан жасауға болады.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>3 3</code>","<code>1 1</code>","<code>3 1</code>","<code>1 3</code>"],"a":2,"e":"<code>jalpy</code> - <code>static</code>, барлық нысанға ортақ, үш конструктор оны 3-ке жеткізді. <code>ozim</code> - нысан өрісі, әр нысанның өзінде жеке, сондықтан <code>c.ozim = 1</code>. Нақты нәтиже: 3 1.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>P = Nokta@...</code> (хэш-код)","<code>P = (3; 4)</code>","<code>P = 3 4</code>","Компиляция қатесі"],"a":1,"e":"Мәтінге нысанды жалғағанда Java <code>toString()</code>-ті шақырады. Біз оны қайта анықтағандықтан, нәтиже: P = (3; 4).","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Төмендегі кодта қате қайсы? <br><code>class A { private int x = 1; }</code><br><code>class B { void f() { A a = new A(); System.out.println(a.x); } }</code>","o":["Қате жоқ","<code>x</code> өрісі <code>private</code>, оған <code>B</code> класынан тікелей жетуге болмайды - компиляция қатесі","<code>A</code> классында конструктор жоқ","<code>println</code> нысанды шығара алмайды"],"a":1,"e":"<code>private</code> мүше тек өз класының ішінде көрінеді. Компилятор «<em>x has private access in A</em>» хабарын береді. Шешімі - getter қосу: <code>a.getX()</code>.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Мына код не шығарады?","o":["<code>100</code>","<code>250</code>","<code>350</code>","<code>0</code>"],"a":1,"e":"<code>Qala b = a</code> нысанды көшірмейді, тек сілтемені көшіреді. <code>a</code> мен <code>b</code> бір нысанды көрсетеді, сондықтан <code>b</code> арқылы жасалған өзгеріс <code>a</code>-дан да көрінеді. Нақты нәтиже: 250.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Мына <code>record</code> үшін нәтиже қандай?","o":["<code>true true</code>","<code>false false</code>","<code>true false</code>","<code>false true</code>"],"a":2,"e":"Record <code>equals</code>-ті барлық өріс бойынша автоматты жасайды: екі нысан мазмұны бойынша тең (<code>true</code>). Бірақ <code>==</code> сілтемені салыстырады, ал олар әртүрлі нысандар (<code>false</code>). Нақты нәтиже: true false.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Неге <code>static</code> әдіс ішінде <code>this</code> қолдануға болмайды?","o":["Өйткені <code>this</code> тек конструкторда жұмыс істейді","Өйткені <code>static</code> әдіс нысансыз, класқа тиесілі шақырылады, ендеше «осы нысан» деген ұғым жоқ","Өйткені <code>this</code> кілт сөз емес","Өйткені <code>static</code> әдіс өрістерді өзгерте алмайды"],"a":1,"e":"<code>static</code> әдіс нысансыз-ақ шақырылады (<code>Math.sqrt(4)</code>), сондықтан ол нысанның өрістеріне де, <code>this</code>-ке де тікелей жете алмайды. Ол тек static өрістермен жұмыс істей алады.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Қай жағдайда нысан <strong>қоқыс жинаушы</strong> үшін босатуға үміткер болады?","o":["Нысанның <code>toString</code> әдісі шақырылған соң","Оған көрсететін бірде-бір (қолжетімді) сілтеме қалмағанда","Бағдарламада <code>delete</code> жазылғанда","Нысанның барлық өрісі <code>private</code> болғанда"],"a":1,"e":"Java-да нысандарды қолмен өшірмейміз. Егер нысанға стектегі айнымалылардан немесе басқа қолжетімді нысандардан жету мүмкін болмаса (сілтемелер <code>null</code> болды не басқа нысанға ауысты), ол қолжетімсіз және GC оны босата алады.","l":"3-апта: Класстар және нысандар","u":"java/lectures/week-3.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>A</code>","<code>AB</code>","<code>ABC</code>","<code>CBA</code>"],"a":2,"e":"<code>Nemere.ait()</code> алдымен <code>super.ait()</code> шақырады (ол <code>Bala.ait()</code>), ол өз кезегінде <code>Ata.ait()</code>-ты шақырады (\"A\"). Содан соң \"B\" қосылады, одан кейін \"C\". Нәтиже: <code>ABC</code>. Жарияланған тип <code>Ata</code> болса да, нақты нысан <code>Nemere</code> болғандықтан, <code>Nemere</code>-нің нұсқасы орындалады.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Қай жол компиляция қатесін береді (<code>Aspap</code> - абстракт класс, <code>Dombyra extends Aspap</code>, ол барлық абстракт әдісті жазған)?","o":["<code>Aspap a = new Dombyra();</code>","<code>Aspap a = new Aspap();</code>","<code>Dombyra d = new Dombyra();</code>","<code>Object o = new Dombyra();</code>"],"a":1,"e":"Абстракт класстың нысанын <code>new</code> арқылы жасауға болмайды. Бірақ ол айнымалының типі бола алады (1-нұсқа), ал барлық класс <code>Object</code> ұрпағы (4-нұсқа).","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Мына жұптың қайсысында <strong>has-a</strong> қатынасы дұрыс (құрама, мұрагерлік емес)?","o":["<code>KiizUy</code> және <code>Shanyrak</code>","<code>Dombyra</code> және <code>Aspap</code>","<code>Qobyz</code> және <code>Aspap</code>","<code>Taksi</code> және <code>Kolik</code>"],"a":0,"e":"Киіз үйдің шаңырағы бар (has-a), демек <code>KiizUy</code> ішінде <code>Shanyrak</code> өрісі болады. Қалған жұптарда «біріншісі - екіншісінің бір түрі» (is-a), яғни мұрагерлік дұрыс.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Мына код компиляцияда не береді?","o":["Ештеңе, бәрі дұрыс, <code>тық-тық</code> шығады","Қате: интерфейс әдісін жүзеге асырғанда <code>public</code> қою керек (қол жеткізу деңгейі әлсіреген)","Қате: <code>Dombyra</code> абстракт болуы керек","Қате: <code>implements</code> орнына <code>extends</code> жазылуы керек"],"a":1,"e":"Интерфейстің әдістері автоматты <code>public</code>. Класта оны <code>public</code>-сіз жазсақ, қол жеткізуді тарылтқан боламыз, ал мұнда жол жоқ: <code>attempting to assign weaker access privileges; was public</code>. Дұрыс жазылуы: <code>public void ojna()</code>.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>бала бала</code>","<code>ата ата</code>","<code>ата бала</code>","<code>бала ата</code>"],"a":2,"e":"Әдістер динамикалық байланысады: <code>p.get()</code> нақты нысанның (<code>Bala</code>) нұсқасын шақырады және оның <code>t</code> өрісін (\"бала\") қайтарады. Ал <code>p.t</code> өрісі айнымалының жарияланған типі (<code>Ата</code>) бойынша алынады, яғни \"ата\". Нәтиже: <code>ата бала</code>.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"<code>enum Juz { ULY, ORTA, KISHI }</code> берілген. <code>Juz.KISHI.ordinal()</code> неге тең?","o":["0","1","3","2"],"a":3,"e":"<code>ordinal()</code> 0-ден басталады: ULY - 0, ORTA - 1, KISHI - 2.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>үлкен: 43</code> және <code>жол емес</code> (екі жол)","Тек <code>үлкен: 43</code>","Тек <code>жол емес</code>","Компиляция қатесі"],"a":0,"e":"<code>o</code> - <code>Integer</code> 42, 40-тан үлкен, сондықтан <code>n + 1 = 43</code> шығады. Екінші <code>if</code> ішінде <code>o instanceof String</code> жалған, оның терісі ақиқат, сондықтан \"жол емес\" де шығады. Үлгі айнымалысы <code>s</code> бұл жерде қолданылмайды, бұл дұрыс.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"<code>sealed interface Tulga permits Shanyrak, Tortburysh</code> жарияланған. Мына сөйлемнің қайсысы дұрыс?","o":["Кез келген класс <code>Tulga</code>-ны жүзеге асыра алады","<code>permits</code> тізімі тек көмекші түсініктеме, оны компилятор тексермейді","<code>sealed</code> тек <code>enum</code> үшін жұмыс істейді","<code>Tulga</code>-ны тек тізімде аталған типтер жүзеге асыра алады, басқасы қате береді"],"a":3,"e":"<code>sealed</code> иерархияны тұйықтайды: тек <code>permits</code> тізімінде аталған кластар ғана мұра ала алады. Бұл Java 17-де финалды мүмкіндік.","l":"4-апта: Мұрагерлік, интерфейстер және полиморфизм","u":"java/lectures/week-4.html#quiz","c":"java"},{"q":"Мына әрекеттердің қайсысы <code>ArrayList</code>-те O(1) (тұрақты уақыт) болады?","o":["Тізімнің басына элемент қосу","Тізімнен мән бойынша <code>contains</code> іздеу","Индекс бойынша <code>get(i)</code> алу","Тізімнің ортасындағы элементті жою"],"a":2,"e":"<code>ArrayList</code> ішінде массив бар, сондықтан индекс бойынша алу бірден орындалады: O(1). Басына қосу мен ортасынан жою элементтерді жылжытуды қажет етеді (O(n)), ал <code>contains</code> бәрін қарап шығады (O(n)).","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>[5, 3, 1, 5, 3, 4] 6</code>","<code>[1, 3, 4, 5] 4</code>","<code>[5, 3, 1, 4] 4</code>","<code>[1, 3, 4, 5] 6</code>"],"a":1,"e":"<code>Set</code> қайталанатын 5 пен 3-ті қабылдамайды, ал <code>TreeSet</code> элементтерді өсу ретімен сұрыптап ұстайды. Бірегей мәндер: 1, 3, 4, 5, яғни өлшемі 4.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына жолда не қате? <code>List&lt;int&gt; san = new ArrayList&lt;&gt;();</code>","o":["<code>ArrayList</code> импортталмаған","<code>new ArrayList&lt;&gt;()</code> дұрыс жазылмаған","Ештеңе, жол дұрыс","Generic тип параметрі тек сілтеме типі бола алады; <code>int</code> орнына <code>Integer</code> жазу керек"],"a":3,"e":"<code>List&lt;int&gt;</code> компиляция қатесін береді: <code>unexpected type; required: reference, found: int</code>. Дұрысы <code>List&lt;Integer&gt;</code>; <code>int</code> ↔ <code>Integer</code> түрлендіруді Java автоматты жасайды (autoboxing).","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>1 1 2</code>","<code>null 1 2</code>","<code>2 2 2</code>","<code>1 2 2</code>"],"a":0,"e":"<code>put</code> кілт бұрыннан болған болса, ескі мәнді қайтарады (<code>1</code>) және оны жаңасымен (<code>2</code>) ауыстырады. Кілт бірегей, сондықтан <code>size()</code> әлі 1. Соңғы <code>get</code> жаңа мәнді береді: 2.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына кодта қай жол компиляция қатесін береді?","o":["<code>List&lt;? extends Number&gt; l = new ArrayList&lt;Integer&gt;();</code>","<code>Number n = l.get(0);</code>","<code>l.add(5);</code>","Үшеуі де дұрыс"],"a":2,"e":"<code>? extends Number</code> тізімінен оқуға болады (элемент <code>Number</code>-дің ұрпағы), бірақ оған қосуға болмайды: компилятор тізімнің нақты типін (<code>Integer</code> па, <code>Double</code> па) білмейді. Тек <code>null</code> қосуға болады.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>[ай, күн, жер, су]</code>","<code>[су, ай, жер, күн]</code>","<code>[күн, жер, ай, су]</code>","<code>[ай, су, күн, жер]</code>"],"a":3,"e":"Жолдар ұзындығы бойынша сұрыпталады: екі әріптілер (<code>ай</code>, <code>су</code>), сосын үш әріптілер (<code>күн</code>, <code>жер</code>). Сұрыптау тұрақты, сондықтан ұзындығы бірдей элементтер бастапқы ретін сақтайды: <code>ай</code> <code>су</code>-дан бұрын, <code>күн</code> <code>жер</code>-ден бұрын.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>5 3</code> және <code>5 4 1</code>","<code>1 3</code> және <code>1 4 5</code>","<code>1 3</code> және <code>5 4 1</code>","<code>1 2</code> және <code>1 4 5</code>"],"a":1,"e":"<code>PriorityQueue</code> табиғи реттілікте ең кішісін бірінші ұстайды: <code>peek()</code> = 1, өлшемі 3. <code>poll()</code> үш рет шақырылғанда мәндер өсу ретімен шығады: 1, 4, 5.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"<code>equals</code> және <code>hashCode</code> туралы қай сөйлем дұрыс?","o":["<code>equals</code> бойынша тең екі нысанның <code>hashCode()</code> мәні де тең болуы керек","<code>hashCode</code> бірдей болса, нысандар міндетті түрде тең","<code>HashMap</code> кілті үшін <code>hashCode</code> жеткілікті, <code>equals</code> керек емес","Өз кілт класына екеуі де қажет емес, Java өзі жасайды"],"a":0,"e":"Келісім: <code>a.equals(b)</code> ақиқат болса, <code>a.hashCode() == b.hashCode()</code> болуы шарт. Керісінше міндетті емес (<code>Aa</code> және <code>BB</code> хештері бірдей, бірақ жолдар әртүрлі). <code>HashMap</code> алдымен хешпен қорапты табады, содан кейін <code>equals</code> арқылы нақтылайды, сондықтан екеуі де керек. Тек <code>record</code> екеуін де автоматты жасайды.","l":"5-апта: Collections және generics","u":"java/lectures/week-5.html#quiz","c":"java"},{"q":"Мына ерекше жағдайлардың қайсысы <strong>checked</strong> (компилятор өңдеуді талап етеді)?","o":["<code>NullPointerException</code>","<code>ArithmeticException</code>","<code>IllegalArgumentException</code>","<code>IOException</code>"],"a":3,"e":"<code>IOException</code> - <code>Exception</code> ұрпағы, бірақ <code>RuntimeException</code> емес, сондықтан checked: <code>try</code>/<code>catch</code> не <code>throws</code> керек. Қалғандары <code>RuntimeException</code> ұрпақтары, яғни unchecked.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>10</code>","<code>2 10</code>","<code>1 2 10</code>","<code>1 10 2</code>"],"a":2,"e":"<code>return 10</code> орындалғанға дейін <code>finally</code> блогы орындалады. Сондықтан алдымен <code>1 </code>, сосын <code>2 </code> шығады, ал <code>10</code> мәні <code>main</code> ішіндегі <code>println</code> арқылы соңында шығады.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына код компиляцияда не береді?","o":["Қате: <code>unreported exception IOException; must be caught or declared to be thrown</code>","Ештеңе, бағдарлама дұрыс","Қате: <code>Files</code> кластары табылмады","Тек ескерту, бірақ іске қосылады"],"a":0,"e":"<code>Files.readString</code> <code>IOException</code> (checked) лақтыра алады. <code>main</code> оны не <code>catch</code> арқылы ұстамаған, не <code>throws</code> арқылы жарияламаған, сондықтан компилятор кодты қабылдамайды.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына жерде не қате?","o":["<code>oqy</code> әдісін <code>main</code> шақыра алмайды","Екінші <code>catch</code> (<code>IOException</code>) қол жетпейтін: оны алдыңғы <code>catch (Exception e)</code> бұрыннан ұстайды","<code>throws IOException</code> жазбасы артық","Ештеңе қате емес, <code>1</code> шығады"],"a":1,"e":"<code>Exception</code> - <code>IOException</code>-нің ата-класы, сондықтан бірінші <code>catch</code> барлығын ұстайды. Екінші блок ешқашан орындалмайды, сондықтан компилятор <code>exception IOException has already been caught</code> деген қате береді. Реті кері болуы керек: алдымен нақты түр.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>5</code>","<code>2</code>","<code>3</code>","<code>4</code>"],"a":2,"e":"Тізімдегі «а» әрпі бар сөздер: қала, ауыл, дала. «көл» мен «су»-да <code>а</code> жоқ. <code>count()</code> 3 қайтарады.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>10</code>","<code>20</code>","<code>5</code>","<code>-1</code>"],"a":3,"e":"<code>Optional.of(5)</code> - <code>map</code> 10 жасайды, бірақ <code>filter(x -&gt; x &gt; 20)</code> оны өткізбейді, қорап бос болып қалады. <code>orElse(-1)</code> әдепкі мәнді береді: -1.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Қай функционалды интерфейс бір мән қабылдайды, бірақ <strong>ештеңе қайтармайды</strong>?","o":["<code>Predicate&lt;T&gt;</code>","<code>Consumer&lt;T&gt;</code>","<code>Function&lt;T,R&gt;</code>","<code>Supplier&lt;T&gt;</code>"],"a":1,"e":"<code>Consumer&lt;T&gt;</code> әдісі <code>void accept(T)</code>: мәнді «жұтады» (<code>forEach</code> ішінде). <code>Predicate</code> - <code>boolean</code>, <code>Function</code> - нәтиже түрін, <code>Supplier</code> - параметрсіз мән береді.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>O1 O2 тело C2 C1</code>","<code>O1 O2 тело C1 C2</code>","<code>O1 тело C1 O2 C2</code>","<code>тело O1 O2 C2 C1</code>"],"a":0,"e":"Ресурстар жарияланған ретімен ашылады (<code>O1</code>, <code>O2</code>), блок орындалады, ал жабу <em>кері ретпен</em> болады: <code>C2</code>, содан кейін <code>C1</code>.","l":"6-апта: Ерекше жағдайлар, файлдар, lambda және Stream","u":"java/lectures/week-6.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>A</code> және <code>A</code>","<code>main</code> және <code>A</code>","<code>A</code> және <code>main</code>","<code>main</code> және <code>main</code>"],"a":1,"e":"<code>t.run()</code> жаңа ағын ашпайды, кәдімгі әдіс сияқты <code>main</code> ағынында орындалады, сондықтан <code>main</code> шығады. <code>t.start()</code> жаңа ағынды іске қосады, оның аты <code>A</code>. <code>join()</code> оның біткенін күтеді, сондықтан екінші жол <code>A</code>.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"Race condition деген не?","o":["Екі ағынның бір-бірін күтіп мәңгі тұрып қалуы","Ағынның қатемен тоқтауы","Ағындардың өте жылдам жұмыс істеуі","Нәтиже ағындардың орындалу ретіне байланысты болып, ортақ деректі қорғаусыз өзгертуден шығатын қате"],"a":3,"e":"Race condition - ортақ айнымалыны бірнеше ағын қорғаусыз өзгерткенде нәтиженің ағындардың араласу ретіне байланысты болуы. Бірінші нұсқа - deadlock.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"<code>synchronized (qulyp) { ... }</code> не кепілдік береді?","o":["Блок өте жылдам орындалады","Блоктағы код ешқашан қате бермейді","Бір мезгілде тек бір ағын осы құлып нысанымен қорғалған блокқа кіре алады","Блок жаңа ағында орындалады"],"a":2,"e":"<code>synchronized</code> өзара шеттету (<em>mutual exclusion</em>) береді: бір құлыппен қорғалған код бөлігін бір мезгілде бір ағын ғана орындайды. Қалғандары күтеді. Ол жылдамдық не қателерден қорғау кепілдігін бермейді.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>42</code> және <code>true</code>","<code>42</code> және <code>false</code>","<code>13</code> және <code>true</code>","Бағдарлама тоқтамайды, ештеңе шықпайды"],"a":0,"e":"<code>submit(() -&gt; 6 * 7)</code> нәтиже қайтаратын <code>Callable</code> жібереді; <code>f.get()</code> нәтиже (42) дайын болғанша күтеді. <code>shutdown()</code> шақырылғаннан кейін <code>isShutdown()</code> - <code>true</code>.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"<code>t.join()</code> шақыру нені білдіреді?","o":["<code>t</code> ағынын іске қосады","Шақырған ағын <code>t</code> ағыны аяқталғанша күтеді","<code>t</code> ағынын мәжбүрлеп тоқтатады","<code>t</code> ағынына басымдық береді"],"a":1,"e":"<code>join()</code> - шақырған ағынды <code>t</code> біткенше «тоқтатып» қояды. Іске қосу - <code>start()</code>, ал тоқтатуды <code>interrupt()</code> ұсынады (мәжбүрлеп тоқтату жоқ).","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"Maven жобасында JUnit тесттері әдетте қай қалтада тұрады?","o":["<code>src/main/java</code>","<code>target/test</code>","<code>src/test/java</code>","<code>tests</code> (жобаның түбірінде)"],"a":2,"e":"Стандартты Maven құрылымы: негізгі код - <code>src/main/java</code>, тесттер - <code>src/test/java</code>. <code>target</code> - жиналған нәтиже қалтасы, оған қолмен код жазбайды.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"JUnit 5-те әр тесттің алдында орындалатын дайындық әдісін қай аннотация белгілейді?","o":["<code>@BeforeEach</code>","<code>@AfterAll</code>","<code>@Test(before = true)</code>","<code>@Setup</code>"],"a":0,"e":"<code>@BeforeEach</code> әдісі әр <code>@Test</code> алдында орындалады (мысалы, таза <code>Zhurnal</code> нысанын жасау үшін). <code>@AfterAll</code> барлық тесттен кейін бір рет орындалады, ал <code>@Setup</code> JUnit-те жоқ.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"},{"q":"Мына бағдарлама не шығарады?","o":["<code>5 5 6</code>","<code>6 7 7</code>","<code>6 6 6</code>","<code>6 6 7</code>"],"a":3,"e":"<code>incrementAndGet()</code> алдымен 1 қосып, жаңа мәнді (6) қайтарады. <code>getAndIncrement()</code> алдымен ескі мәнді (6) қайтарып, содан кейін 1 қосады (мән 7 болады). Соңында <code>a.get()</code> = 7.","l":"7-апта: Көп ағын, құралдар және қорытынды жоба","u":"java/lectures/week-7.html#quiz","c":"java"}];
